def destroyClient(clientObj):
    if hasattr(clientObj, 'clientID') and clientObj.clientID is not None:
        try:
            clientObj.Send({'DEL': '', 'clientID': clientObj.clientID})
        except:
            pass
        clientObj.clientID = None

