xt: str|!> -> None', faultTolerance=True), 'isEntry': True}], 'QUERY': [{'re': GenerateRE4FunctionCalling('QUERY<!|keywords: str|!> -> str', faultTolerance=True), 'isEntry': True}]}
        self.ACTIONS = {}
        return

    def Recall(self, key: str):
