    @staticmethod
    def get_task_instruction():
        return 'Interact with a household to solve a task. Imagine you are an intelligent agent in a household environment and your target is to perform actions to complete) the task goal. At the beginning of your interactions, you will be given the detailed description of the current environment and your goal to accomplish. A tool will be provided for you to use to submit the action you want to take. This tool is the only tool you should and must take in order to operate any action in the environment. The way you perform action is to place the action chosen by you in the arguments field of your tool call. For each of your turn, you will be given a list of actions which you can choose one to perform in this turn. The action you would like to take should be offered in this format: "the name of your next action", and you should fill it in the argument field of your tool call. Note that you should always call a tool to operate an action from the given choices. After your each turn, the environment will give you immediate feedback based on which you plan your next few steps. if the environment output "Nothing happened", that means the previous action is invalid and you should try more options.\n Reminder:\n1. the action must be chosen from the given available actions. Any actions except provided available actions will be regarded as illegal.\n2. Always call the tool to hand in your next action and think when necessary.'

    def get_prompt(self, filename: str):
        for k, v in self.prefixes.items():
            if filename.startswith(k):
                example = self.prompts[v]
                return deepcopy(example)
        raise Exception(f'unsupported name: {filename}')

    @staticmethod
    def get_available_actions(actions):
        actions = '\n'.join(actions)
        return ' AVAILABLE ACTIONS: ' + actions + '\n'

    def alfworld_run(self, session: Session, env):
        finish_reason = SampleStatus.COMPLETED
        ob, info = self.env.reset_env(env)
        ob = '\n'.join(ob[0].split('\n\n')[1:])
        log_info = {'log': []}
        session.inject(ChatCompletionSystemMessageParam(role='system', content=self.get_task_instruction()))
        init_prompt = 'Here is your task. ' + ob + self.get_available_actions(info.get('admissible_commands', [[]])[0])
        log_info['init_prompt'] = init_prompt
        session.inject(ChatCompletionUserMessageParam(role='user', content=init_prompt))
        for i in range(0, self.max_step):
            output = session.sync_action()
            tool_calls = []
            for message in output.messages:
                tool_calls.extend(message.get('tool_calls', []) or [])
            if not tool_calls:
                finish_reason = SampleStatus.AGENT_VALIDATION_FAILED
                session.inject(ChatCompletionUserMessageParam(role='user', content='No executable tool calls found. Please call a tool instead'))
                session.inject(RewardHistoryItem(reward=0, score=0))
                continue
            try:
                tool_call = tool_calls[0]
                arguments = tool_call['function']['arguments']
                arguments = json.loads(arguments)
                arguments = list(arguments.values())
                call_id = tool_call['id']
                admissible_commands = info.get('admissible_commands', [[]])[0]
                output = arguments[0]
                action = process_action(output, admissible_commands)
            except:
                finish_reason = SampleStatus.AGENT_INVALID_ACTION
                session.inject(ChatCompletionUserMessageParam(role='user', content='No valid tool calls found. Please call a tool instead.'))
                session.inject(RewardHistoryItem(reward=0, score=0))
                continue
            observation, reward, done, info = self.env.step_env(env, action)
            observation, reward, done = (process_ob(observation[0]), info['won'][0], done[0])
            session.inject(ChatCompletionToolMessageParam(role='tool', tool_call_id=call_id, content=observation + self.get_available_actions(info.get('admissible_commands', [[]])[0])))
            round_reward = reward
            if 'Nothing happens' in observation:
                round_reward = 0
            session.inject(RewardHistoryItem(reward=round_reward, score=reward))
            payload = {'round': i + 1, 'output': output, 'action': action, 'admissible_commands': admissible_commands, 'observation': observation, 'done': done}
            log_info['log'].append(payload)
            if len(log_info['log']) > 3:
                pre_logs = log_info['log'][-3:]
                pre_acts = [pre_log['output'] for pre_log in pre_logs]
                if len(list(set(pre_acts))) == 1:
                    self.logger.info('repeat actions for 3 times: failure')
                    return (0, log_info, SampleStatus.AGENT_INVALID_ACTION)
            if done:
                return (reward, log_info, finish_reason)
        else:
            finish_reason = SampleStatus.TASK_LIMIT_REACHED
            final_reward = 0
            reward_history = RewardHistoryItem(reward=final_reward, score=0)
            session.inject(reward_history)
        return (0, log_info, finish_reason)

def load_config(config_file):
    with open(config_file) as reader:
        config = yaml.safe_load(reader)
    return config

def load_prompts(prompts_file):
    with open(prompts_file, 'r') as f:
        d = json.load(f)
        f.close()
    return d

# Cluster 3

def deep_merge(base_item, new_item):
    if isinstance(base_item, dict) and isinstance(new_item, dict):
        ret = deepcopy(base_item)
        for key in new_item:
            if key in ret:
                ret[key] = deep_merge(ret[key], new_item[key])
            else:
                ret[key] = new_item[key]
        return ret
    if isinstance(base_item, list) and isinstance(new_item, list):
        ret = deepcopy(base_item)
        ret.extend(new_item)
        return ret
    return new_item

class ConfigLoader:

    def __init__(self) -> None:
        self.loading: Set[str] = set()
        self.loaded: Dict[str, Any] = dict()

    def load_from(self, path) -> Dict:
        path = os.path.realpath(path)
        if path in self.loading:
            raise Exception('Circular import detected: {}'.format(path))
        if path in self.loaded:
            return deepcopy(self.loaded[path])
        if not os.path.exists(path):
            raise Exception('File not found: {}'.format(path))
        if path.endswith('.yaml') or path.endswith('.yml'):
            with open(path) as f:
                config = yaml.safe_load(f)
        elif path.endswith('.json'):
            with open(path) as f:
                config = json.load(f)
        else:
            raise Exception('Unknown file type: {}'.format(path))
        self.loading.add(path)
        try:
            config = self.parse_imports(os.path.dirname(path), config)
        except Exception as e:
            self.loading.remove(path)
            raise e
        self.loading.remove(path)
        self.loaded[path] = config
        return self.parse_default_and_overwrite(deepcopy(config))

    def parse_imports(self, path, raw_config):
        raw_config = deepcopy(raw_config)
        if isinstance(raw_config, dict):
            ret = {}
            if 'import' in raw_config:
                v = raw_config.pop('import')
                if isinstance(v, str):
                    config = self.load_from(os.path.join(path, v))
                    ret = deep_merge(ret, config)
                elif isinstance(v, list):
                    for vv in v:
                        assert isinstance(vv, str), 'Import list must be a list of strings, found {}'.format(type(vv))
                        config = self.load_from(os.path.join(path, vv))
                        ret = deep_merge(ret, config)
                else:
                    raise Exception('Unknown import value: {}'.format(v))
            for k, v in raw_config.items():
                raw_config[k] = self.parse_imports(path, v)
            ret = deep_merge(ret, raw_config)
            return ret
        elif isinstance(raw_config, list):
            ret = []
            for v in raw_config:
                ret.append(self.parse_imports(path, v))
            return ret
        else:
            return raw_config

    def parse_default_and_overwrite(self, config):
        if isinstance(config, dict):
            if not config:
                return {}
            ret = {}
            overwriting = False
            defaulting = False
            if 'overwrite' in config:
                overwrite = self.parse_default_and_overwrite(config.pop('overwrite'))
                overwriting = True
            if 'default' in config:
                default = self.parse_default_and_overwrite(config.pop('default'))
                defaulting = True
            for k, v in config.items():
                parsed_v = self.parse_default_and_overwrite(v)
                if overwriting:
                    parsed_v = deep_merge(parsed_v, overwrite)
                if defaulting:
                    parsed_v = deep_merge(default, parsed_v)
                ret[k] = parsed_v
            return ret
        elif isinstance(config, list):
            ret = []
            for v in config:
                ret.append(self.parse_default_and_overwrite(v))
            return ret
        else:
            return config

# Cluster 4

def main(args):
    agent_names, task_names, validation_names, details = analyze_output(args.config, args.output, parse_timestamp(args.time))
    task_names.sort(key=lambda x: TaskHandler.get_handler(x).get_order_priority())
    summary = OrderedDict()
    for agent in details:
        summary[agent] = OrderedDict()
        for task in details[agent]:
            handler = TaskHandler.get_handler(task)
            if handler is not None:
                summary[agent][task] = handler.get_main_metric(details[agent][task]['overall'])
            else:
                summary[agent][task] = details[agent][task]['overall']
    for agent in details:
        for task in details[agent]:
            print(ColorMessage.cyan(f'Agent: {agent:20} Task: {task:20} Path: {details[agent][task]['file']}'))
    final_result = {'summary': summary, 'details': details}
    os.makedirs(args.save, exist_ok=True)
    with open(os.path.join(args.save, 'result.json'), 'w', encoding='utf-8') as f:
        json.dump(final_result, f, indent=4, ensure_ascii=False, sort_keys=True)
    with open(os.path.join(args.save, 'result.yaml'), 'w', encoding='utf-8') as f:
        yaml.dump(final_result, f, indent=4, allow_unicode=True, sort_keys=True)
    with open(os.path.join(args.save, 'summary.csv'), 'w', encoding='utf-8') as f:
        '\n        Format:\n            Agent\\Task, Task1, Task2, ...\n            Agent1, MainMetric(Agent1,Task1), MainMetric(Agent1,Task2), ...\n            ......\n        '
        f.write('Agent\\Task,' + ','.join(task_names) + '\n')
        for agent in summary:
            f.write(agent + ',' + ','.join([str(summary[agent][task]) if task in summary[agent] else '' for task in task_names]) + '\n')
    agent_validations = {agent: {validation: [] for validation in validation_names} for agent in agent_names}
    task_validations = {task: {validation: [] for validation in validation_names} for task in task_names}
    for agent in summary:
        for task in summary[agent]:
            if 'validation' in details[agent][task]['overall']:
                for validation in details[agent][task]['overall']['validation']:
                    agent_validations[agent][validation].append(details[agent][task]['overall']['validation'][validation])
                    task_validations[task][validation].append(details[agent][task]['overall']['validation'][validation])
    with open(os.path.join(args.save, 'agent_validation.csv'), 'w', encoding='utf-8') as f:
        '\n        Format:\n            Agent\\Validation, Validation1, Validation2, ...\n            Agent1, Avg(Agent1,Validation1), Avg(Agent1,Validation2), ...\n            ......\n        '
        f.write('Agent\\Validation,' + ','.join(validation_names) + '\n')
        for agent in agent_validations:
            f.write(agent + ',' + ','.join([str(sum(agent_validations[agent][validation]) / len(agent_validations[agent][validation])) if validation in agent_validations[agent] and len(agent_validations[agent][validation]) > 0 else '--' for validation in validation_names]) + '\n')
    with open(os.path.join(args.save, 'task_validation.csv'), 'w', encoding='utf-8') as f:
        '\n        Format:\n            Task\\Validation, Validation1, Validation2, ...\n            Task1, Avg(Task1,Validation1), Avg(Task1,Validation2), ...\n            ......\n        '
        f.write('Task\\Validation,' + ','.join(validation_names) + '\n')
        for task in task_validations:
            f.write(task + ',' + ','.join([str(sum(task_validations[task][validation]) / len(task_validations[task][validation])) if validation in task_validations[task] and len(task_validations[task][validation]) > 0 else '--' for validation in validation_names]) + '\n')
    print(ColorMessage.green(f'Analysis result saved to {os.path.abspath(args.save)}'))

def analyze_output(config: str, output: str, since_timestamp: float):
    """
    Walk through the output folder (including sub-dir) and analyze the overall.json file
    Rule:
        - valid overall file: **/{agent}/{task}/overall.json
        - if a same (agent, task) pair, select the latest one
    """
    loader = ConfigLoader()
    config: dict = loader.load_from(config)
    assert 'definition' in config, 'definition not found in config'
    assert 'agent' in config['definition'], 'agent not found in config.definition'
    assert 'task' in config['definition'], 'task not found in config.definition'
    agents = set(config['definition']['agent'].keys()).intersection(set(MODEL_MAP.keys()))
    tasks = list(config['definition']['task'].keys())
    print(ColorMessage.cyan(f'Available Agents ({len(agents)}):\n    ' + '\n    '.join(agents) + '\n\n' + f'Available Tasks ({len(tasks)}):\n    ' + '\n    '.join(tasks) + '\n'))
    overall_dict = OrderedDict()
    for root, dirs, files in os.walk(output):
        if 'overall.json' in files:
            root = os.path.abspath(root)
            pattern = root.split('/')
            if len(pattern) < 2:
                continue
            agent = pattern[-2]
            task = pattern[-1]
            ct = os.path.getmtime(os.path.join(root, 'overall.json'))
            if agent not in agents:
                continue
            elif task not in tasks:
                continue
            elif ct < since_timestamp:
                continue
            agent = MODEL_MAP[agent]
            if agent in overall_dict and task in overall_dict[agent]:
                if ct < overall_dict[agent][task]['time']:
                    continue
            overall_dict.setdefault(agent, OrderedDict())
            overall_dict[agent][task] = {'file': os.path.join(root, 'overall.json'), 'time': os.path.getmtime(os.path.join(root, 'overall.json'))}
    agent_names = []
    task_names = []
    validation_names = []
    for agent in overall_dict:
        if agent not in agent_names:
            agent_names.append(agent)
        for task in overall_dict[agent]:
            if task not in task_names:
                task_names.append(task)
            overall_dict[agent][task]['time'] = datetime.datetime.fromtimestamp(overall_dict[agent][task]['time']).strftime('%Y-%m-%d %H:%M:%S')
            with open(overall_dict[agent][task]['file'], 'r', encoding='utf-8') as f:
                overall_dict[agent][task]['overall'] = json.load(f)
            if 'validation' in overall_dict[agent][task]['overall']:
                overall_dict[agent][task]['overall']['validation'] = {validation: VALIDATION_MAP_FUNC[validation](overall_dict[agent][task]['overall']['validation']) for validation in VALIDATION_MAP_FUNC}
                for validation in overall_dict[agent][task]['overall']['validation']:
                    if validation not in validation_names:
                        validation_names.append(validation)
    return (agent_names, task_names, validation_names, overall_dict)

def parse_timestamp(time_str: str) -> float:
    try:
        return float(time_str)
    except:
        pass
    try:
        return datetime.datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S').timestamp()
    except:
        pass
    try:
        return datetime.datetime.strptime(time_str, '%Y-%m-%d').timestamp()
    except:
        pass
    try:
        return datetime.datetime.strptime(time_str, '%Y-%m').timestamp()
    except:
        pass
    num = float(re.findall('[\\d\\.]+', time_str)[0])
    unit = re.findall('[a-zA-Z]+', time_str)[0]
    if unit == 'd':
        delta = num * 24 * 60 * 60
    elif unit == 'h':
        delta = num * 60 * 60
    elif unit == 'm':
        delta = num * 60
    elif unit == 's':
        delta = num
    else:
        raise Exception('Unknown time unit')
    return time.time() - delta

# Cluster 5

def expression_to_lisp(expression) -> str:
    rtn = '('
    for i, e in enumerate(expression):
        if isinstance(e, list):
            rtn += expression_to_lisp(e)
        else:
            rtn += e
        if i != len(expression) - 1:
            rtn += ' '
    rtn += ')'
    return rtn

def get_nesting_level(expression) -> int:
    max_sub = 0
    for item in expression:
        if isinstance(item, list):
            level = get_nesting_level(item)
            if level > max_sub:
                max_sub = level
    return 1 + max_sub

def lisp_to_nested_expression(lisp_string: str) -> List:
    """
    Takes a logical form as a lisp string and returns a nested list representation of the lisp.
    For example, "(count (division first))" would get mapped to ['count', ['division', 'first']].
    """
    stack: List = []
    current_expression: List = []
    tokens = lisp_string.split()
    for token in tokens:
        while token[0] == '(':
            nested_expression: List = []
            current_expression.append(nested_expression)
            stack.append(current_expression)
            current_expression = nested_expression
            token = token[1:]
        current_expression.append(token.replace(')', ''))
        while token[-1] == ')':
            current_expression = stack.pop()
            token = token[:-1]
    return current_expression[0]

def get_answer_type(query: str):
    try:
        expression = lisp_to_nested_expression(query)
        G = logical_form_to_graph(expression)
        for node in G.nodes.items():
            if 'question_node' in node[1] and node[1]['question_node'] == 1:
                return node[1]['id']
    except Exception:
        return None

def same_logical_form(form1: str, form2: str) -> bool:
    if form1.__contains__('@@UNKNOWN@@') or form2.__contains__('@@UNKNOWN@@'):
        return False
    try:
        G1 = logical_form_to_graph(lisp_to_nested_expression(form1))
    except Exception:
        return False
    try:
        G2 = logical_form_to_graph(lisp_to_nested_expression(form2))
    except Exception:
        return False

    def node_match(n1, n2):
        if n1['id'] == n2['id'] and n1['type'] == n2['type']:
            func1 = n1.pop('function', 'none')
            func2 = n2.pop('function', 'none')
            tc1 = n1.pop('tc', 'none')
            tc2 = n2.pop('tc', 'none')
            if func1 == func2 and tc1 == tc2:
                return True
            else:
                return False
        else:
            return False

    def multi_edge_match(e1, e2):
        if len(e1) != len(e2):
            return False
        values1 = []
        values2 = []
        for v in e1.values():
            values1.append(v['relation'])
        for v in e2.values():
            values2.append(v['relation'])
        return sorted(values1) == sorted(values2)
    return nx.is_isomorphic(G1, G2, node_match=node_match, edge_match=multi_edge_match)

def binary_nesting(function: str, elements: List[str], types_along_path=None) -> str:
    if len(elements) < 2:
        print('error: binary function should have 2 parameters!')
    if not types_along_path:
        if len(elements) == 2:
            return '(' + function + ' ' + elements[0] + ' ' + elements[1] + ')'
        else:
            return '(' + function + ' ' + elements[0] + ' ' + binary_nesting(function, elements[1:]) + ')'
    elif len(elements) == 2:
        return '(' + function + ' ' + types_along_path[0] + ' ' + elements[0] + ' ' + elements[1] + ')'
    else:
        return '(' + function + ' ' + types_along_path[0] + ' ' + elements[0] + ' ' + binary_nesting(function, elements[1:], types_along_path[1:]) + ')'

def get_canonical_lisp(logical_form: str):
    expression = lisp_to_nested_expression(logical_form)
    new_expression = _anonymize_entities(expression)
    new_logical_form = expression_to_lisp(new_expression)
    return new_logical_form

def postprocess_raw_code(raw_lisp):
    expression = lisp_to_nested_expression(raw_lisp)
    if expression[0] in ['ARGMAX', 'ARGMIN'] and len(expression) > 3:
        expression[2] = binary_nesting('JOIN', expression[2:])
        expression = expression[:3]
        raw_lisp = expression_to_lisp(expression)
    splits = raw_lisp.split(' ')
    for i, s in enumerate(splits):
        if len(s) > 4 and s[-4:] == '_inv':
            splits[i] = f'(R {s[:-4]})'
        if len(s) > 5 and s[-5:] == '_inv)':
            splits[i] = f'(R {s[:-5]}))'
    processed_lisp = ' '.join(splits)
    return processed_lisp

def max_count_relations(program: str):
    expression = lisp_to_nested_expression(program)
    relations_count = count_relations_expression(expression)
    max = 0
    for r in relations_count:
        if relations_count[r] > max:
            max = relations_count[r]
    return max

# Cluster 7

def lisp_to_sparql(lisp_program: str):
    clauses = []
    order_clauses = []
    entities = set()
    identical_variables_r = {}
    expression = lisp_to_nested_expression(lisp_program)
    superlative = False
    if expression[0] in ['ARGMAX', 'ARGMIN']:
        superlative = True
        if isinstance(expression[2], list):

            def retrieve_relations(exp: list):
                rtn = []
                for element in exp:
                    if element == 'JOIN':
                        continue
                    elif isinstance(element, str):
                        rtn.append(element)
                    elif isinstance(element, list) and element[0] == 'R':
                        rtn.append(element)
                    elif isinstance(element, list) and element[0] == 'JOIN':
                        rtn.extend(retrieve_relations(element))
                return rtn
            relations = retrieve_relations(expression[2])
            expression = expression[:2]
            expression.extend(relations)
    sub_programs = _linearize_lisp_expression(expression, [0])
    question_var = len(sub_programs) - 1
    count = False

    def get_root(var: int):
        while var in identical_variables_r:
            var = identical_variables_r[var]
        return var
    for i, subp in enumerate(sub_programs):
        i = str(i)
        if subp[0] == 'JOIN':
            if isinstance(subp[1], list):
                if subp[2][:2] in ['m.', 'g.']:
                    clauses.append('ns:' + subp[2] + ' ns:' + subp[1][1] + ' ?x' + i + ' .')
                    entities.add(subp[2])
                elif subp[2][0] == '#':
                    clauses.append('?x' + subp[2][1:] + ' ns:' + subp[1][1] + ' ?x' + i + ' .')
                else:
                    if subp[2].__contains__('^^'):
                        data_type = subp[2].split('^^')[1].split('#')[1]
                        if data_type not in ['integer', 'float', 'dateTime', 'double']:
                            subp[2] = f'"{subp[2].split('^^')[0] + '-08:00'}"^^<{subp[2].split('^^')[1]}>'
                        else:
                            subp[2] = f'"{subp[2].split('^^')[0]}"^^<{subp[2].split('^^')[1]}>'
                    clauses.append(subp[2] + ' ns:' + subp[1][1] + ' ?x' + i + ' .')
            elif subp[2][:2] in ['m.', 'g.']:
                clauses.append('?x' + i + ' ns:' + subp[1] + ' ns:' + subp[2] + ' .')
                entities.add(subp[2])
            elif subp[2][0] == '#':
                clauses.append('?x' + i + ' ns:' + subp[1] + ' ?x' + subp[2][1:] + ' .')
            elif subp[2].__contains__('^^'):
                data_type = subp[2].split('^^')[1].split('#')[1]
                if data_type not in ['integer', 'float', 'dateTime', 'double']:
                    subp[2] = f'"{subp[2].split('^^')[0] + '-08:00'}"^^<{subp[2].split('^^')[1]}>'
                else:
                    subp[2] = f'"{subp[2].split('^^')[0]}"^^<{subp[2].split('^^')[1]}>'
                clauses.append('?x' + i + ' ns:' + subp[1] + ' ' + subp[2] + ' .')
            else:
                clauses.append(f'?x ns:{subp[1]} ?obj .')
                clauses.append(f'FILTER (str(?obj) = "{subp[2]}") .')
        elif subp[0] == 'AND':
            var1 = int(subp[2][1:])
            rooti = get_root(int(i))
            root1 = get_root(var1)
            if rooti > root1:
                identical_variables_r[rooti] = root1
            else:
                identical_variables_r[root1] = rooti
                root1 = rooti
            if subp[1][0] == '#':
                var2 = int(subp[1][1:])
                root2 = get_root(var2)
                if root1 > root2:
                    identical_variables_r[root1] = root2
                else:
                    identical_variables_r[root2] = root1
            else:
                clauses.append('?x' + i + ' ns:type.object.type ns:' + subp[1] + ' .')
        elif subp[0] in ['le', 'lt', 'ge', 'gt']:
            clauses.append('?x' + i + ' ns:' + subp[1] + ' ?y' + i + ' .')
            if subp[0] == 'le':
                op = '<='
            elif subp[0] == 'lt':
                op = '<'
            elif subp[0] == 'ge':
                op = '>='
            else:
                op = '>'
            if subp[2].__contains__('^^'):
                data_type = subp[2].split('^^')[1].split('#')[1]
                if data_type not in ['integer', 'float', 'dateTime', 'double']:
                    subp[2] = f'"{subp[2].split('^^')[0] + '-08:00'}"^^<{subp[2].split('^^')[1]}>'
                else:
                    subp[2] = f'"{subp[2].split('^^')[0]}"^^<{subp[2].split('^^')[1]}>'
            clauses.append(f'FILTER (?y{i} {op} {subp[2]})')
        elif subp[0] == 'TC':
            var = int(subp[1][1:])
            rooti = get_root(int(i))
            root_var = get_root(var)
            if rooti > root_var:
                identical_variables_r[rooti] = root_var
            else:
                identical_variables_r[root_var] = rooti
            year = subp[3]
            if year == 'NOW':
                from_para = '"2015-08-10"^^xsd:dateTime'
                to_para = '"2015-08-10"^^xsd:dateTime'
            else:
                from_para = f'"{year}-12-31"^^xsd:dateTime'
                to_para = f'"{year}-01-01"^^xsd:dateTime'
            clauses.append(f'FILTER(NOT EXISTS {{?x{i} ns:{subp[2]} ?sk0}} || ')
            clauses.append(f'EXISTS {{?x{i} ns:{subp[2]} ?sk1 . ')
            clauses.append(f'FILTER(xsd:datetime(?sk1) <= {from_para}) }})')
            if subp[2][-4:] == 'from':
                clauses.append(f'FILTER(NOT EXISTS {{?x{i} ns:{subp[2][:-4] + 'to'} ?sk2}} || ')
                clauses.append(f'EXISTS {{?x{i} ns:{subp[2][:-4] + 'to'} ?sk3 . ')
            else:
                clauses.append(f'FILTER(NOT EXISTS {{?x{i} ns:{subp[2][:-9] + 'to_date'} ?sk2}} || ')
                clauses.append(f'EXISTS {{?x{i} ns:{subp[2][:-9] + 'to_date'} ?sk3 . ')
            clauses.append(f'FILTER(xsd:datetime(?sk3) >= {to_para}) }})')
        elif subp[0] in ['ARGMIN', 'ARGMAX']:
            superlative = True
            if subp[1][0] == '#':
                var = int(subp[1][1:])
                rooti = get_root(int(i))
                root_var = get_root(var)
                if rooti > root_var:
                    identical_variables_r[rooti] = root_var
                else:
                    identical_variables_r[root_var] = rooti
            else:
                clauses.append(f'?x{i} ns:type.object.type ns:{subp[1]} .')
            if len(subp) == 3:
                clauses.append(f'?x{i} ns:{subp[2]} ?sk0 .')
            elif len(subp) > 3:
                for j, relation in enumerate(subp[2:-1]):
                    if j == 0:
                        var0 = f'x{i}'
                    else:
                        var0 = f'c{j - 1}'
                    var1 = f'c{j}'
                    if isinstance(relation, list) and relation[0] == 'R':
                        clauses.append(f'?{var1} ns:{relation[1]} ?{var0} .')
                    else:
                        clauses.append(f'?{var0} ns:{relation} ?{var1} .')
                clauses.append(f'?c{j} ns:{subp[-1]} ?sk0 .')
            if subp[0] == 'ARGMIN':
                order_clauses.append('ORDER BY ?sk0')
            elif subp[0] == 'ARGMAX':
                order_clauses.append('ORDER BY DESC(?sk0)')
            order_clauses.append('LIMIT 1')
        elif subp[0] == 'COUNT':
            var = int(subp[1][1:])
            root_var = get_root(var)
            identical_variables_r[int(i)] = root_var
            count = True
    for i in range(len(clauses)):
        for k in identical_variables_r:
            clauses[i] = clauses[i].replace(f'?x{k} ', f'?x{get_root(k)} ')
    question_var = get_root(question_var)
    for i in range(len(clauses)):
        clauses[i] = clauses[i].replace(f'?x{question_var} ', f'?x ')
    if superlative:
        arg_clauses = clauses[:]
    for entity in entities:
        clauses.append(f'FILTER (?x != ns:{entity})')
    clauses.insert(0, f"FILTER (!isLiteral(?x) OR lang(?x) = '' OR langMatches(lang(?x), 'en'))")
    clauses.insert(0, 'WHERE {')
    if count:
        clauses.insert(0, f'SELECT COUNT DISTINCT ?x')
    elif superlative:
        clauses.insert(0, '{SELECT ?sk0')
        clauses = arg_clauses + clauses
        clauses.insert(0, 'WHERE {')
        clauses.insert(0, f'SELECT DISTINCT ?x')
    else:
        clauses.insert(0, f'SELECT DISTINCT ?x')
    clauses.insert(0, 'PREFIX ns: <http://rdf.freebase.com/ns/>')
    clauses.append('}')
    clauses.extend(order_clauses)
    if superlative:
        clauses.append('}')
        clauses.append('}')
    return '\n'.join(clauses)

def retrieve_relations(exp: list):
    rtn = []
    for element in exp:
        if element == 'JOIN':
            continue
        elif isinstance(element, str):
            rtn.append(element)
        elif isinstance(element, list) and element[0] == 'R':
            rtn.append(element)
        elif isinstance(element, list) and element[0] == 'JOIN':
            rtn.extend(retrieve_relations(element))
    return rtn

def get_root(var: int):
    while var in identical_variables_r:
        var = identical_variables_r[var]
    return var

# Cluster 8

def _get_graph(expression: List) -> nx.MultiGraph:
    if isinstance(expression, str):
        G = nx.MultiDiGraph()
        if get_symbol_type(expression) == 1:
            G.add_node(1, id=expression, type='entity')
        elif get_symbol_type(expression) == 2:
            G.add_node(1, id=expression, type='literal')
        elif get_symbol_type(expression) == 3:
            G.add_node(1, id=expression, type='class')
        elif get_symbol_type(expression) == 4:
            domain, rang = relation_dr[expression]
            G.add_node(1, id=rang, type='class')
            G.add_node(2, id=domain, type='class')
            G.add_edge(2, 1, relation=expression)
            if REVERSE:
                if expression in reverse_properties:
                    G.add_edge(1, 2, relation=reverse_properties[expression])
        return G
    if expression[0] == 'R':
        if get_symbol_type(expression[1]) != 4:
            pass
        G = _get_graph(expression[1])
        size = len(G.nodes())
        mapping = {}
        for n in G.nodes():
            mapping[n] = size - n + 1
        G = nx.relabel_nodes(G, mapping)
        return G
    elif expression[0] in ['JOIN', 'le', 'ge', 'lt', 'gt']:
        if isinstance(expression[1], str) and get_symbol_type(expression[1]) != 4 or (not isinstance(expression[2], list) and get_symbol_type(expression[2]) not in [1, 2]) or (isinstance(expression[1], list) and expression[1][0] != 'R'):
            pass
        G1 = _get_graph(expression=expression[1])
        G2 = _get_graph(expression=expression[2])
        size = len(G2.nodes())
        qn_id = size
        if G1.nodes[1]['type'] == G2.nodes[qn_id]['type'] == 'class':
            if G2.nodes[qn_id]['id'] in upper_types[G1.nodes[1]['id']]:
                G2.nodes[qn_id]['id'] = G1.nodes[1]['id']
        if G1.nodes[1]['type'] == 'entity':
            mapping = {}
            for n in G1.nodes():
                mapping[n] = n + size
            G1 = nx.relabel_nodes(G1, mapping)
        else:
            mapping = {}
            for n in G1.nodes():
                mapping[n] = n + size - 1
            G1 = nx.relabel_nodes(G1, mapping)
        G = nx.compose(G1, G2)
        if expression[0] != 'JOIN':
            G.nodes[1]['function'] = function_map[expression[0]]
        return G
    elif expression[0] == 'AND':
        if not isinstance(expression[1], list) and get_symbol_type(expression[1]) != 3 or not isinstance(expression[2], list):
            pass
        G1 = _get_graph(expression[1])
        G2 = _get_graph(expression[2])
        size1 = len(G1.nodes())
        size2 = len(G2.nodes())
        if G1.nodes[size1]['type'] == G2.nodes[size2]['type'] == 'class':
            G2.nodes[size2]['id'] = G1.nodes[size1]['id']
        if G1.nodes[1]['type'] == 'entity':
            mapping = {}
            for n in G1.nodes():
                mapping[n] = n + size2
            G1 = nx.relabel_nodes(G1, mapping)
        else:
            mapping = {}
            for n in G1.nodes():
                mapping[n] = n + size2 - 1
            G1 = nx.relabel_nodes(G1, mapping)
        G2 = nx.relabel_nodes(G2, {size2: size1 + size2 - 1})
        G = nx.compose(G1, G2)
        return G
    elif expression[0] == 'COUNT':
        if len(expression) != 2 or not isinstance(expression[1], list):
            pass
        G = _get_graph(expression[1])
        size = len(G.nodes())
        G.nodes[size]['function'] = 'count'
        return G
    elif expression[0].__contains__('ARG'):
        if not isinstance(expression[1], list) and get_symbol_type(expression[1]) != 3 or (not isinstance(expression[2], list) and get_symbol_type(expression[2]) != 4):
            pass
        G1 = _get_graph(expression[1])
        size1 = len(G1.nodes())
        G2 = _get_graph(expression[2])
        size2 = len(G2.nodes())
        G2.nodes[1]['id'] = 0
        G2.nodes[1]['type'] = 'literal'
        G2.nodes[1]['function'] = expression[0].lower()
        if G1.nodes[size1]['type'] == G2.nodes[size2]['type'] == 'class':
            G2.nodes[size2]['id'] = G1.nodes[size1]['id']
        mapping = {}
        for n in G1.nodes():
            mapping[n] = n + size2 - 1
        G1 = nx.relabel_nodes(G1, mapping)
        G2 = nx.relabel_nodes(G2, {size2: size1 + size2 - 1})
        G = nx.compose(G1, G2)
        return G
    elif expression[0] == 'TC':
        G = _get_graph(expression[1])
        size = len(G.nodes())
        G.nodes[size]['tc'] = (expression[2], expression[3])
        return G

def get_symbol_type(symbol: str) -> int:
    if symbol.__contains__('^^'):
        return 2
    elif symbol in types:
        return 3
    elif symbol in relations:
        return 4
    elif symbol:
        return 1

def count_relations_expression(expression: List):
    rtn = defaultdict(lambda: 0)
    for item in expression:
        if isinstance(item, str):
            if get_symbol_type(item) == 4:
                rtn[item] += 1
                if item in reverse_properties:
                    rtn[reverse_properties[item]] += 1
        else:
            item_rtn = count_relations_expression(item)
            for r in item_rtn:
                if r in rtn:
                    rtn[r] = rtn[r] + item_rtn[r]
                else:
                    rtn[r] = item_rtn[r]
    return rtn

# Cluster 9

def set_visited(G, s, e, relation):
    end_num = get_end_num(G, s)
    for i in range(0, end_num[e]):
        if G.edges[s, e, i]['relation'] == relation:
            G.edges[s, e, i]['visited'] = True

def get_end_num(G, s):
    end_num = defaultdict(lambda: 0)
    for edge in list(G.edges(s)):
        end_num[list(edge)[1]] += 1
    return end_num

def none_function(G, start, arg_node=None, type_constraint=True):
    if arg_node is not None:
        arg = G.nodes[arg_node]['function']
        path = list(nx.all_simple_paths(G, start, arg_node))
        assert len(path) == 1
        arg_clause = []
        for i in range(0, len(path[0]) - 1):
            edge = G.edges[path[0][i], path[0][i + 1], 0]
            if edge['reverse']:
                relation = '(R ' + edge['relation'] + ')'
            else:
                relation = edge['relation']
            arg_clause.append(relation)
        while i >= 0:
            flag = False
            if G.out_degree[path[0][i]] > 2:
                flag = True
            G.remove_edge(path[0][i], path[0][i + 1], 0)
            i -= 1
            if flag:
                break
        if len(arg_clause) > 1:
            arg_clause = binary_nesting(function='JOIN', elements=arg_clause)
        else:
            arg_clause = arg_clause[0]
        return '(' + arg.upper() + ' ' + none_function(G, start) + ' ' + arg_clause + ')'
    if G.nodes[start]['type'] != 'class':
        return G.nodes[start]['id']
    end_num = get_end_num(G, start)
    clauses = []
    if G.nodes[start]['question'] and type_constraint:
        clauses.append(G.nodes[start]['id'])
    for key in end_num.keys():
        for i in range(0, end_num[key]):
            if not G.edges[start, key, i]['visited']:
                relation = G.edges[start, key, i]['relation']
                G.edges[start, key, i]['visited'] = True
                set_visited(G, key, start, relation)
                if G.edges[start, key, i]['reverse']:
                    relation = '(R ' + relation + ')'
                if G.nodes[key]['function'].__contains__('<') or G.nodes[key]['function'].__contains__('>'):
                    if G.nodes[key]['function'] == '>':
                        clauses.append('(gt ' + relation + ' ' + none_function(G, key) + ')')
                    if G.nodes[key]['function'] == '>=':
                        clauses.append('(ge ' + relation + ' ' + none_function(G, key) + ')')
                    if G.nodes[key]['function'] == '<':
                        clauses.append('(lt ' + relation + ' ' + none_function(G, key) + ')')
                    if G.nodes[key]['function'] == '<=':
                        clauses.append('(le ' + relation + ' ' + none_function(G, key) + ')')
                else:
                    clauses.append('(JOIN ' + relation + ' ' + none_function(G, key) + ')')
    if len(clauses) == 0:
        return G.nodes[start]['id']
    if len(clauses) == 1:
        return clauses[0]
    else:
        return binary_nesting(function='AND', elements=clauses)

def get_lisp_from_graph_query(graph_query):
    G = nx.MultiDiGraph()
    aggregation = 'none'
    arg_node = None
    for node in graph_query['nodes']:
        G.add_node(node['nid'], id=node['id'], type=node['node_type'], question=node['question_node'], function=node['function'], cla=node['class'])
        if node['question_node'] == 1:
            qid = node['nid']
        if node['function'] != 'none':
            aggregation = node['function']
            if node['function'].__contains__('arg'):
                arg_node = node['nid']
    for edge in graph_query['edges']:
        G.add_edge(edge['start'], edge['end'], relation=edge['relation'], reverse=False, visited=False)
        G.add_edge(edge['end'], edge['start'], relation=edge['relation'], reverse=True, visited=False)
    if 'count' == aggregation:
        return count_function(G, qid)
    else:
        return none_function(G, qid, arg_node=arg_node)

def count_function(G, start):
    return '(COUNT ' + none_function(G, start) + ')'

# Cluster 0

def _get_gewei(c_str):
    """
    分割出个位数字
    """
    if u'百零' in c_str:
        return _c2n(c_str.split(u'百零')[1])
    elif u'十' in c_str:
        return _c2n(c_str.split(u'十')[1])
    elif u'千零' in c_str:
        return _c2n(c_str.split(u'千零')[1])
    else:
        return '0'

def _c2n(c_str):
    """
    将汉字转化成数字
    """
    if c_str == '':
        return u'0'
    src = u'点零一二三四五六七八九'
    dst = u'.0123456789'
    for i, c in enumerate(src):
        c_str = c_str.replace(c, dst[i])
    return c_str

def _get_shiwei(c_str):
    """
    分割出十位数字
    """
    if u'百零' in c_str:
        return u'0'
    elif u'百' in c_str:
        return _c2n(c_str.split(u'百')[1].split(u'十')[0])
    elif u'千零' in c_str and u'十' in c_str:
        return _c2n(c_str.split(u'千零')[1].split(u'十')[0])
    elif u'十' in c_str:
        if c_str.split(u'十')[0] == '':
            return u'1'
        return _c2n(c_str.split(u'十')[0])
    else:
        return u'0'

def _get_baiwei(c_str):
    """
    分割出百位数字
    """
    if u'千零' in c_str:
        return u'0'
    elif u'千' in c_str:
        return _c2n(c_str.split(u'千')[1].split(u'百')[0])
    elif u'百' in c_str:
        return _c2n(c_str.split(u'百')[0])
    else:
        return ''

def _get_qianwei(c_str):
    """
    分割出千位数字
    """
    if u'万零' in c_str:
        return u'0'
    elif u'万' in c_str:
        return _c2n(c_str.split(u'万')[1].split(u'千')[0])
    elif u'千' in c_str:
        return _c2n(c_str.split(u'千')[0])
    else:
        return ''

def _get_complex(c_str):
    gewei = _get_gewei(c_str)
    shiwei = _get_shiwei(c_str)
    baiwei = _get_baiwei(c_str)
    qianwei = _get_qianwei(c_str)
    c_str = qianwei + baiwei + shiwei + gewei
    return c_str

def _convert_section(c_str):
    if _check_whether_special(c_str):
        return _c2n(c_str)
    else:
        return _get_complex(c_str)

def _check_whether_special(c_str):
    for i in u'十百千万亿':
        if i in c_str:
            return False
    return True

def _convert_all(c_str):
    if _check_whether_special(c_str):
        return _c2n(c_str)
    result = ''
    flag = 0
    float_part = ''
    if u'点' in c_str:
        flag1 = 1
        i = c_str.split(u'点')[1]
        c_str = c_str.split(u'点')[0]
        float_part = '.' + _convert_section(i)
    if u'亿' in c_str:
        flag = 8
        i = c_str.split(u'亿')[0]
        c_str = c_str.split(u'亿')[1]
        result += _convert_section(i)
        if c_str == '':
            result += '00000000'
            return result
    if u'万' in c_str:
        flag = 4
        i = c_str.split(u'万')[0]
        c_str = c_str.split(u'万')[1]
        result += _convert_section(i)
        if c_str == '':
            result += '0000'
            return result
    right = _get_complex(c_str)
    return result + '0' * (flag - len(_get_complex(c_str))) + right + float_part

# Cluster 1

def get_edit_distance(hyp_arr, truth_arr, normalize, level):
    """ calculate edit distance
    This is very universal, both for cha-level and phn-level
    """
    graph = tf.Graph()
    with graph.as_default():
        truth = tf.sparse_placeholder(tf.int32)
        hyp = tf.sparse_placeholder(tf.int32)
        editDist = tf.reduce_sum(tf.edit_distance(hyp, truth, normalize=normalize))
    with tf.Session(graph=graph) as session:
        truthTest = list_to_sparse_tensor(truth_arr, level)
        hypTest = list_to_sparse_tensor(hyp_arr, level)
        feedDict = {truth: truthTest, hyp: hypTest}
        dist = session.run(editDist, feed_dict=feedDict)
    return dist

def list_to_sparse_tensor(targetList, level):
    """ turn 2-D List to SparseTensor
    """
    indices = []
    vals = []
    assert level == 'phn' or level == 'cha', 'type must be phoneme or character, seq2seq will be supported in future'
    phn = ['aa', 'ae', 'ah', 'ao', 'aw', 'ax', 'ax-h', 'axr', 'ay', 'b', 'bcl', 'ch', 'd', 'dcl', 'dh', 'dx', 'eh', 'el', 'em', 'en', 'eng', 'epi', 'er', 'ey', 'f', 'g', 'gcl', 'h#', 'hh', 'hv', 'ih', 'ix', 'iy', 'jh', 'k', 'kcl', 'l', 'm', 'n', 'ng', 'nx', 'ow', 'oy', 'p', 'pau', 'pcl', 'q', 'r', 's', 'sh', 't', 'tcl', 'th', 'uh', 'uw', 'ux', 'v', 'w', 'y', 'z', 'zh']
    mapping = {'ah': 'ax', 'ax-h': 'ax', 'ux': 'uw', 'aa': 'ao', 'ih': 'ix', 'axr': 'er', 'el': 'l', 'em': 'm', 'en': 'n', 'nx': 'n', 'eng': 'ng', 'sh': 'zh', 'hv': 'hh', 'bcl': 'h#', 'pcl': 'h#', 'dcl': 'h#', 'tcl': 'h#', 'gcl': 'h#', 'kcl': 'h#', 'q': 'h#', 'epi': 'h#', 'pau': 'h#'}
    group_phn = ['ae', 'ao', 'aw', 'ax', 'ay', 'b', 'ch', 'd', 'dh', 'dx', 'eh', 'er', 'ey', 'f', 'g', 'h#', 'hh', 'ix', 'iy', 'jh', 'k', 'l', 'm', 'n', 'ng', 'ow', 'oy', 'p', 'r', 's', 't', 'th', 'uh', 'uw', 'v', 'w', 'y', 'z', 'zh']
    mapping = {'ah': 'ax', 'ax-h': 'ax', 'ux': 'uw', 'aa': 'ao', 'ih': 'ix', 'axr': 'er', 'el': 'l', 'em': 'm', 'en': 'n', 'nx': 'n', 'eng': 'ng', 'sh': 'zh', 'hv': 'hh', 'bcl': 'h#', 'pcl': 'h#', 'dcl': 'h#', 'tcl': 'h#', 'gcl': 'h#', 'kcl': 'h#', 'q': 'h#', 'epi': 'h#', 'pau': 'h#'}
    group_phn = ['ae', 'ao', 'aw', 'ax', 'ay', 'b', 'ch', 'd', 'dh', 'dx', 'eh', 'er', 'ey', 'f', 'g', 'h#', 'hh', 'ix', 'iy', 'jh', 'k', 'l', 'm', 'n', 'ng', 'ow', 'oy', 'p', 'r', 's', 't', 'th', 'uh', 'uw', 'v', 'w', 'y', 'z', 'zh']
    if level == 'cha':
        for tI, target in enumerate(targetList):
            for seqI, val in enumerate(target):
                indices.append([tI, seqI])
                vals.append(val)
        shape = [len(targetList), np.asarray(indices).max(axis=0)[1] + 1]
        return (np.array(indices), np.array(vals), np.array(shape))
    elif level == 'phn':
        '\n        for phn level, we should collapse 61 labels into 39 labels before scoring\n        \n        Reference:\n          Heterogeneous Acoustic Measurements and Multiple Classifiers for Speech Recognition(1986), \n            Andrew K. Halberstadt, https://groups.csail.mit.edu/sls/publications/1998/phdthesis-drew.pdf\n        '
        for tI, target in enumerate(targetList):
            for seqI, val in enumerate(target):
                if val < len(phn) and phn[val] in mapping.keys():
                    val = group_phn.index(mapping[phn[val]])
                indices.append([tI, seqI])
                vals.append(val)
        shape = [len(targetList), np.asarray(indices).max(0)[1] + 1]
        return (np.array(indices), np.array(vals), np.array(shape))
    else:
        raise ValueError('Invalid level: %s' % str(level))

def data_lists_to_batches(inputList, targetList, batchSize, level):
    """ padding the input list to a same dimension, integrate all data into batchInputs
    """
    assert len(inputList) == len(targetList)
    nFeatures = inputList[0].shape[0]
    maxLength = 0
    for inp in inputList:
        maxLength = max(maxLength, inp.shape[1])
    randIxs = np.random.permutation(len(inputList))
    start, end = (0, batchSize)
    dataBatches = []
    while end <= len(inputList):
        batchSeqLengths = np.zeros(batchSize)
        for batchI, origI in enumerate(randIxs[start:end]):
            batchSeqLengths[batchI] = inputList[origI].shape[-1]
        batchInputs = np.zeros((maxLength, batchSize, nFeatures))
        batchTargetList = []
        for batchI, origI in enumerate(randIxs[start:end]):
            padSecs = maxLength - inputList[origI].shape[1]
            batchInputs[:, batchI, :] = np.pad(inputList[origI].T, ((0, padSecs), (0, 0)), 'constant', constant_values=0)
            batchTargetList.append(targetList[origI])
        dataBatches.append((batchInputs, list_to_sparse_tensor(batchTargetList, level), batchSeqLengths))
        start += batchSize
        end += batchSize
    return (dataBatches, maxLength)

def load_batched_data(mfccPath, labelPath, batchSize, mode, level):
    """returns 3-element tuple: batched data (list), maxTimeLength (int), and
       total number of samples (int)"""
    return data_lists_to_batches([np.load(os.path.join(mfccPath, fn)) for fn in os.listdir(mfccPath)], [np.load(os.path.join(labelPath, fn)) for fn in os.listdir(labelPath)], batchSize, level) + (len(os.listdir(mfccPath)),)

def get_edit_distance(hyp_arr, truth_arr, mode='train'):
    """ calculate edit distance
    """
    graph = tf.Graph()
    with graph.as_default():
        truth = tf.sparse_placeholder(tf.int32)
        hyp = tf.sparse_placeholder(tf.int32)
        editDist = tf.edit_distance(hyp, truth, normalize=True)
    with tf.Session(graph=graph) as session:
        truthTest = list_to_sparse_tensor(truth_arr, mode)
        hypTest = list_to_sparse_tensor(hyp_arr, mode)
        feedDict = {truth: truthTest, hyp: hypTest}
        dist = session.run(editDist, feed_dict=feedDict)
    return dist

class Runner(object):

    def _default_configs(self):
        return {'level': level, 'rnncell': rnncell, 'batch_size': batch_size, 'num_hidden': num_hidden, 'num_feature': num_feature, 'num_classes': num_classes, 'num_layer': num_layer, 'num_iter': num_iter, 'activation': activation_fn, 'optimizer': optimizer_fn, 'learning_rate': lr, 'keep_prob': keep_prob, 'grad_clip': grad_clip}

    @describe
    def load_data(self, args, mode, type):
        if mode == 'train':
            return load_batched_data(train_mfcc_dir, train_label_dir, batch_size, mode, type)
        elif mode == 'test':
            return load_batched_data(test_mfcc_dir, test_label_dir, batch_size, mode, type)
        else:
            raise TypeError('mode should be train or test.')

    def run(self):
        args_dict = self._default_configs()
        args = dotdict(args_dict)
        batchedData, maxTimeSteps, totalN = self.load_data(args, mode=mode, type=level)
        model = model_fn(args, maxTimeSteps)
        num_params = count_params(model, mode='trainable')
        all_num_params = count_params(model, mode='all')
        model.config['trainable params'] = num_params
        model.config['all params'] = all_num_params
        print(model.config)
        with tf.Session() as sess:
            if keep == True:
                ckpt = tf.train.get_checkpoint_state(savedir)
                if ckpt and ckpt.model_checkpoint_path:
                    model.saver.restore(sess, ckpt.model_checkpoint_path)
                    print('Model restored from:' + savedir)
            else:
                print('Initializing')
                sess.run(model.initial_op)
            for epoch in range(num_epochs):
                start = time.time()
                if mode == 'train':
                    print('Epoch', epoch + 1, '...')
                batchErrors = np.zeros(len(batchedData))
                batchRandIxs = np.random.permutation(len(batchedData))
                for batch, batchOrigI in enumerate(batchRandIxs):
                    batchInputs, batchTargetSparse, batchSeqLengths = batchedData[batchOrigI]
                    batchTargetIxs, batchTargetVals, batchTargetShape = batchTargetSparse
                    feedDict = {model.inputX: batchInputs, model.targetIxs: batchTargetIxs, model.targetVals: batchTargetVals, model.targetShape: batchTargetShape, model.seqLengths: batchSeqLengths}
                    if level == 'cha':
                        if mode == 'train':
                            _, l, pre, y, er = sess.run([model.optimizer, model.loss, model.predictions, model.targetY, model.errorRate], feed_dict=feedDict)
                            batchErrors[batch] = er
                            print('\n{} mode, total:{},batch:{}/{},epoch:{}/{},train loss={:.3f},mean train CER={:.3f}\n'.format(level, totalN, batch + 1, len(batchRandIxs), epoch + 1, num_epochs, l, er / batch_size))
                        elif mode == 'test':
                            l, pre, y, er = sess.run([model.loss, model.predictions, model.targetY, model.errorRate], feed_dict=feedDict)
                            batchErrors[batch] = er
                            print('\n{} mode, total:{},batch:{}/{},test loss={:.3f},mean test CER={:.3f}\n'.format(level, totalN, batch + 1, len(batchRandIxs), l, er / batch_size))
                    elif level == 'phn':
                        if mode == 'train':
                            _, l, pre, y = sess.run([model.optimizer, model.loss, model.predictions, model.targetY], feed_dict=feedDict)
                            er = get_edit_distance([pre.values], [y.values], True, level)
                            print('\n{} mode, total:{},batch:{}/{},epoch:{}/{},train loss={:.3f},mean train PER={:.3f}\n'.format(level, totalN, batch + 1, len(batchRandIxs), epoch + 1, num_epochs, l, er))
                            batchErrors[batch] = er * len(batchSeqLengths)
                        elif mode == 'test':
                            l, pre, y = sess.run([model.loss, model.predictions, model.targetY], feed_dict=feedDict)
                            er = get_edit_distance([pre.values], [y.values], True, level)
                            print('\n{} mode, total:{},batch:{}/{},test loss={:.3f},mean test PER={:.3f}\n'.format(level, totalN, batch + 1, len(batchRandIxs), l, er))
                            batchErrors[batch] = er * len(batchSeqLengths)
                    if er / batch_size == 1.0:
                        break
                    if batch % 30 == 0:
                        print('Truth:\n' + output_to_sequence(y, type=level))
                        print('Output:\n' + output_to_sequence(pre, type=level))
                    if mode == 'train' and ((epoch * len(batchRandIxs) + batch + 1) % 20 == 0 or (epoch == num_epochs - 1 and batch == len(batchRandIxs) - 1)):
                        checkpoint_path = os.path.join(savedir, 'model.ckpt')
                        model.saver.save(sess, checkpoint_path, global_step=epoch)
                        print('Model has been saved in {}'.format(savedir))
                end = time.time()
                delta_time = end - start
                print('Epoch ' + str(epoch + 1) + ' needs time:' + str(delta_time) + ' s')
                if mode == 'train':
                    if (epoch + 1) % 1 == 0:
                        checkpoint_path = os.path.join(savedir, 'model.ckpt')
                        model.saver.save(sess, checkpoint_path, global_step=epoch)
                        print('Model has been saved in {}'.format(savedir))
                    epochER = batchErrors.sum() / totalN
                    print('Epoch', epoch + 1, 'mean train error rate:', epochER)
                    logging(model, logfile, epochER, epoch, delta_time, mode='config')
                    logging(model, logfile, epochER, epoch, delta_time, mode=mode)
                if mode == 'test':
                    with open(os.path.join(resultdir, level + '_result.txt'), 'a') as result:
                        result.write(output_to_sequence(y, type=level) + '\n')
                        result.write(output_to_sequence(pre, type=level) + '\n')
                        result.write('\n')
                    epochER = batchErrors.sum() / totalN
                    print(' test error rate:', epochER)
                    logging(model, logfile, epochER, mode=mode)

