                with open(path) as f:
                    ds[-1] = f.read()
            except:
                print('Using initial description')
            cc_test_datasets_multiclass += [ds]
        except:
            print(f'{name} at datasets_kaggle/{name}/train.csv not found, skipping...')
    return cc_test_datasets_multiclass

