    def _execute_agent_call(self, agent_call_config, user_guid, user_input, demo_data):
        """
        Execute an agent call with static and dynamic parameters.
        This is called when there's no display_result and the agent needs to be executed for real.

        Args:
            agent_call_config: The agent_call content block from JSON
            user_guid: User GUID for context
            user_input: User's message for dynamic parameter extraction
            demo_data: Full demo data for additional context

        Returns:
            Agent response or fallback message
        """
        try:
            agent_name = agent_call_config.get('agent', '')
            static_params = agent_call_config.get('static_parameters', {})
            dynamic_params_config = agent_call_config.get('dynamic_parameters', {})
            fallback = agent_call_config.get('fallback_response', 'Unable to complete the agent call.')
            description = agent_call_config.get('description', f'Calling {agent_name}')
            logging.info(f'Executing agent call: {agent_name} - {description}')
            dynamic_params = self._resolve_dynamic_parameters(dynamic_params_config, user_guid, user_input, demo_data)
            merged_params = {**static_params, **dynamic_params}
            logging.info(f'Agent call parameters: {json.dumps(merged_params, indent=2)}')
            agent = self._get_or_load_agent(agent_name)
            if not agent:
                logging.error(f"Agent '{agent_name}' not found locally or on GitHub")
                return fallback
            result = agent.perform(**merged_params)
            logging.info(f"Agent call to '{agent_name}' completed successfully")
            return result
        except Exception as e:
            logging.error(f'Error executing agent call: {str(e)}')
            import traceback
            logging.error(traceback.format_exc())
            return agent_call_config.get('fallback_response', f'Error executing agent: {str(e)}')

    def _resolve_dynamic_parameters(self, dynamic_params_config, user_guid, user_input, demo_data):
        """
        Resolve dynamic parameters from various sources.

        Dynamic parameter configuration format:
        {
            "param_name": {
                "source": "user_guid" | "user_input" | "context" | "infer",
                "description": "What this parameter is for",
                "extract_pattern": "Optional regex pattern for extraction",
                "default": "Optional default value"
            }
        }

        Or simplified format:
        {
            "param_name": "user_guid"  # Just the source as a string
        }
        """
        resolved_params = {}
        for param_name, config in dynamic_params_config.items():
            if isinstance(config, str):
                config = {'source': config}
            source = config.get('source', 'infer')
            default_value = config.get('default', None)
            extract_pattern = config.get('extract_pattern', None)
            resolved_value = None
            if source == 'user_guid':
                resolved_value = user_guid
            elif source == 'user_input':
                if extract_pattern:
                    match = re.search(extract_pattern, user_input, re.IGNORECASE)
                    if match:
                        resolved_value = match.group(1) if match.groups() else match.group(0)
                else:
                    resolved_value = user_input
            elif source == 'context':
                context_key = config.get('context_key', param_name)
                resolved_value = demo_data.get(context_key, default_value)
            elif source == 'infer':
                resolved_value = config.get('description', 'Inferred by assistant')
            if resolved_value is None and default_value is not None:
                resolved_value = default_value
            if resolved_value is not None:
                resolved_params[param_name] = resolved_value
        return resolved_params

    def _get_or_load_agent(self, agent_name):
        """
        Get an agent instance, loading from GitHub if not available locally.

        Args:
            agent_name: Name of the agent to load

        Returns:
            Agent instance or None if not found
        """
        if self.agent_manager:
            try:
                agent = self.agent_manager.get_agent(agent_name)
                if agent:
                    logging.info(f"Agent '{agent_name}' found locally via AgentManager")
                    return agent
            except Exception as e:
                logging.debug(f'Error checking local AgentManager: {str(e)}')
        if agent_name in self.remote_agent_cache:
            logging.info(f"Agent '{agent_name}' found in remote cache")
            return self.remote_agent_cache[agent_name]
        logging.info(f"Agent '{agent_name}' not found locally, attempting to load from GitHub...")
        agent = self._load_agent_from_github(agent_name)
        if agent:
            self.remote_agent_cache[agent_name] = agent
            logging.info(f"Agent '{agent_name}' successfully loaded from GitHub and cached")
            return agent
        logging.error(f"Agent '{agent_name}' not found locally or on GitHub")
        return None

    def _fetch_agent_manifest(self):
        """
        Attempt to fetch agent manifest from GitHub for faster agent discovery.
        This is optional - if manifest doesn't exist, falls back to path-based search.

        Returns:
            Manifest dict or None if not available
        """
        if self._agent_manifest_cache is not None:
            return self._agent_manifest_cache
        try:
            manifest_url = f'{self.GITHUB_RAW_BASE}/manifest.json'
            logging.debug(f'Attempting to fetch agent manifest from {manifest_url}')
            response = requests.get(manifest_url, timeout=5)
            response.raise_for_status()
            manifest = response.json()
            self._agent_manifest_cache = manifest
            logging.info(f'Agent manifest loaded successfully: {len(manifest.get('agents', []))} singular agents, {len(manifest.get('stacks', []))} stacks')
            return manifest
        except requests.exceptions.RequestException as e:
            logging.debug(f'No manifest found (will use path-based search): {str(e)}')
            self._agent_manifest_cache = {}
            return None
        except Exception as e:
            logging.debug(f'Error loading manifest: {str(e)}')
            self._agent_manifest_cache = {}
            return None

    def _find_agent_in_manifest(self, agent_name):
        """
        Find agent path using manifest if available.

        Args:
            agent_name: Name of the agent to find

        Returns:
            Agent file path or None if not found in manifest
        """
        manifest = self._fetch_agent_manifest()
        if not manifest:
            return None
        snake_case_name = self._convert_to_snake_case(agent_name)
        for agent in manifest.get('agents', []):
            if agent.get('id') == snake_case_name or agent.get('id') == agent_name:
                url = agent.get('url', '')
                if self.GITHUB_RAW_BASE in url:
                    path = url.replace(self.GITHUB_RAW_BASE + '/', '')
                    logging.info(f"Found agent '{agent_name}' in manifest: {path}")
                    return path
        for stack in manifest.get('stacks', []):
            for agent in stack.get('agents', []):
                if agent.get('id') == snake_case_name or agent.get('id') == agent_name:
                    url = agent.get('url', '')
                    if self.GITHUB_RAW_BASE in url:
                        path = url.replace(self.GITHUB_RAW_BASE + '/', '')
                        logging.info(f"Found stack agent '{agent_name}' in manifest: {path}")
                        return path
        return None

    def _load_agent_from_github(self, agent_name):
        """
        Load an agent from GitHub repository.

        Strategy:
        1. Check manifest (if available) for exact agent location
        2. Fall back to searching multiple possible locations:
           - agents/{agent_name}_agent.py
           - agent_stacks/*/{agent_name}_stack/agents/{agent_name}_agent.py

        Args:
            agent_name: Name of the agent to load

        Returns:
            Agent instance or None if not found
        """
        manifest_path = self._find_agent_in_manifest(agent_name)
        if manifest_path:
            agent = self._fetch_and_load_agent_from_path(agent_name, manifest_path)
            if agent:
                return agent
        snake_case_name = self._convert_to_snake_case(agent_name)
        possible_paths = [f'agents/{snake_case_name}.py', f'agents/{snake_case_name}_agent.py', f'agents/{agent_name}.py']
        stack_categories = ['b2b_sales', 'b2c_sales', 'energy', 'federal_government', 'financial_services', 'healthcare', 'manufacturing', 'professional_services', 'retail_cpg', 'slg_government', 'software_dp']
        for category in stack_categories:
            possible_paths.extend([f'agent_stacks/{category}_stacks/{snake_case_name}_stack/agents/{snake_case_name}_agent.py', f'agent_stacks/{category}_stacks/{snake_case_name}_stack/agents/{snake_case_name}.py', f'agent_stacks/{category}_stacks/{agent_name}_stack/agents/{agent_name}.py'])
        for path in possible_paths:
            agent = self._fetch_and_load_agent_from_path(agent_name, path)
            if agent:
                return agent
        return None

    def _fetch_and_load_agent_from_path(self, agent_name, file_path):
        """
        Fetch agent code from GitHub and dynamically load it.
        Uses requests library for robust HTTP handling.

        Args:
            agent_name: Name of the agent
            file_path: Path to the agent file in the repo

        Returns:
            Agent instance or None if fetch/load fails
        """
        try:
            url = f'{self.GITHUB_RAW_BASE}/{file_path}'
            logging.info(f'Attempting to fetch agent from: {url}')
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            agent_code = response.text
            logging.info(f'Successfully fetched agent code from {url} ({len(agent_code)} bytes)')
            agent_instance = self._load_agent_from_code(agent_name, agent_code, url)
            return agent_instance
        except requests.exceptions.HTTPError as e:
            if e.response.status_code == 404:
                logging.debug(f'Agent not found at {url}')
            else:
                logging.warning(f'HTTP error fetching agent from {url}: {e.response.status_code}')
            return None
        except requests.exceptions.Timeout:
            logging.warning(f'Timeout fetching agent from {url}')
            return None
        except requests.exceptions.RequestException as e:
            logging.warning(f'Request error fetching agent from {url}: {str(e)}')
            return None
        except Exception as e:
            logging.error(f'Error fetching/loading agent from {url}: {str(e)}')
            import traceback
            logging.error(traceback.format_exc())
            return None

    def _load_agent_from_code(self, agent_name, code, source_url):
        """
        Dynamically load an agent from Python code string.

        Args:
            agent_name: Name of the agent
            code: Python code as string
            source_url: URL where code was fetched from (for reference)

        Returns:
            Agent instance or None if load fails
        """
        try:
            module_name = f'dynamic_agent_{agent_name}_{id(code)}'
            spec = importlib.util.spec_from_loader(module_name, loader=None)
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            exec(code, module.__dict__)
            agent_class = None
            for name, obj in module.__dict__.items():
                if isinstance(obj, type) and name.endswith('Agent') and (name != 'BasicAgent') and hasattr(obj, 'perform'):
                    agent_class = obj
                    break
            if not agent_class:
                logging.error(f'No agent class found in code from {source_url}')
                return None
            agent_instance = agent_class()
            logging.info(f'Successfully instantiated {agent_class.__name__} from {source_url}')
            return agent_instance
        except Exception as e:
            logging.error(f'Error loading agent from code: {str(e)}')
            import traceback
            logging.error(traceback.format_exc())
            return None

    def _convert_to_snake_case(self, name):
        """
        Convert CamelCase or PascalCase to snake_case.

        Args:
            name: String to convert

        Returns:
            snake_case version of the string
        """
        if name.endswith('Agent'):
            name = name[:-5]
        s1 = re.sub('(.)([A-Z][a-z]+)', '\\1_\\2', name)
        return re.sub('([a-z0-9])([A-Z])', '\\1_\\2', s1).lower()

    def format_error_response(self, error_message):
        """
        Format an error response in a consistent way.
        """
        response = {'status': 'error', 'error': error_message, 'available_actions': ['list_demos - List all available demo files', 'load_demo - Load a specific demo and see its structure', 'respond - Get canned response for user input']}
        return json.dumps(response, indent=2)

# Cluster 4

def safe_json_loads(json_str):
    """
    Safely loads JSON string, handling potential errors.
    """
    if not json_str:
        return {}
    try:
        if isinstance(json_str, (dict, list)):
            return json_str
        return json.loads(json_str)
    except json.JSONDecodeError:
        return {'error': f'Invalid JSON: {json_str}'}

class AzureFileStorageManager:

    def __init__(self):
        storage_connection = os.environ.get('AzureWebJobsStorage', '')
        if not storage_connection:
            raise ValueError('AzureWebJobsStorage connection string is required')
        connection_parts = dict((part.split('=', 1) for part in storage_connection.split(';')))
        self.account_name = connection_parts.get('AccountName')
        self.account_key = connection_parts.get('AccountKey')
        self.share_name = os.environ.get('AZURE_FILES_SHARE_NAME')
        if not self.share_name:
            raise ValueError('AZURE_FILES_SHARE_NAME environment variable is required')
        self.shared_memory_path = 'shared_memories'
        self.default_file_name = 'memory.json'
        self.current_guid = None
        self.current_memory_path = self.shared_memory_path
        if not all([self.account_name, self.account_key]):
            raise ValueError('Invalid storage connection string')
        self.file_service = FileService(account_name=self.account_name, account_key=self.account_key)
        self._ensure_share_exists()

    def _ensure_share_exists(self):
        try:
            self.file_service.create_share(self.share_name, fail_on_exist=False)
            self.ensure_directory_exists(self.shared_memory_path)
            try:
                self.file_service.get_file_properties(self.share_name, self.shared_memory_path, self.default_file_name)
            except Exception:
                self.file_service.create_file_from_text(self.share_name, self.shared_memory_path, self.default_file_name, '{}')
                logging.info(f'Created new {self.default_file_name} in shared memories directory')
        except Exception as e:
            logging.error(f'Error ensuring share exists: {str(e)}')
            raise

    def set_memory_context(self, guid=None):
        """Set the memory context - only create new directories if valid GUID is provided"""
        if not guid:
            self.current_guid = None
            self.current_memory_path = self.shared_memory_path
            return True
        guid_pattern = re.compile('^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', re.IGNORECASE)
        if not guid_pattern.match(guid):
            logging.warning(f'Invalid GUID format: {guid}. Using shared memory.')
            self.current_guid = None
            self.current_memory_path = self.shared_memory_path
            return False
        try:
            guid_dir = f'memory/{guid}'
            guid_file = 'user_memory.json'
            try:
                self.file_service.get_file_properties(self.share_name, guid_dir, guid_file)
                self.current_guid = guid
                self.current_memory_path = guid_dir
                return True
            except Exception:
                self.ensure_directory_exists(guid_dir)
                self.file_service.create_file_from_text(self.share_name, guid_dir, guid_file, '{}')
                logging.info(f'Created new memory file for GUID: {guid}')
                self.current_guid = guid
                self.current_memory_path = guid_dir
                return True
        except Exception as e:
            logging.error(f'Error setting memory context for GUID {guid}: {str(e)}')
            self.current_guid = None
            self.current_memory_path = self.shared_memory_path
            return False

    def read_json(self):
        """Read from either GUID-specific memory or shared memories"""
        if self.current_guid and self.current_memory_path != self.shared_memory_path:
            try:
                return self._read_guid_memory()
            except Exception:
                self.current_guid = None
                self.current_memory_path = self.shared_memory_path
                return self._read_shared_memory()
        else:
            return self._read_shared_memory()

    def _read_shared_memory(self):
        try:
            file_content = self.file_service.get_file_to_text(self.share_name, self.shared_memory_path, self.default_file_name)
            return safe_json_loads(file_content.content)
        except Exception as e:
            logging.error(f'Error reading from shared memory: {str(e)}')
            if 'ResourceNotFound' in str(e):
                self._ensure_share_exists()
            return {}

    def _read_guid_memory(self):
        try:
            file_content = self.file_service.get_file_to_text(self.share_name, self.current_memory_path, 'user_memory.json')
            return safe_json_loads(file_content.content)
        except Exception as e:
            logging.error(f'Error reading from GUID memory: {str(e)}')
            raise

    def write_json(self, data):
        """Write to either GUID-specific memory or shared memories"""
        if self.current_guid and self.current_memory_path != self.shared_memory_path:
            try:
                self._write_guid_memory(data)
            except Exception:
                self.current_guid = None
                self.current_memory_path = self.shared_memory_path
                self._write_shared_memory(data)
        else:
            self._write_shared_memory(data)

    def _write_shared_memory(self, data):
        try:
            json_content = json.dumps(data, indent=4)
            self.file_service.create_file_from_text(self.share_name, self.shared_memory_path, self.default_file_name, json_content)
        except Exception as e:
            logging.error(f'Error writing to shared memory: {str(e)}')
            if 'ResourceNotFound' in str(e):
                self._ensure_share_exists()
                self._write_shared_memory(data)

    def _write_guid_memory(self, data):
        try:
            json_content = json.dumps(data, indent=4)
            self.file_service.create_file_from_text(self.share_name, self.current_memory_path, 'user_memory.json', json_content)
        except Exception as e:
            logging.error(f'Error writing to GUID memory: {str(e)}')
            raise

    def ensure_directory_exists(self, directory_name):
        """Only creates directories that are explicitly needed"""
        try:
            if not directory_name:
                return False
            self.file_service.create_share(self.share_name, fail_on_exist=False)
            parts = directory_name.split('/')
            current_path = ''
            for part in parts:
                if part:
                    if current_path:
                        current_path = f'{current_path}/{part}'
                    else:
                        current_path = part
                    self.file_service.create_directory(self.share_name, current_path, fail_on_exist=False)
            return True
        except Exception as e:
            logging.error(f'Error ensuring directory exists: {str(e)}')
            return False

    def write_file(self, directory_name, file_name, content):
        """
        Writes a file to Azure File Storage, properly handling binary data.

        Args:
            directory_name (str): The directory to write to
            file_name (str): The name of the file
            content: The content to write (can be str, bytes, or BytesIO)

        Returns:
            bool: Success or failure
        """
        try:
            self.ensure_directory_exists(directory_name)
            if isinstance(content, (bytes, bytearray)):
                self.file_service.create_file_from_bytes(self.share_name, directory_name, file_name, content)
            elif hasattr(content, 'read') and callable(content.read):
                content.seek(0)
                binary_content = content.read()
                if isinstance(binary_content, (bytes, bytearray)):
                    self.file_service.create_file_from_bytes(self.share_name, directory_name, file_name, binary_content)
                else:
                    self.file_service.create_file_from_text(self.share_name, directory_name, file_name, str(binary_content))
            else:
                self.file_service.create_file_from_text(self.share_name, directory_name, file_name, str(content))
            return True
        except Exception as e:
            logging.error(f'Error writing file: {str(e)}')
            return False

    def read_file(self, directory_name, file_name):
        """
        Reads a file from Azure File Storage.

        For text files, returns the content as a string.
        For binary files, consider using read_file_binary instead.

        Args:
            directory_name (str): The directory to read from
            file_name (str): The name of the file

        Returns:
            str or None: The file content or None if an error occurs
        """
        try:
            if file_name.lower().endswith(('.pptx', '.docx', '.xlsx', '.pdf', '.zip', '.jpg', '.png', '.gif')):
                return self.read_file_binary(directory_name, file_name)
            try:
                file_content = self.file_service.get_file_to_text(self.share_name, directory_name, file_name)
                return file_content.content
            except Exception as text_error:
                logging.warning(f'Failed to read as text, trying binary: {str(text_error)}')
                return self.read_file_binary(directory_name, file_name)
        except Exception as e:
            logging.error(f'Error reading file: {str(e)}')
            return None

    def read_file_binary(self, directory_name, file_name):
        """
        Reads a file from Azure File Storage as binary data.

        Args:
            directory_name (str): The directory to read from
            file_name (str): The name of the file

        Returns:
            bytes or None: The binary file content or None if an error occurs
        """
        try:
            binary_stream = self.file_service.get_file_to_bytes(self.share_name, directory_name, file_name)
            return binary_stream.content
        except Exception as e:
            logging.error(f'Error reading binary file: {str(e)}')
            return None

    def list_files(self, directory_name):
        try:
            return self.file_service.list_directories_and_files(self.share_name, directory_name)
        except Exception as e:
            logging.error(f'Error listing files: {str(e)}')
            return []

    def generate_download_url(self, directory, filename, expiry_time):
        """
        Generates a temporary download URL with SAS token for a file in Azure File Storage.

        Args:
            directory (str): The directory containing the file
            filename (str): The filename to download
            expiry_time (datetime): When the URL should expire

        Returns:
            str: The download URL or None if failed
        """
        try:
            if directory.endswith('/'):
                file_path = f'{directory}{filename}'
            else:
                file_path = f'{directory}/{filename}'
            directory_path = '/'.join(file_path.split('/')[:-1])
            file_name = file_path.split('/')[-1]
            start_time = datetime.utcnow()
            expiry_time = start_time + timedelta(minutes=30)
            sas_token = self.file_service.generate_file_shared_access_signature(share_name=self.share_name, directory_name=directory_path, file_name=file_name, permission='r', expiry=expiry_time)
            file_url = f'https://{self.account_name}.file.core.windows.net/{self.share_name}/{file_path}'
            download_url = f'{file_url}?{sas_token}'
            return download_url
        except Exception as e:
            logging.error(f'Error generating download URL: {str(e)}')
            logging.error(f'Directory: {directory}, Filename: {filename}')
            return None

