def main():
    """Main CLI interface"""
    if len(sys.argv) < 2:
        print(json.dumps({'error': 'Usage: python explore_databento_data.py <command>', 'commands': ['explore', 'sample [n]']}, indent=2))
        sys.exit(1)
    command = sys.argv[1].lower()
    result = {}
    try:
        if command == 'explore':
            result = explore_raw_data()
        elif command == 'sample':
            n = int(sys.argv[2]) if len(sys.argv) > 2 else 10
            result = show_sample_records(n)
        else:
            result = {'error': f'Unknown command: {command}'}
