class CannySampler:

    def __init__(self, target):
        self.raw = target
        self.f = lambda timg: cv2.Canny(t2rgb(timg), 100, 200)
        self.target = self.f(target)
        self.cache = {self.target.shape: self.target}

    def __call__(self, dic):
        rgbs = dic['rgbs']
