class PredicateExecutor(AbstractExecutor):
    """ """

    def __init__(self, db: EvaDBDatabase, node: PredicatePlan):
        super().__init__(db, node)
        self.predicate = node.predicate

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        child_executor = self.children[0]
        for batch in child_executor.exec(**kwargs):
            batch = apply_predicate(batch, self.predicate)
            if not batch.empty():
                yield batch
        instrument_function_expression_cost(self.predicate, self.catalog())

def apply_predicate(batch: Batch, predicate: AbstractExpression) -> Batch:
    if not batch.empty() and predicate is not None:
        outcomes = predicate.evaluate(batch)
        batch.drop_zero(outcomes)
        batch.reset_index()
    return batch

def instrument_function_expression_cost(expr: Union[AbstractExpression, List[AbstractExpression]], catalog: 'CatalogManager'):
    """We are expecting an instance of a catalog. An optimization can be to avoid creating a catalog instance if there is no function expression. An easy fix is to pass the function handler and create the catalog instance only if there is a function expression. In the past, this was problematic because of Ray. We can revisit it again."""
    if expr is None:
        return
    list_expr = expr
    if not isinstance(expr, list):
        list_expr = [expr]
    for expr in list_expr:
        for func_expr in expr.find_all(FunctionExpression):
            if func_expr.function_obj and func_expr._stats:
                function_id = func_expr.function_obj.row_id
                catalog.upsert_function_cost_catalog_entry(function_id, func_expr.function_obj.name, func_expr._stats.prev_cost)

class ProjectExecutor(AbstractExecutor):
    """ """

    def __init__(self, db: EvaDBDatabase, node: ProjectPlan):
        super().__init__(db, node)
        self.target_list = node.target_list

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        if len(self.children) == 0:
            dummy_batch = Batch(pd.DataFrame([0]))
            batch = apply_project(dummy_batch, self.target_list)
            if not batch.empty():
                yield batch
        elif len(self.children) == 1:
            child_executor = self.children[0]
            for batch in child_executor.exec(**kwargs):
                batch = apply_project(batch, self.target_list)
                if not batch.empty():
                    yield batch
        else:
            raise ExecutorError('ProjectExecutor has more than 1 children.')
        instrument_function_expression_cost(self.target_list, self.catalog())

def apply_project(batch: Batch, project_list: List[AbstractExpression]):
    if not batch.empty() and project_list:
        batches = [expr.evaluate(batch) for expr in project_list]
        batch = Batch.merge_column_wise(batches)
    return batch

class OrderByExecutor(AbstractExecutor):
    """
    Sort the frames which satisfy the condition

    Arguments:
        node (AbstractPlan): The OrderBy Plan

    """

    def __init__(self, db: EvaDBDatabase, node: OrderByPlan):
        super().__init__(db, node)
        self._orderby_list = node.orderby_list
        self._columns = node.columns
        self._sort_types = node.sort_types
        self.batch_sizes = []

    def _extract_column_name(self, col):
        col_name = []
        if isinstance(col, TupleValueExpression):
            col_name += [col.col_alias]
        elif isinstance(col, FunctionExpression):
            col_name += col.col_alias
        else:
            raise ExecutorError('Expression type {} is not supported.'.format(type(col)))
        return col_name

    def extract_column_names(self):
        """extracts the string name of the column"""
        col_name_list = []
        for col in self._columns:
            col_name_list += self._extract_column_name(col)
        return col_name_list

    def extract_sort_types(self):
        """extracts the sort type for the column"""
        sort_type_bools = []
        for st in self._sort_types:
            if st is ParserOrderBySortType.ASC:
                sort_type_bools.append(True)
            else:
                sort_type_bools.append(False)
        return sort_type_bools

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        child_executor = self.children[0]
        aggregated_batch_list = []
        for batch in child_executor.exec(**kwargs):
            self.batch_sizes.append(len(batch))
            aggregated_batch_list.append(batch)
        aggregated_batch = Batch.concat(aggregated_batch_list, copy=False)
        if not len(aggregated_batch):
            return
        merge_batch_list = [aggregated_batch]
        for col in self._columns:
            col_name_list = self._extract_column_name(col)
            for col_name in col_name_list:
                if col_name not in aggregated_batch.columns:
                    batch = col.evaluate(aggregated_batch)
                    merge_batch_list.append(batch)
        if len(merge_batch_list) > 1:
            aggregated_batch = Batch.merge_column_wise(merge_batch_list)
        try:
            aggregated_batch.sort_orderby(by=self.extract_column_names(), sort_type=self.extract_sort_types())
        except KeyError:
            pass
        index = 0
        for i in self.batch_sizes:
            batch = aggregated_batch[index:index + i]
            batch.reset_index()
            index += i
            yield batch

class NestedLoopJoinExecutor(AbstractExecutor):

    def __init__(self, db: EvaDBDatabase, node: NestedLoopJoinPlan):
        super().__init__(db, node)
        self.predicate = node.join_predicate

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        outer = self.children[0]
        inner = self.children[1]
        for row1 in outer.exec(**kwargs):
            for row2 in inner.exec(**kwargs):
                result_batch = Batch.join(row1, row2)
                result_batch.reset_index()
                result_batch = apply_predicate(result_batch, self.predicate)
                if not result_batch.empty():
                    yield result_batch
        if self.predicate:
            instrument_function_expression_cost(self.predicate, self.catalog())

class SequentialScanExecutor(AbstractExecutor):
    """
    Applies predicates to filter the frames which satisfy the condition
    Arguments:
        node (AbstractPlan): The SequentialScanPlan

    """

    def __init__(self, db: EvaDBDatabase, node: SeqScanPlan):
        super().__init__(db, node)
        self.predicate = node.predicate
        self.project_expr = node.columns
        self.alias = node.alias

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        child_executor = self.children[0]
        for batch in child_executor.exec(**kwargs):
            if self.alias:
                batch.modify_column_alias(self.alias)
            batch = apply_predicate(batch, self.predicate)
            batch = apply_project(batch, self.project_expr)
            if not batch.empty():
                yield batch
        if self.predicate or self.project_expr:
            catalog = self.catalog()
            instrument_function_expression_cost(self.predicate, catalog)
            instrument_function_expression_cost(self.project_expr, catalog)

class ApplyAndMergeExecutor(AbstractExecutor):
    """
    Apply the function expression to the input data, merge the output of the function
    with the input data, and yield the result to the parent. The current implementation
    assumes an inner join while merging. Therefore, if the function does not return any
    output, the input rows are dropped.
    Arguments:
        node (AbstractPlan): ApplyAndMergePlan

    """

    def __init__(self, db: EvaDBDatabase, node: ApplyAndMergePlan):
        super().__init__(db, node)
        self.func_expr = node.func_expr
        self.do_unnest = node.do_unnest
        self.alias = node.alias

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        child_executor = self.children[0]
        for batch in child_executor.exec(**kwargs):
            func_result = self.func_expr.evaluate(batch)
            output = Batch.merge_column_wise([batch, func_result])
            if self.do_unnest:
                output.unnest(func_result.columns)
                output.reset_index()
            yield output
        instrument_function_expression_cost(self.func_expr, self.catalog())

class HashJoinExecutor(AbstractExecutor):

    def __init__(self, db: EvaDBDatabase, node: HashJoinProbePlan):
        super().__init__(db, node)
        self.predicate = node.join_predicate
        self.join_type = node.join_type
        self.probe_keys = node.probe_keys
        self.join_project = node.join_project

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        build_table = self.children[0]
        probe_table = self.children[1]
        hash_keys = [key.col_alias for key in self.probe_keys]
        for build_batch in build_table.exec():
            for probe_batch in probe_table.exec():
                probe_batch.reassign_indices_to_hash(hash_keys)
                join_batch = Batch.join(probe_batch, build_batch)
                join_batch.reset_index()
                join_batch = apply_predicate(join_batch, self.predicate)
                join_batch = apply_project(join_batch, self.join_project)
                yield join_batch
        if self.predicate or self.join_project:
            catalog = self.catalog()
            instrument_function_expression_cost(self.predicate, catalog)
            instrument_function_expression_cost(self.join_project, catalog)

class FunctionScanExecutor(AbstractExecutor):
    """
    Executes functional expression which yields a table of rows
    Arguments:
        node (AbstractPlan): FunctionScanPlan

    """

    def __init__(self, db: EvaDBDatabase, node: FunctionScanPlan):
        super().__init__(db, node)
        self.func_expr = node.func_expr
        self.do_unnest = node.do_unnest

    def exec(self, *args, **kwargs) -> Iterator[Batch]:
        assert 'lateral_input' in kwargs, 'Key lateral_input not passed to the FunctionScan'
        lateral_input = kwargs.get('lateral_input')
        if not lateral_input.empty():
            res = self.func_expr.evaluate(lateral_input)
            if not res.empty():
                if self.do_unnest:
                    res.unnest(res.columns)
                yield res
            instrument_function_expression_cost(self.func_expr, self.catalog())

class FunctionExpression(AbstractExpression):
    """
    Consider FunctionExpression: ObjDetector -> (labels, boxes)

    `output`: If the user wants only subset of outputs. Eg,
    ObjDetector.labels the parser with set output to 'labels'

    `output_objs`: It is populated by the binder. In case the
    output is None, the binder sets output_objs to list of all
    output columns of the FunctionExpression. Eg, ['labels',
    'boxes']. Otherwise, only the output columns.

    FunctionExpression also needs to prepend its alias to all the
    projected columns. This is important as other parts of the query
    might be assessing the results using alias. Eg,

    `Select Detector.labels
     FROM Video JOIN LATERAL ObjDetector AS Detector;`
    """

    def __init__(self, func: Callable, name: str, output: str=None, alias: Alias=None, **kwargs):
        super().__init__(ExpressionType.FUNCTION_EXPRESSION, **kwargs)
        self._context = Context()
        self._name = name
        self._function = func
        self._function_instance = None
        self._output = output
        self.alias = alias
        self.function_obj: FunctionCatalogEntry = None
        self.output_objs: List[FunctionIOCatalogEntry] = []
        self.projection_columns: List[str] = []
        self._cache: FunctionExpressionCache = None
        self._stats = FunctionStats()

    @property
    def name(self):
        return self._name

    @property
    def output(self):
        return self._output

    @property
    def col_alias(self):
        col_alias_list = []
        if self.alias is not None:
            for col in self.alias.col_names:
                col_alias_list.append('{}.{}'.format(self.alias.alias_name, col))
        return col_alias_list

    @property
    def function(self):
        return self._function

    @function.setter
    def function(self, func: Callable):
        self._function = func

    def enable_cache(self, cache: 'FunctionExpressionCache'):
        self._cache = cache
        return self

    def has_cache(self):
        return self._cache is not None

    def consolidate_stats(self):
        if self.function_obj is None:
            return
        if self.has_cache() and self._stats.cache_misses > 0:
            cost_per_func_call = self._stats.timer.total_elapsed_time / self._stats.cache_misses
        else:
            cost_per_func_call = self._stats.timer.total_elapsed_time / self._stats.num_calls
        if abs(self._stats.prev_cost - cost_per_func_call) > cost_per_func_call / 10:
            self._stats.prev_cost = cost_per_func_call

    def evaluate(self, batch: Batch, **kwargs) -> Batch:
        func = self._gpu_enabled_function()
        with self._stats.timer:
            outcomes = self._apply_function_expression(func, batch, **kwargs)
            if outcomes.frames.empty is False:
                outcomes = outcomes.project(self.projection_columns)
                outcomes.modify_column_alias(self.alias)
        self._stats.num_calls += len(batch)
        try:
            self.consolidate_stats()
        except Exception as e:
            logger.warn(f'Persisting FunctionExpression {str(self)} stats failed with {str(e)}')
        return outcomes

    def signature(self) -> str:
        """It constructs the signature of the function expression.
        It traverses the children (function arguments) and compute signature for each
        child. The output is in the form `function_name[row_id](arg1, arg2, ...)`.

        Returns:
            str: signature string
        """
        child_sigs = []
        for child in self.children:
            child_sigs.append(child.signature())
        func_sig = f'{self.name}[{self.function_obj.row_id}]({','.join(child_sigs)})'
        return func_sig

    def _gpu_enabled_function(self):
        if self._function_instance is None:
            self._function_instance = self.function()
            if isinstance(self._function_instance, GPUCompatible):
                device = self._context.gpu_device()
                if device != NO_GPU:
                    self._function_instance = self._function_instance.to_device(device)
        return self._function_instance

    def _apply_function_expression(self, func: Callable, batch: Batch, **kwargs):
        """
        If cache is not enabled, call the func on the batch and return.
        If cache is enabled:
        (1) iterate over the input batch rows and check if we have the value in the
        cache;
        (2) for all cache miss rows, call the func;
        (3) iterate over each cache miss row and store the results in the cache;
        (4) stitch back the partial cache results with the new func calls.
        """
        func_args = Batch.merge_column_wise([child.evaluate(batch, **kwargs) for child in self.children])
        if not self._cache:
            return func_args.apply_function_expression(func)
        output_cols = [obj.name for obj in self.function_obj.outputs]
        results = np.full([len(batch), len(output_cols)], None)
        cache_keys = func_args
        if self._cache.key:
            cache_keys = Batch.merge_column_wise([child.evaluate(batch, **kwargs) for child in self._cache.key])
            assert len(cache_keys) == len(batch), 'Not all rows have the cache key'
        cache_miss = np.full(len(batch), True)
        for idx, (_, key) in enumerate(cache_keys.iterrows()):
            val = self._cache.store.get(key.to_numpy())
            results[idx] = val
            cache_miss[idx] = val is None
        self._stats.cache_misses += sum(cache_miss)
        if cache_miss.any():
            func_args = func_args[list(cache_miss)]
            cache_miss_results = func_args.apply_function_expression(func)
            missing_keys = cache_keys[list(cache_miss)]
            for key, value in zip(missing_keys.iterrows(), cache_miss_results.iterrows()):
                self._cache.store.set(key[1].to_numpy(), value[1].to_numpy())
            results[cache_miss] = cache_miss_results.to_numpy()
        return Batch(pd.DataFrame(results, columns=output_cols))

    def __str__(self) -> str:
        args = [str(child) for child in self.children]
        expr_str = f'{self.name}({','.join(args)})'
        return expr_str

    def __eq__(self, other):
        is_subtree_equal = super().__eq__(other)
        if not isinstance(other, FunctionExpression):
            return False
        return is_subtree_equal and self.name == other.name and (self.output == other.output) and (self.alias == other.alias) and (self.function == other.function) and (self.output_objs == other.output_objs) and (self._cache == other._cache)

    def __hash__(self) -> int:
        return hash((super().__hash__(), self.name, self.output, self.alias, self.function, tuple(self.output_objs), self._cache))

# Cluster 4

def extract_id_from_json_text(response_text: str, key_to_find: str='id') -> Optional[str]:
    if not response_text:
        return None
    try:
        json_match = re.search('(\\{.*\\})', response_text, re.DOTALL)
        if json_match:
            json_str = json_match.group(1)
            data = json.loads(json_str)
            if isinstance(data, dict):
                if key_to_find in data and isinstance(data[key_to_find], str):
                    return data[key_to_find]
                for k_var in ['record_id', 'evolved_id', 'plan_id', 'id']:
                    if k_var == key_to_find:
                        continue
                    if k_var in data and isinstance(data[k_var], str):
                        return data[k_var]
                for nested_key in ['record', 'evolved_record', 'saved_record', 'component', 'agent', 'tool', 'evolved_agent', 'created_agent']:
                    if nested_key in data and isinstance(data[nested_key], dict):
                        target_dict = data[nested_key]
                        if key_to_find in target_dict and isinstance(target_dict[key_to_find], str):
                            return target_dict[key_to_find]
                        if 'id' in target_dict and isinstance(target_dict['id'], str):
                            return target_dict['id']
                if 'results' in data and isinstance(data['results'], list) and data['results']:
                    if isinstance(data['results'][0], dict):
                        first_result = data['results'][0]
                        if key_to_find in first_result:
                            return first_result.get(key_to_find)
                        if 'id' in first_result:
                            return first_result.get('id')
    except Exception:
        pass
    patterns = [f'"{key_to_find}":\\s*"([^"]+)"']
    if key_to_find not in ['id', 'record_id', 'evolved_id']:
        patterns.extend([f'"record_id":\\s*"([^"]+)"', f'"evolved_id":\\s*"([^"]+)"', f'"id":\\s*"([^"]+)"'])
    patterns.extend(['ID:\\s*([a-fA-F0-9]{8}-(?:[a-fA-F0-9]{4}-){3}[a-fA-F0-9]{12}|[a-fA-F0-9]{24}|[a-zA-Z0-9_.\\-]+)', '([a-fA-F0-9]{8}-(?:[a-fA-F0-9]{4}-){3}[a-fA-F0-9]{12})'])
    for pattern in patterns:
        match = re.search(pattern, response_text)
        if match and match.group(1):
            extracted_id = match.group(1).strip()
            if len(extracted_id) > 5 and (not extracted_id.lower().startswith('http')):
                logger.info(f"Regex extracted ID '{extracted_id}' for key '{key_to_find}' using pattern: {pattern}")
                return extracted_id
    logger.warning(f"Could not extract ID for key '{key_to_find}' from SystemAgent response: {response_text[:200]}...")
    return None

class AgentFactory:
    """
    Factory for creating and executing agents across different frameworks.
    """

    def __init__(self, smart_library: SmartLibrary, llm_service: LLMService, provider_registry: Optional[ProviderRegistry]=None):
        """
        Initialize the agent factory.

        Args:
            smart_library: Smart library for retrieving agent records
            llm_service: LLM service for text generation
            provider_registry: Optional provider registry to use
        """
        self.library = smart_library
        self.llm_service = llm_service
        self.active_agents = {}
        self.provider_registry = provider_registry or ProviderRegistry()
        if not self.provider_registry.list_available_providers():
            self._register_default_providers()
        logger.info(f'Agent Factory initialized with providers: {self.provider_registry.list_available_providers()}')

    def _register_default_providers(self) -> None:
        """Register the default set of providers."""
        self.provider_registry.register_provider(BeeAIProvider(self.llm_service))
        logger.info(f'Registered default providers: {self.provider_registry.list_available_providers()}')

    def clean_code_snippet(code_snippet):
        """Clean code snippet by removing markdown formatting and fixing common syntax issues."""
        if '```' in code_snippet:
            lines = code_snippet.split('\n')
            clean_lines = []
            inside_code_block = False
            for line in lines:
                if line.strip().startswith('```'):
                    inside_code_block = not inside_code_block
                    continue
                if not inside_code_block:
                    clean_lines.append(line)
            code_snippet = '\n'.join(clean_lines)
        return code_snippet.strip()

    async def create_agent(self, record: Dict[str, Any], firmware_content: Optional[str]=None, tools: Optional[List[Any]]=None, config: Optional[Dict[str, Any]]=None) -> Any:
        """
        Create an agent instance from a library record.

        Args:
            record: Agent record from the Smart Library
            firmware_content: Optional firmware content to inject
            tools: Optional list of tools to provide to the agent
            config: Optional configuration parameters

        Returns:
            Instantiated agent
        """
        metadata = record.get('metadata', {})
        framework_name = metadata.get('framework', 'beeai')
        config = config or {}
        logger.info(f"Creating agent '{record['name']}' using framework '{framework_name}'")
        if framework_name.lower() == 'beeai':
            try:
                agent = await self._create_beeai_agent_directly(record, tools, config)
                if agent:
                    self.active_agents[record['name']] = {'record': record, 'instance': agent, 'type': 'AGENT', 'framework': framework_name, 'provider_id': 'BeeAIProvider'}
                    return agent
            except Exception as e:
                logger.warning(f'Direct BeeAI agent creation failed: {str(e)}, falling back to provider')
        provider = self.provider_registry.get_provider_for_framework(framework_name)
        if not provider:
            error_msg = f"No provider found for framework '{framework_name}'"
            logger.error(error_msg)
            raise ValueError(error_msg)
        try:
            agent_instance = await provider.create_agent(record=record, tools=tools, firmware_content=firmware_content, config=config)
            self.active_agents[record['name']] = {'record': record, 'instance': agent_instance, 'type': 'AGENT', 'framework': framework_name, 'provider_id': provider.__class__.__name__}
            logger.info(f"Successfully created agent '{record['name']}' with framework '{framework_name}'")
            return agent_instance
        except Exception as e:
            logger.error(f"Error creating agent '{record['name']}': {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            raise

    async def _create_beeai_agent_directly(self, record: Dict[str, Any], tools: Optional[List[Any]]=None, config: Optional[Dict[str, Any]]=None) -> Optional[ReActAgent]:
        """
        Attempt to create a BeeAI agent directly from the code without using a provider.

        Args:
            record: Agent record from the Smart Library
            tools: Optional tools to provide to the agent
            config: Optional configuration

        Returns:
            BeeAI agent instance if successful, None otherwise
        """
        code_snippet = record['code_snippet']
        class_match = re.search('class\\s+(\\w+)(?:\\(.*\\))?:', code_snippet)
        if not class_match:
            return None
        initializer_class_name = class_match.group(1)
        if 'def create_agent' not in code_snippet:
            return None
        try:
            module_name = f'dynamic_agent_{record['id'].replace('-', '_')}'
            with tempfile.NamedTemporaryFile(suffix='.py', delete=False, mode='w') as f:
                f.write(code_snippet)
                temp_file = f.name
            try:
                spec = importlib.util.spec_from_file_location(module_name, temp_file)
                if not spec or not spec.loader:
                    return None
                module = importlib.util.module_from_spec(spec)
                sys.modules[module_name] = module
                spec.loader.exec_module(module)
                if hasattr(module, initializer_class_name):
                    initializer_class = getattr(module, initializer_class_name)
                    if hasattr(initializer_class, 'create_agent'):
                        chat_model = self.llm_service.chat_model
                        import inspect
                        sig = inspect.signature(initializer_class.create_agent)
                        if 'tools' in sig.parameters:
                            agent = initializer_class.create_agent(chat_model, tools)
                        else:
                            agent = initializer_class.create_agent(chat_model)
                        if isinstance(agent, ReActAgent):
                            return agent
            finally:
                os.unlink(temp_file)
                if module_name in sys.modules:
                    del sys.modules[module_name]
        except Exception as e:
            logger.error(f'Error creating BeeAI agent directly: {str(e)}')
            import traceback
            logger.error(traceback.format_exc())
        return None

    async def execute_agent(self, agent_name: str, input_text: str, execution_config: Optional[Dict[str, Any]]=None) -> Dict[str, Any]:
        """
        Execute an agent by name with input text.

        Args:
            agent_name: Name of the agent to execute
            input_text: Input text to process
            execution_config: Optional execution configuration parameters

        Returns:
            Execution result dictionary
        """
        if agent_name not in self.active_agents:
            error_msg = f"Agent '{agent_name}' not found in active agents"
            logger.error(error_msg)
            return {'status': 'error', 'message': error_msg}
        agent_info = self.active_agents[agent_name]
        agent_instance = agent_info['instance']
        framework_name = agent_info.get('framework', 'default')
        logger.info(f"Executing agent '{agent_name}' using framework '{framework_name}'")
        provider = self.provider_registry.get_provider_for_framework(framework_name)
        if not provider:
            error_msg = f"No provider found for framework '{framework_name}'"
            logger.error(error_msg)
            return {'status': 'error', 'message': error_msg}
        try:
            result = await provider.execute_agent(agent_instance=agent_instance, input_text=input_text, execution_config=execution_config)
            if hasattr(self.library, 'update_usage_metrics') and 'record' in agent_info:
                await self.library.update_usage_metrics(agent_info['record']['id'], result['status'] == 'success')
            return result
        except Exception as e:
            logger.error(f"Error executing agent '{agent_name}': {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            return {'status': 'error', 'message': f"Error executing agent '{agent_name}': {str(e)}"}

class ExecuteOpenAIAgentTool(Tool[ExecuteOpenAIAgentInput, None, StringToolOutput]):
    """
    Tool for executing OpenAI agents from the Smart Library.
    This tool loads and runs agents created with the OpenAI Agents SDK.
    """
    name = 'ExecuteOpenAIAgentTool'
    description = 'Execute OpenAI agents stored in the Smart Library with input text and optional tools'
    input_schema = ExecuteOpenAIAgentInput

    def __init__(self, smart_library: SmartLibrary, openai_provider: Optional[OpenAIAgentsProvider]=None, tool_factory=None, options: Optional[Dict[str, Any]]=None):
        super().__init__(options=options or {})
        self.library = smart_library
        self.provider = openai_provider or OpenAIAgentsProvider()
        self.tool_factory = tool_factory
        self.active_agents = {}

    def _create_emitter(self) -> Emitter:
        return Emitter.root().child(namespace=['tool', 'openai', 'execute_agent'], creator=self)

    async def _run(self, input: ExecuteOpenAIAgentInput, options: Optional[Dict[str, Any]]=None, context: Optional[RunContext]=None) -> StringToolOutput:
        """
        Execute an OpenAI agent from the Smart Library.

        Args:
            input: The execution parameters

        Returns:
            StringToolOutput containing the execution result
        """
        try:
            agent_record = await self._get_agent_record(input.agent_id_or_name)
            if not agent_record:
                return StringToolOutput(json.dumps({'status': 'error', 'message': f"Agent '{input.agent_id_or_name}' not found"}, indent=2))
            metadata = agent_record.get('metadata', {})
            framework = metadata.get('framework', '').lower()
            if framework != 'openai-agents':
                return StringToolOutput(json.dumps({'status': 'error', 'message': f"Agent '{input.agent_id_or_name}' is not an OpenAI agent"}, indent=2))
            agent, tools = await self._get_or_create_agent(agent_record, input.tools_to_use, input.apply_firmware)
            result = await self._execute_agent(agent, input.input_text, input.max_turns)
            return StringToolOutput(json.dumps({'status': 'success', 'agent_name': agent_record['name'], 'input': input.input_text, 'output': result['result'], 'tools_used': [t.name for t in tools] if tools else [], 'execution_details': {'max_turns': input.max_turns, 'firmware_applied': input.apply_firmware}}, indent=2))
        except Exception as e:
            import traceback
            logger.error(f'Error executing OpenAI agent: {str(e)}')
            logger.error(traceback.format_exc())
            return StringToolOutput(json.dumps({'status': 'error', 'message': f'Error executing OpenAI agent: {str(e)}', 'details': traceback.format_exc()}, indent=2))

    async def _get_agent_record(self, agent_id_or_name: str) -> Optional[Dict[str, Any]]:
        """Get an agent record by ID or name."""
        record = await self.library.find_record_by_id(agent_id_or_name)
        if record:
            return record
        return await self.library.find_record_by_name(agent_id_or_name, 'AGENT')

    async def _get_or_create_agent(self, record: Dict[str, Any], tool_names: Optional[List[str]]=None, apply_firmware: bool=True) -> Tuple[OpenAIAgent, List[Any]]:
        """Get an existing agent instance or create a new one."""
        if record['id'] in self.active_agents:
            return (self.active_agents[record['id']]['instance'], self.active_agents[record['id']]['tools'])
        tools = []
        if tool_names and self.tool_factory:
            for tool_name in tool_names:
                tool_record = await self.library.find_record_by_name(tool_name, 'TOOL')
                if tool_record:
                    tool = await self.tool_factory.create_tool(tool_record)
                    tools.append(tool)
        openai_tools = []
        if tools:
            openai_tools = [OpenAIToolAdapter.convert_evolving_tool_to_openai(t) for t in tools]
        agent = await self.provider.create_agent(record=record, tools=openai_tools, firmware_content='Apply governance rules' if apply_firmware else None, config={'apply_firmware': apply_firmware})
        self.active_agents[record['id']] = {'instance': agent, 'tools': tools, 'record': record}
        return (agent, tools)

    async def _execute_agent(self, agent: OpenAIAgent, input_text: str, max_turns: int=10) -> Dict[str, Any]:
        """Execute an OpenAI agent with input text."""
        try:
            context = {}
            result = await Runner.run(agent, input_text, context=context, max_turns=max_turns)
            return {'status': 'success', 'result': str(result.final_output), 'raw_result': result}
        except Exception as e:
            logger.error(f'Error in _execute_agent: {str(e)}')
            import traceback
            logger.error(traceback.format_exc())
            raise

# Cluster 6

def clear_cache(args):
    """Clear the LLM cache."""
    cache = LLMCache(cache_dir=args.cache_dir)
    older_than = args.older_than * 86400 if args.older_than else None
    count = cache.clear_cache(older_than)
    logger.info(f'Cleared {count} cache entries')

def main():
    parser = argparse.ArgumentParser(description='LLM Cache Management Utilities')
    parser.add_argument('--cache-dir', type=str, default='.llm_cache', help='Cache directory')
    subparsers = parser.add_subparsers(dest='command', help='Command to run')
    clear_parser = subparsers.add_parser('clear', help='Clear the cache')
    clear_parser.add_argument('--older-than', type=int, help='Clear entries older than this many days')
    stats_parser = subparsers.add_parser('stats', help='Show cache statistics')
    stats_parser.add_argument('--verbose', '-v', action='store_true', help='Show detailed information')
    args = parser.parse_args()
    if args.command == 'clear':
        clear_cache(args)
    elif args.command == 'stats':
        cache_stats(args)
    else:
        parser.print_help()

def cache_stats(args):
    """Show cache statistics."""
    from pathlib import Path
    import json
    import time
    cache_dir = Path(args.cache_dir)
    completion_dir = cache_dir / 'completions'
    embedding_dir = cache_dir / 'embeddings'
    completion_files = list(completion_dir.glob('*.json')) if completion_dir.exists() else []
    embedding_files = list(embedding_dir.glob('*.json')) if embedding_dir.exists() else []
    completion_models = {}
    embedding_models = {}
    now = time.time()
    for file in completion_files:
        try:
            model = file.name.split('_')[0]
            completion_models[model] = completion_models.get(model, 0) + 1
            with open(file, 'r') as f:
                data = json.load(f)
            age_days = (now - data['timestamp']) / 86400
            if args.verbose:
                logger.info(f'Completion cache: {file.name}, Age: {age_days:.1f} days')
        except:
            pass
    for file in embedding_files:
        try:
            model = file.name.split('_')[0]
            embedding_models[model] = embedding_models.get(model, 0) + 1
            with open(file, 'r') as f:
                data = json.load(f)
            age_days = (now - data['timestamp']) / 86400
            if args.verbose:
                logger.info(f'Embedding cache: {file.name}, Age: {age_days:.1f} days')
        except:
            pass
    logger.info(f'LLM Cache Statistics for {cache_dir}')
    logger.info(f'Completion cache entries: {len(completion_files)}')
    for model, count in completion_models.items():
        logger.info(f'  - {model}: {count} entries')
    logger.info(f'Embedding cache entries: {len(embedding_files)}')
    for model, count in embedding_models.items():
        logger.info(f'  - {model}: {count} entries')
    total_size = sum((f.stat().st_size for f in completion_files + embedding_files))
    logger.info(f'Total cache size: {total_size / (1024 * 1024):.2f} MB')

class SmartAgentBus:

    def __init__(self, smart_library: Optional[SmartLibrary]=None, system_agent: Optional[IAgent]=None, llm_service: Optional[LLMService]=None, container: Optional[DependencyContainer]=None, mongodb_client: Optional[MongoDBClient]=None, mongodb_uri: Optional[str]=None, mongodb_db_name: Optional[str]=None, registry_collection_name: str='eat_agent_registry', logs_collection_name: str='eat_agent_bus_logs', circuit_breaker_path: str='agent_bus_circuit_breakers.json', component_experience_tracker: Optional[ComponentExperienceTracker]=None):
        self.container = container
        self._system_agent_instance = system_agent
        self._initialized = False
        self._agent_instances: Dict[str, Any] = {}
        self.circuit_breakers: Dict[str, Dict[str, Any]] = {}
        self.circuit_breaker_path = circuit_breaker_path
        self.mongodb_client: Optional[MongoDBClient] = None
        self.registry_collection: Optional[motor.motor_asyncio.AsyncIOMotorCollection] = None
        self.logs_collection: Optional[motor.motor_asyncio.AsyncIOMotorCollection] = None
        if container:
            self.smart_library = smart_library or container.get('smart_library', None)
            self.llm_service = llm_service or container.get('llm_service', None)
            if not self.llm_service:
                self.llm_service = LLMService(container=container)
                container.register('llm_service', self.llm_service)
        else:
            self.smart_library = smart_library
            self.llm_service = llm_service or LLMService()
        if mongodb_client is not None:
            self.mongodb_client = mongodb_client
            logger.debug('SmartAgentBus: Using directly passed MongoDBClient.')
        elif container and container.has('mongodb_client'):
            self.mongodb_client = container.get('mongodb_client')
            logger.debug('SmartAgentBus: Using MongoDBClient from container.')
        else:
            logger.warning('SmartAgentBus: MongoDBClient not passed directly or found in container. Attempting to create new instance.')
            try:
                self.mongodb_client = MongoDBClient(uri=mongodb_uri, db_name=mongodb_db_name)
                if container:
                    container.register('mongodb_client', self.mongodb_client)
            except ValueError as e:
                logger.error(f'SmartAgentBus: Failed to initialize default MongoDBClient: {e}. DB operations will fail.')
                self.mongodb_client = None
        if self.mongodb_client:
            if not isinstance(self.mongodb_client.client, motor.motor_asyncio.AsyncIOMotorClient):
                logger.critical('SmartAgentBus: MongoDBClient is NOT using an AsyncIOMotorClient (Motor). Async DB ops will fail.')
                self.registry_collection = None
                self.logs_collection = None
            else:
                self.registry_collection_name = registry_collection_name
                self.logs_collection_name = logs_collection_name
                self.registry_collection = self.mongodb_client.get_collection(self.registry_collection_name)
                self.logs_collection = self.mongodb_client.get_collection(self.logs_collection_name)
                asyncio.create_task(self._ensure_registry_indexes_and_load())
        else:
            logger.error('SmartAgentBus: MongoDBClient is not available. Database operations will not be possible.')
            self.registry_collection_name = 'N/A (MongoDB unavailable)'
            self.logs_collection_name = 'N/A (MongoDB unavailable)'
            self.registry_collection = None
            self.logs_collection = None
        self.experience_tracker = None
        if component_experience_tracker:
            self.experience_tracker = component_experience_tracker
            logger.debug('SmartAgentBus: Using directly passed ComponentExperienceTracker.')
        elif self.container and self.container.has('component_experience_tracker'):
            self.experience_tracker = self.container.get('component_experience_tracker')
            logger.debug('SmartAgentBus: Using ComponentExperienceTracker from container.')
        elif self.mongodb_client:
            try:
                self.experience_tracker = ComponentExperienceTracker(mongodb_client=self.mongodb_client)
                logger.info('SmartAgentBus: Initialized new ComponentExperienceTracker instance.')
                if self.container and (not self.container.has('component_experience_tracker')):
                    self.container.register('component_experience_tracker', self.experience_tracker)
            except Exception as e:
                logger.error(f'SmartAgentBus: Failed to initialize ComponentExperienceTracker: {e}', exc_info=True)
        else:
            logger.warning('SmartAgentBus: ComponentExperienceTracker not provided and MongoDBClient unavailable for its auto-init.')
        self.agents: Dict[str, Dict[str, Any]] = {}
        self._load_circuit_breakers()
        if container and (not container.has('agent_bus')):
            container.register('agent_bus', self)
        logger.info(f"SmartAgentBus initialized. Registry: '{self.registry_collection_name}', Logs: '{self.logs_collection_name}'")

    @property
    def system_agent(self) -> Optional[IAgent]:
        if not self._system_agent_instance and self.container and self.container.has('system_agent'):
            self._system_agent_instance = self.container.get('system_agent')
        return self._system_agent_instance

    async def _ensure_registry_indexes_and_load(self):
        """Ensure MongoDB indexes for the agent registry and load data into memory."""
        if self.registry_collection is None:
            logger.error(f"Cannot ensure indexes: registry_collection '{self.registry_collection_name}' is None.")
            return
        try:
            await self.registry_collection.create_index([('id', pymongo.ASCENDING)], unique=True, background=True)
            await self.registry_collection.create_index([('name', pymongo.ASCENDING)], background=True)
            await self.registry_collection.create_index([('status', pymongo.ASCENDING)], background=True)
            await self.registry_collection.create_index([('type', pymongo.ASCENDING)], background=True)
            await self.registry_collection.create_index([('capabilities.id', pymongo.ASCENDING)], background=True)
            await self.registry_collection.create_index([('description', pymongo.TEXT)], name='description_text_index', background=True)
            logger.info(f"Ensured standard indexes on '{self.registry_collection_name}'.")
            logger.info("Reminder: For vector search on agent descriptions (field 'description_embedding'), ensure an Atlas Vector Search index (e.g., 'vector_index_agent_description') is configured manually on the 'description_embedding' field.")
        except Exception as e:
            logger.error(f'Error creating MongoDB indexes for {self.registry_collection_name}: {e}', exc_info=True)
        await self._load_registry_from_db()

    async def _load_registry_from_db(self) -> None:
        """Load all agent records from MongoDB into the in-memory self.agents dictionary."""
        if self.registry_collection is None:
            logger.error('Registry collection is not initialized. Cannot load from DB.')
            return
        logger.info(f"Loading agent registry from MongoDB collection '{self.registry_collection_name}'...")
        self.agents = {}
        try:
            projection = {'_id': 0, 'description_embedding': 0, 'capabilities.description_embedding': 0}
            cursor = self.registry_collection.find({}, projection)
            async for agent_doc in cursor:
                self.agents[agent_doc['id']] = agent_doc
            logger.info(f'Loaded {len(self.agents)} agents from MongoDB into in-memory cache.')
        except Exception as e:
            logger.error(f'Error loading agent registry from MongoDB: {e}', exc_info=True)

    def _load_circuit_breakers(self) -> None:
        if os.path.exists(self.circuit_breaker_path):
            try:
                with open(self.circuit_breaker_path, 'r') as f:
                    self.circuit_breakers = json.load(f)
                logger.info(f'Loaded {len(self.circuit_breakers)} circuit breaker states from {self.circuit_breaker_path}')
            except Exception as e:
                logger.error(f'Error loading circuit breakers: {e}')
                self.circuit_breakers = {}
        else:
            logger.info(f'Circuit breaker file {self.circuit_breaker_path} not found. Starting with empty states.')
            self.circuit_breakers = {}

    async def _save_circuit_breakers(self) -> None:
        try:
            with open(self.circuit_breaker_path, 'w') as f:
                json.dump(self.circuit_breakers, f, indent=2)
        except Exception as e:
            logger.error(f'Error saving circuit breakers: {e}')

    async def initialize_from_library(self) -> None:
        if self._initialized:
            logger.debug('AgentBus already initialized from library.')
            return
        if not self.smart_library:
            logger.warning('SmartLibrary not provided; cannot initialize AgentBus from library.')
            return
        logger.info('AgentBus initializing from SmartLibrary...')
        try:
            agent_records = await self.smart_library.export_records(record_type='AGENT')
            tool_records = await self.smart_library.export_records(record_type='TOOL')
        except ConnectionError as e:
            logger.error(f'Failed to export records from SmartLibrary due to DB connection issue: {e}')
            return
        library_records = agent_records + tool_records
        initialized_count = 0
        for record in library_records:
            if record.get('status') != 'active':
                logger.debug(f"Skipping record {record['id']} from SmartLibrary during init as it's not 'active' (status: {record.get('status')}).")
                continue
            if record['id'] in self.agents:
                logger.info(f'Agent {record['id']} already in bus registry. Re-registering to sync with SmartLibrary.')
            capabilities = record.get('metadata', {}).get('capabilities', [])
            if not capabilities and record.get('name'):
                cap_id = f'{record['name'].lower().replace(' ', '_')}_default_capability'
                capabilities = [{'id': cap_id, 'name': record['name'], 'description': record.get('description', f'Default capability for {record['name']}'), 'confidence': 0.7}]
            agent_instance = None
            if self.container:
                agent_factory = self.container.get('agent_factory', None)
                tool_factory = self.container.get('tool_factory', None)
                try:
                    if record['record_type'] == 'AGENT' and agent_factory:
                        agent_instance = await agent_factory.create_agent(record)
                    elif record['record_type'] == 'TOOL' and tool_factory:
                        agent_instance = await tool_factory.create_tool(record)
                except Exception as e:
                    logger.error(f'Instance creation failed for SmartLibrary component {record.get('name')} ({record.get('id')}): {e}', exc_info=True)
            try:
                await self.register_agent(agent_id=record['id'], name=record['name'], description=record.get('description', ''), capabilities=capabilities, agent_type=record.get('record_type', 'GENERIC'), metadata={'source': 'SmartLibrary', **record.get('metadata', {})}, agent_instance=agent_instance, embed_capabilities=True)
                initialized_count += 1
            except RuntimeError as reg_err:
                logger.error(f'Failed to register/update agent {record['name']} during library sync: {reg_err}')
            except Exception as e:
                logger.error(f'Unexpected error processing record {record['name']} ({record['id']}) during library sync: {e}', exc_info=True)
        self._initialized = True
        logger.info(f'AgentBus initialization/sync from SmartLibrary processed. Updated/Registered {initialized_count} active components.')

    async def update_agent_from_library(self, agent_id: str) -> bool:
        """
        Updates a single agent's definition and status in the AgentBus
        based on its state in the SmartLibrary.
        """
        if not self.smart_library:
            logger.error(f'SmartLibrary not available. Cannot update agent {agent_id}.')
            return False
        if self.registry_collection is None:
            logger.error(f'AgentBus registry collection not available. Cannot update agent {agent_id}.')
            return False
        logger.info(f'Attempting to update agent {agent_id} in AgentBus from SmartLibrary.')
        try:
            library_record = await self.smart_library.find_record_by_id(agent_id)
        except Exception as e:
            logger.error(f'Error fetching record {agent_id} from SmartLibrary: {e}', exc_info=True)
            return False
        if not library_record:
            logger.warning(f'Agent {agent_id} not found in SmartLibrary. Considering removal from AgentBus.')
            return False
        library_status = library_record.get('status')
        agent_name = library_record.get('name', agent_id)
        if library_status == 'active' or library_status == 'deployed':
            logger.info(f"Agent {agent_id} ({agent_name}) is '{library_status}' in SmartLibrary. Registering/updating in AgentBus.")
            try:
                capabilities = library_record.get('metadata', {}).get('capabilities', [])
                if not capabilities and library_record.get('name'):
                    cap_id = f'{library_record['name'].lower().replace(' ', '_')}_default_capability'
                    capabilities = [{'id': cap_id, 'name': library_record['name'], 'description': library_record.get('description', f'Default capability for {library_record['name']}'), 'confidence': 0.7}]
                agent_instance = None
                if self.container:
                    agent_factory = self.container.get('agent_factory', None)
                    tool_factory = self.container.get('tool_factory', None)
                    try:
                        if library_record.get('record_type') == 'AGENT' and agent_factory:
                            agent_instance = await agent_factory.create_agent(library_record)
                        elif library_record.get('record_type') == 'TOOL' and tool_factory:
                            agent_instance = await tool_factory.create_tool(library_record)
                    except Exception as e_inst:
                        logger.warning(f'Instance creation failed for {agent_id} during update_agent_from_library: {e_inst}', exc_info=False)
                await self.register_agent(agent_id=library_record['id'], name=library_record['name'], description=library_record.get('description', ''), capabilities=capabilities, agent_type=library_record.get('record_type', 'GENERIC'), metadata={'source': 'SmartLibrary_update', **library_record.get('metadata', {})}, agent_instance=agent_instance, embed_capabilities=True)
                logger.info(f'Successfully registered/updated agent {agent_id} ({agent_name}) in AgentBus from SmartLibrary.')
                return True
            except Exception as e_reg:
                logger.error(f'Failed to register/update agent {agent_id} ({agent_name}) in AgentBus: {e_reg}', exc_info=True)
                return False
        elif library_status == 'archived' or library_status == 'inactive':
            logger.info(f"Agent {agent_id} ({agent_name}) is '{library_status}' in SmartLibrary. Updating status in AgentBus and removing instance.")
            update_result = await self.registry_collection.update_one({'id': agent_id}, {'$set': {'status': library_status, 'last_updated': datetime.now(timezone.utc)}})
            if agent_id in self.agents:
                self.agents[agent_id]['status'] = library_status
                self.agents[agent_id]['last_updated'] = datetime.now(timezone.utc).isoformat()
            if agent_id in self._agent_instances:
                del self._agent_instances[agent_id]
                logger.debug(f'Removed live instance of archived agent {agent_id} ({agent_name}) from AgentBus cache.')
            if update_result.modified_count > 0 or update_result.matched_count > 0:
                logger.info(f"Successfully updated status of agent {agent_id} ({agent_name}) to '{library_status}' in AgentBus registry.")
                return True
            else:
                logger.warning(f"Agent {agent_id} ({agent_name}) was not found in AgentBus registry for status update to '{library_status}', but was '{library_status}' in library.")
                return True
        else:
            logger.warning(f"Agent {agent_id} ({agent_name}) has an unhandled status '{library_status}' in SmartLibrary. No action taken in AgentBus.")
            return False

    async def _log_agent_execution(self, bus_type: str, agent_id: str, task: Dict[str, Any], result: Optional[Dict[str, Any]]=None, error: Optional[str]=None, duration: Optional[float]=None) -> None:
        if self.logs_collection is None:
            logger.warning('Logs collection not available. Skipping log.')
            return
        agent_name = self.agents.get(agent_id, {}).get('name', 'N/A') if agent_id != 'N/A' else 'N/A'
        log_entry = {'log_id': f'log_{uuid.uuid4().hex[:12]}', 'timestamp': datetime.now(timezone.utc), 'bus_type': bus_type, 'agent_id': agent_id, 'agent_name': agent_name, 'task_description': task.get('capability') or task.get('operation', 'direct_execution'), 'task_details': task, 'result': result, 'error': error, 'duration_ms': int(duration * 1000) if duration is not None else None}
        try:
            for key in ['task_details', 'result']:
                if isinstance(log_entry[key], dict):
                    log_entry[key] = json.loads(json.dumps(log_entry[key], default=str))
            await self.logs_collection.insert_one(log_entry)
        except Exception as e:
            logger.error(f'Failed to write execution log to MongoDB: {e}', exc_info=True)
        if self.experience_tracker:
            try:
                input_params_for_experience = task.get('content', task) if isinstance(task.get('content'), dict) else task
                component_type = 'UNKNOWN'
                if agent_id != 'N/A' and agent_id in self.agents:
                    component_type = self.agents[agent_id].get('type', 'UNKNOWN')
                output_summary_for_experience = None
                if result and isinstance(result, dict):
                    output_summary_for_experience = str(result.get('content_summary', result))[:500]
                elif result:
                    output_summary_for_experience = str(result)[:500]
                await self.experience_tracker.record_event(component_id=agent_id, name=agent_name, record_type=component_type, duration_ms=duration * 1000 if duration is not None else 0.0, success=error is None, error=error, input_params=input_params_for_experience, output_summary=output_summary_for_experience)
            except Exception as e:
                logger.error(f'SmartAgentBus: Failed to record event with ComponentExperienceTracker for agent {agent_id}: {e}', exc_info=True)

    def _check_circuit_breaker(self, agent_id: str) -> bool:
        if agent_id not in self.circuit_breakers:
            return False
        cb = self.circuit_breakers[agent_id]
        failures = cb.get('failures', 0)
        last_failure_time = cb.get('last_failure', 0.0)
        if failures >= 3 and time.time() - last_failure_time < 300:
            logger.warning(f'Circuit breaker tripped for agent {agent_id}. Failures: {failures}, Last failure: {datetime.fromtimestamp(last_failure_time).isoformat()}')
            return True
        return False

    async def _record_failure(self, agent_id: str) -> None:
        if agent_id not in self.circuit_breakers:
            self.circuit_breakers[agent_id] = {'failures': 0, 'last_failure': 0.0}
        self.circuit_breakers[agent_id]['failures'] = self.circuit_breakers[agent_id].get('failures', 0) + 1
        self.circuit_breakers[agent_id]['last_failure'] = time.time()
        await self._save_circuit_breakers()
        logger.warning(f'Failure recorded for agent {agent_id}. Total failures: {self.circuit_breakers[agent_id]['failures']}. Last failure: {datetime.fromtimestamp(self.circuit_breakers[agent_id]['last_failure']).isoformat()}')

    async def _reset_circuit_breaker(self, agent_id: str) -> None:
        if agent_id in self.circuit_breakers:
            logger.info(f'Resetting circuit breaker for agent {agent_id}')
            del self.circuit_breakers[agent_id]
            await self._save_circuit_breakers()

    async def register_agent(self, name: str, description: str, capabilities: List[Dict[str, Any]], agent_type: str='GENERIC', metadata: Optional[Dict[str, Any]]=None, agent_instance=None, agent_id: Optional[str]=None, embed_capabilities: bool=False) -> str:
        if self.registry_collection is None:
            logger.error('Registry collection not available. Cannot register agent.')
            raise RuntimeError('Agent registry (MongoDB) is not available.')
        if not self.llm_service:
            logger.error('LLMService not available. Cannot generate embeddings for agent registration.')
            raise RuntimeError('LLMService is required for agent registration if embeddings are needed.')
        if not agent_id:
            agent_id = f'agent_{uuid.uuid4().hex[:8]}'
        cap_names_str = ', '.join((c.get('name', c.get('id', '')) for c in capabilities))
        agent_desc_for_embedding = f'Agent Name: {name}\nType: {agent_type}\nDescription: {description}\nCapabilities Offered: {cap_names_str}'
        description_embedding = []
        try:
            description_embedding = await self.llm_service.embed(agent_desc_for_embedding)
        except Exception as e:
            logger.error(f"Embedding generation failed for agent '{name}' description: {e}", exc_info=True)
            description_embedding = [0.0] * DEFAULT_AGENT_EMBEDDING_DIM
        processed_capabilities = []
        for cap_data in capabilities:
            cap_id = cap_data.get('id', f'{cap_data.get('name', 'capability').lower().replace(' ', '_')}_{uuid.uuid4().hex[:4]}')
            cap = {'id': cap_id, 'name': cap_data.get('name', cap_id), 'description': cap_data.get('description', f'Default description for {cap_id}'), 'confidence': cap_data.get('confidence', 0.8)}
            if embed_capabilities and cap['description']:
                try:
                    cap['description_embedding'] = await self.llm_service.embed(cap['description'])
                except Exception as e:
                    logger.error(f"Embedding generation failed for capability '{cap['name']}': {e}", exc_info=True)
                    cap['description_embedding'] = [0.0] * DEFAULT_AGENT_EMBEDDING_DIM
            processed_capabilities.append(cap)
        current_time = datetime.now(timezone.utc)
        existing_doc = await self.registry_collection.find_one({'id': agent_id}, {'registered_at': 1})
        registered_at = existing_doc.get('registered_at', current_time) if existing_doc else current_time
        agent_doc = {'id': agent_id, 'name': name, 'description': description, 'type': agent_type, 'capabilities': processed_capabilities, 'metadata': metadata or {}, 'status': 'active', 'description_embedding': description_embedding, 'registered_at': registered_at, 'last_updated': current_time, 'last_seen': current_time}
        try:
            result = await self.registry_collection.replace_one({'id': agent_id}, agent_doc, upsert=True)
            op_type = 'Registered new' if result.upserted_id else 'Updated' if result.modified_count > 0 else 'Refreshed (no change)'
            cached_doc = agent_doc.copy()
            cached_doc.pop('description_embedding', None)
            for cap_item in cached_doc.get('capabilities', []):
                cap_item.pop('description_embedding', None)
            self.agents[agent_id] = cached_doc
            if agent_instance:
                self._agent_instances[agent_id] = agent_instance
            await self._log_agent_execution('system', agent_id, {'operation': 'register', 'details': {'name': name, 'type': agent_type, 'capabilities_count': len(capabilities)}}, {'status': 'success', 'type': op_type})
            logger.info(f'{op_type} agent: {name} ({agent_id}) in MongoDB registry.')
            return agent_id
        except Exception as e:
            logger.error(f'MongoDB registration error for agent {name}: {e}', exc_info=True)
            raise

    async def discover_agents(self, task_description: Optional[str]=None, capability_id: Optional[str]=None, min_confidence: float=0.6, agent_type: Optional[str]=None, limit: int=5) -> List[Dict[str, Any]]:
        if self.registry_collection is None:
            logger.error('Registry collection unavailable. Cannot discover agents.')
            return []
        if not task_description and (not capability_id):
            raise ValueError('Either task_description or capability_id must be provided for agent discovery.')
        matches: List[Dict[str, Any]] = []
        projection = {'_id': 0, 'description_embedding': 0}
        if capability_id:
            logger.debug(f"Discovering agents by capability_id '{capability_id}' via metadata query.")
            query_filter: Dict[str, Any] = {'status': 'active', 'capabilities.id': capability_id}
            if agent_type:
                query_filter['type'] = agent_type
            cursor = self.registry_collection.find(query_filter, projection).limit(limit * 2)
            async for agent_doc in cursor:
                cap_conf = 0.0
                for cap_item in agent_doc.get('capabilities', []):
                    if cap_item.get('id') == capability_id:
                        cap_conf = cap_item.get('confidence', 0.0)
                        break
                if cap_conf >= min_confidence:
                    is_healthy = not self._check_circuit_breaker(agent_doc['id'])
                    if is_healthy:
                        matches.append({**agent_doc, 'similarity_score': cap_conf, 'is_healthy': True})
            matches.sort(key=lambda x: x.get('similarity_score', 0.0), reverse=True)
        elif task_description:
            if not self.llm_service:
                logger.error('LLMService not available for embedding task description. Cannot perform vector search for agents.')
                return []
            logger.debug(f"Discovering agents by task_description '{task_description[:50]}...' using vector search on 'description_embedding'.")
            try:
                query_embedding = await self.llm_service.embed(task_description)
                atlas_vs_index_name = 'vector_index_agent_description'
                vs_stage_definition: Dict[str, Any] = {'index': atlas_vs_index_name, 'path': 'description_embedding', 'queryVector': query_embedding, 'numCandidates': limit * 15, 'limit': limit * 3}
                mql_filter_conditions = []
                if agent_type:
                    mql_filter_conditions.append({'type': agent_type})
                mql_filter_conditions.append({'status': 'active'})
                if mql_filter_conditions:
                    vs_stage_definition['filter'] = {'$and': mql_filter_conditions} if len(mql_filter_conditions) > 1 else mql_filter_conditions[0]
                pipeline = [{'$vectorSearch': vs_stage_definition}, {'$project': {**projection, 'similarity_score': {'$meta': 'vectorSearchScore'}}}]
                logger.debug(f'SmartAgentBus discover_agents ($vectorSearch) pipeline: {json.dumps(pipeline)}')
                cursor = self.registry_collection.aggregate(pipeline)
                async for agent_doc in cursor:
                    if agent_doc.get('similarity_score', 0.0) >= min_confidence:
                        is_healthy = not self._check_circuit_breaker(agent_doc['id'])
                        if is_healthy:
                            matches.append({**agent_doc, 'is_healthy': True})
            except pymongo.errors.OperationFailure as e:
                logger.error(f'Vector search for agents failed: {e}. No fallback implemented for this path.', exc_info=True)
                if 'index not found' in str(e).lower() or 'Unknown $vectorSearch index' in str(e).lower() or 'unknown search index' in str(e).lower() or ('Invalid $vectorSearch' in str(e).lower()):
                    logger.error(f"CRITICAL: Atlas Vector Search index '{atlas_vs_index_name}' likely missing or misconfigured on collection '{self.registry_collection_name}'. Query: {vs_stage_definition}")
            except Exception as e:
                logger.error(f'Unexpected error during agent discovery with vector search: {e}', exc_info=True)
        return matches[:limit]

    async def request_capability(self, capability: str, content: Dict[str, Any], min_confidence: float=0.6, specific_agent_id: Optional[str]=None, timeout: float=60.0) -> Dict[str, Any]:
        if self.registry_collection is None:
            logger.error('Registry collection unavailable. Cannot request capability.')
            raise RuntimeError('Agent registry (MongoDB) is not available for capability request.')
        logger.info(f"Received data bus request for capability '{capability}'")
        start_time = time.time()
        agent_to_use_doc = None
        agent_id_to_use = None
        task_details = {'capability': capability, 'content_summary': str(content)[:200]}
        if specific_agent_id:
            agent_to_use_doc = self.agents.get(specific_agent_id)
            if not (agent_to_use_doc and agent_to_use_doc.get('status') == 'active'):
                db_doc = await self.registry_collection.find_one({'id': specific_agent_id, 'status': 'active'}, {'_id': 0, 'description_embedding': 0})
                if db_doc:
                    agent_to_use_doc = db_doc
                    self.agents[specific_agent_id] = db_doc
                else:
                    error_msg = f'Targeted agent {specific_agent_id} not found or not active in registry.'
                    await self._log_agent_execution('data', specific_agent_id or 'N/A', task_details, error=error_msg, duration=time.time() - start_time)
                    raise ValueError(error_msg)
            agent_id_to_use = specific_agent_id
            logger.debug(f'Targeting specific agent: {agent_id_to_use} ({agent_to_use_doc.get('name')})')
        else:
            suitable_agents_info = await self.discover_agents(task_description=capability, capability_id=capability, min_confidence=min_confidence)
            if not suitable_agents_info:
                error_msg = f"No healthy agent found for capability '{capability}' with confidence >= {min_confidence}."
                await self._log_agent_execution('data', 'N/A', task_details, error=error_msg, duration=time.time() - start_time)
                raise ValueError(error_msg)
            best_agent_info = suitable_agents_info[0]
            agent_id_to_use = best_agent_info['id']
            agent_to_use_doc = best_agent_info
            logger.debug(f"Discovered agent {agent_id_to_use} ({agent_to_use_doc.get('name')}) for capability '{capability}' with score {best_agent_info.get('similarity_score', 0.0):.2f}.")
        if not agent_to_use_doc:
            critical_error_msg = f"Internal error: Agent ID '{agent_id_to_use}' selected but document could not be retrieved/found."
            await self._log_agent_execution('data', agent_id_to_use or 'N/A', task_details, error=critical_error_msg, duration=time.time() - start_time)
            raise RuntimeError(critical_error_msg)
        if self._check_circuit_breaker(agent_id_to_use):
            error_msg = f'Agent {agent_id_to_use} ({agent_to_use_doc.get('name')}) is temporarily unavailable (circuit breaker tripped).'
            await self._log_agent_execution('data', agent_id_to_use, task_details, error=error_msg, duration=time.time() - start_time)
            raise RuntimeError(error_msg)
        try:
            result_data = await asyncio.wait_for(self._execute_agent_task(agent_to_use_doc, task=content), timeout=timeout)
            await self._reset_circuit_breaker(agent_id_to_use)
            current_time = datetime.now(timezone.utc)
            await self.registry_collection.update_one({'id': agent_id_to_use}, {'$set': {'last_seen': current_time}})
            if agent_id_to_use in self.agents:
                self.agents[agent_id_to_use]['last_seen'] = current_time.isoformat()
            duration = time.time() - start_time
            response = {'status': 'success', 'agent_id': agent_id_to_use, 'agent_name': agent_to_use_doc.get('name'), 'capability_executed': capability, 'content': result_data, 'metadata': {'processing_time_ms': int(duration * 1000)}}
            await self._log_agent_execution('data', agent_id_to_use, task_details, result={'content_summary': str(result_data)[:200]}, duration=duration)
            logger.info(f"Capability '{capability}' executed by {agent_id_to_use} successfully in {duration:.2f}s.")
            return response
        except asyncio.TimeoutError:
            await self._record_failure(agent_id_to_use)
            error_msg = f"Agent {agent_id_to_use} ({agent_to_use_doc.get('name')}) timed out for capability '{capability}' after {timeout}s."
            await self._log_agent_execution('data', agent_id_to_use, task_details, error=error_msg, duration=timeout)
            raise RuntimeError(error_msg)
        except Exception as e:
            await self._record_failure(agent_id_to_use)
            error_msg = f"Agent {agent_id_to_use} ({agent_to_use_doc.get('name')}) failed capability '{capability}': {str(e)}"
            await self._log_agent_execution('data', agent_id_to_use, task_details, error=error_msg, duration=time.time() - start_time)
            logger.error(f"Capability execution error for agent {agent_id_to_use} on capability '{capability}': {e}", exc_info=True)
            raise RuntimeError(error_msg)

    async def execute_with_agent(self, agent_id: str, task: Dict[str, Any], timeout: float=30.0) -> Dict[str, Any]:
        if self.registry_collection is None:
            logger.error('Registry collection unavailable. Cannot execute agent.')
            raise RuntimeError('Agent registry (MongoDB) is not available for agent execution.')
        logger.info(f'Received direct execution request for agent {agent_id}')
        start_time = time.time()
        task_summary_for_log = {'task_summary': str(task)[:200]}
        agent_doc = self.agents.get(agent_id)
        if not agent_doc:
            agent_doc_db = await self.registry_collection.find_one({'id': agent_id}, {'_id': 0, 'description_embedding': 0})
            if agent_doc_db:
                self.agents[agent_id] = agent_doc_db
                agent_doc = agent_doc_db
        if not agent_doc:
            raise ValueError(f"Agent with ID '{agent_id}' not found in registry.")
        if agent_doc.get('status') != 'active':
            raise ValueError(f'Agent {agent_id} ({agent_doc.get('name')}) is not active.')
        if self._check_circuit_breaker(agent_id):
            error_msg = f'Agent {agent_id} ({agent_doc.get('name')}) temporarily unavailable (circuit breaker).'
            await self._log_agent_execution('system', agent_id, task_summary_for_log, error=error_msg, duration=time.time() - start_time)
            raise RuntimeError(error_msg)
        try:
            result_data = await asyncio.wait_for(self._execute_agent_task(agent_doc, task), timeout=timeout)
            await self._reset_circuit_breaker(agent_id)
            current_time = datetime.now(timezone.utc)
            await self.registry_collection.update_one({'id': agent_id}, {'$set': {'last_seen': current_time}})
            if agent_id in self.agents:
                self.agents[agent_id]['last_seen'] = current_time.isoformat()
            duration = time.time() - start_time
            response = {'result': result_data, 'metadata': {'agent_id': agent_id, 'agent_name': agent_doc.get('name'), 'processing_time_ms': int(duration * 1000), 'success': True}}
            await self._log_agent_execution('system', agent_id, task_summary_for_log, result={'result_summary': str(result_data)[:200]}, duration=duration)
            logger.info(f'Direct execution for agent {agent_id} completed successfully in {duration:.2f}s.')
            return response
        except asyncio.TimeoutError:
            await self._record_failure(agent_id)
            error_msg = f'Agent {agent_id} ({agent_doc.get('name')}) timed out (direct execution) after {timeout}s.'
            await self._log_agent_execution('system', agent_id, task_summary_for_log, error=error_msg, duration=timeout)
            raise RuntimeError(error_msg)
        except Exception as e:
            await self._record_failure(agent_id)
            error_msg = f'Agent {agent_id} ({agent_doc.get('name')}) failed (direct execution): {str(e)}'
            await self._log_agent_execution('system', agent_id, task_summary_for_log, error=error_msg, duration=time.time() - start_time)
            logger.error(f'Direct agent execution error for agent {agent_id}: {e}', exc_info=True)
            raise RuntimeError(error_msg)

    async def _execute_agent_task(self, agent_record_doc: Dict[str, Any], task: Dict[str, Any]) -> Any:
        """Internal helper to execute a task on an agent instance."""
        agent_id = agent_record_doc['id']
        agent_instance = self._agent_instances.get(agent_id)
        if not agent_instance:
            logger.warning(f'Live instance for agent {agent_id} ({agent_record_doc.get('name')}) not found in cache, attempting dynamic creation...')
            if self.container:
                agent_factory = self.container.get('agent_factory', None)
                tool_factory = self.container.get('tool_factory', None)
                created = False
                record_type = agent_record_doc.get('type', 'AGENT')
                if 'record_type' in agent_record_doc:
                    record_type = agent_record_doc['record_type']
                if agent_factory and record_type == 'AGENT':
                    try:
                        agent_instance = await agent_factory.create_agent(agent_record_doc)
                        created = True
                    except Exception as e:
                        logger.error(f'Dynamic AGENT creation failed for {agent_id}: {e}', exc_info=True)
                        raise RuntimeError(f'Failed to dynamically create AGENT instance for {agent_id}: {e}') from e
                elif tool_factory and record_type == 'TOOL':
                    try:
                        agent_instance = await tool_factory.create_tool(agent_record_doc)
                        created = True
                    except Exception as e:
                        logger.error(f'Dynamic TOOL creation failed for {agent_id}: {e}', exc_info=True)
                        raise RuntimeError(f'Failed to dynamically create TOOL instance for {agent_id}: {e}') from e
                if created and agent_instance:
                    self._agent_instances[agent_id] = agent_instance
                    logger.info(f'Dynamically created and cached live instance for {agent_id} (type: {record_type})')
                elif not agent_factory and (not tool_factory):
                    raise RuntimeError(f'No agent_factory or tool_factory available in container to create instance for {agent_id}')
                elif record_type == 'AGENT' and (not agent_factory) or (record_type == 'TOOL' and (not tool_factory)):
                    raise RuntimeError(f'No suitable factory found for component {agent_id} of type {record_type}')
            else:
                raise RuntimeError(f'No live instance for agent {agent_id} and no DependencyContainer available for dynamic instantiation.')
        if hasattr(agent_instance, 'run') and callable(agent_instance.run):
            try:
                input_for_run = task.get('text', task) if isinstance(task, dict) else task
                if not isinstance(input_for_run, (str, dict)):
                    input_for_run = str(input_for_run)
                logger.debug(f'Executing .run() on instance for agent {agent_id} with input type {type(input_for_run)}')
                run_result = await agent_instance.run(input_for_run)
                if hasattr(run_result, 'result') and hasattr(run_result.result, 'text'):
                    return run_result.result.text
                elif hasattr(run_result, 'text'):
                    return run_result.text
                elif isinstance(run_result, str):
                    return run_result
                try:
                    return json.loads(json.dumps(run_result, default=str))
                except:
                    return str(run_result)
            except Exception as e:
                logger.error(f'Execution via .run() method failed for agent {agent_id}: {e}', exc_info=True)
                raise RuntimeError(f"Agent's .run() method failed: {e}") from e
        elif agent_record_doc.get('metadata', {}).get('framework') == 'openai-agents':
            if self.container and self.container.has('agent_factory'):
                agent_factory = self.container.get('agent_factory')
                if not hasattr(agent_factory, 'provider_registry'):
                    raise RuntimeError('AgentFactory does not have a provider_registry attribute.')
                provider = agent_factory.provider_registry.get_provider_for_framework('openai-agents')
                if provider:
                    try:
                        input_text = task.get('text', json.dumps(task) if isinstance(task, dict) else str(task))
                        logger.debug(f'Executing OpenAI agent {agent_id} via provider with input_text.')
                        exec_result = await provider.execute_agent(agent_instance, input_text)
                        if exec_result.get('status') == 'success':
                            return exec_result.get('result')
                        else:
                            raise RuntimeError(f'OpenAI Agent execution via provider failed: {exec_result.get('message', 'No message')}')
                    except Exception as e:
                        logger.error(f'Execution of OpenAI agent {agent_id} via provider failed: {e}', exc_info=True)
                        raise RuntimeError(f'OpenAI agent execution failed: {e}') from e
                else:
                    raise RuntimeError(f'OpenAI Agents provider not found in registry for agent {agent_id}.')
            else:
                raise RuntimeError(f'AgentFactory not available in container for executing OpenAI agent {agent_id}.')
        raise RuntimeError(f'No recognized execution method for agent {agent_id} (type: {type(agent_instance)}, framework: {agent_record_doc.get('metadata', {}).get('framework')})')

    async def get_agent_status(self, agent_id: str) -> Dict[str, Any]:
        if self.registry_collection is None:
            logger.error('Registry collection unavailable. Cannot get agent status.')
            raise RuntimeError('Agent registry (MongoDB) is not available for getting agent status.')
        agent_data = self.agents.get(agent_id)
        if not agent_data:
            agent_data_db = await self.registry_collection.find_one({'id': agent_id}, {'_id': 0, 'description_embedding': 0})
            if not agent_data_db:
                raise ValueError(f"Agent with ID '{agent_id}' not found in registry.")
            self.agents[agent_id] = agent_data_db
            agent_data = agent_data_db
        status_dict = {**agent_data, 'health_status': 'healthy' if not self._check_circuit_breaker(agent_id) else 'unhealthy (circuit breaker tripped)', 'is_instance_loaded': agent_id in self._agent_instances}
        if agent_id in self.circuit_breakers:
            cb_info = self.circuit_breakers[agent_id]
            status_dict.update({'circuit_breaker_failures': cb_info.get('failures', 0), 'circuit_breaker_last_failure': datetime.fromtimestamp(cb_info.get('last_failure', 0)).isoformat() if cb_info.get('last_failure') else None})
        else:
            status_dict.update({'circuit_breaker_failures': 0, 'circuit_breaker_last_failure': None})
        return status_dict

    async def health_check(self) -> Dict[str, Any]:
        db_ping_ok = False
        db_name_str = 'N/A'
        if self.mongodb_client:
            db_ping_ok = await self.mongodb_client.ping_server()
            db_name_str = self.mongodb_client.db_name or 'N/A (DB name not set)'
        total_agents_in_cache = len(self.agents)
        active_agents_in_cache = sum((1 for a in self.agents.values() if a.get('status') == 'active'))
        unhealthy_agents_count = sum((1 for agent_id in self.agents if self._check_circuit_breaker(agent_id)))
        overall_status = 'healthy'
        if not db_ping_ok:
            overall_status = 'degraded (DB ping failed)'
        elif unhealthy_agents_count > 0:
            overall_status = f'degraded ({unhealthy_agents_count} agents in circuit breaker)'
        return {'status': overall_status, 'timestamp': datetime.now(timezone.utc).isoformat(), 'mongodb_connection': 'ok' if db_ping_ok else 'failed_ping', 'stats': {'total_agents_in_registry_cache': total_agents_in_cache, 'active_agents_in_registry_cache': active_agents_in_cache, 'loaded_live_instances': len(self._agent_instances), 'agents_in_circuit_breaker': unhealthy_agents_count}, 'storage_config': {'registry_collection': self.registry_collection_name, 'logs_collection': self.logs_collection_name, 'mongodb_database': db_name_str, 'circuit_breaker_file': self.circuit_breaker_path}, 'dependencies': {'llm_service': 'ok' if self.llm_service else 'N/A', 'smart_library': 'ok' if self.smart_library else 'N/A', 'system_agent': 'ok' if self.system_agent else 'N/A', 'agent_factory': 'ok' if self.container and self.container.has('agent_factory') else 'N/A', 'tool_factory': 'ok' if self.container and self.container.has('tool_factory') else 'N/A'}}

    async def clear_logs(self) -> Dict[str, Any]:
        if self.logs_collection is None:
            msg = 'Logs collection not available. Cannot clear logs.'
            logger.warning(msg)
            return {'status': 'skipped', 'message': msg, 'deleted_count': 0}
        try:
            result = await self.logs_collection.delete_many({})
            deleted_count = result.deleted_count
            logger.info(f"Cleared {deleted_count} execution logs from MongoDB '{self.logs_collection_name}'.")
            return {'status': 'success', 'message': f'Cleared {deleted_count} logs.', 'deleted_count': deleted_count}
        except Exception as e:
            logger.error(f'Failed to clear logs from MongoDB: {e}', exc_info=True)
            return {'status': 'error', 'message': f'Failed to clear logs: {e}', 'deleted_count': 0}

    async def list_all_agents(self, agent_type: Optional[str]=None) -> List[Dict[str, Any]]:
        if not self.agents and self.registry_collection is not None:
            await self._load_registry_from_db()
        agents_list = list(self.agents.values())
        if agent_type:
            agents_list = [a for a in agents_list if a.get('type', '').lower() == agent_type.lower()]
        return [{'id': a['id'], 'name': a.get('name', 'Unnamed Agent'), 'type': a.get('type', 'UNKNOWN'), 'status': a.get('status', 'unknown'), 'description_snippet': a.get('description', 'No description')[:70] + '...' if a.get('description') else 'No description', 'capabilities_count': len(a.get('capabilities', []))} for a in agents_list]

    async def get_logs(self, limit: int=100, bus_type: Optional[str]=None, agent_id: Optional[str]=None, task_description: Optional[str]=None) -> List[Dict[str, Any]]:
        """
        Retrieves logs from the logs_collection based on provided filters.

        Args:
            limit: The maximum number of logs to return. Defaults to 100.
            bus_type: Filter logs by the 'bus_type' field.
            agent_id: Filter logs by the 'agent_id' field.
            task_description: Filter logs by the 'task_description' field (exact match).

        Returns:
            A list of log documents, sorted by timestamp in descending order.
        """
        if self.logs_collection is None:
            logger.warning('SmartAgentBus.get_logs: logs_collection is not available. Returning empty list.')
            return []
        query_filter: Dict[str, Any] = {}
        if bus_type:
            query_filter['bus_type'] = bus_type
        if agent_id:
            query_filter['agent_id'] = agent_id
        if task_description:
            query_filter['task_description'] = task_description
        projection = {'_id': 0}
        try:
            cursor = self.logs_collection.find(query_filter, projection).sort('timestamp', pymongo.DESCENDING).limit(limit)
            logs = await cursor.to_list(length=limit)
            return logs
        except Exception as e:
            logger.error(f'SmartAgentBus.get_logs: Error querying logs: {e}', exc_info=True)
            return []

# Cluster 17

class FactorioControlPanel:
    """Minimal control panel for Factorio - MCP read-only monitoring with warning display."""

    def __init__(self, mcp_server: list=None):
        logger.info('Initializing FactorioControlPanel with MCP monitoring')
        self.mcp_server = mcp_server or ['python', '-m', 'fle.env.protocols._mcp']
        self.mcp_bridge = None
        self.update_queue = Queue()
        self.is_monitoring = False
        self.warning_buffer = deque(maxlen=100)
        self.displayed_warnings = deque(maxlen=10)
        self.current_active_warnings: Set[int] = set()
        self.warning_notification_times: Dict[int, float] = {}
        self.warning_renotification_interval = 30
        self.last_warning_check = time.time()
        self.warning_levels = {'critical': {'color': 'red-500', 'icon': '🔴', 'priority': 3}, 'error': {'color': 'orange-500', 'icon': '🟠', 'priority': 2}, 'warning': {'color': 'yellow-500', 'icon': '🟡', 'priority': 1}, 'info': {'color': 'blue-500', 'icon': '🔵', 'priority': 0}}
        self.icon_manager = IconManager()
        self.inventory_items = {}
        self.last_score = 0
        self.production_history = {'timestamps': deque(maxlen=50), 'data': {}}
        self.chart = None
        self.production_samples = deque(maxlen=10)
        self.last_production_notification = {}
        self.production_notification_interval = 30
        self.material_change_threshold = 0.1
        self.coin_icon = None
        self.score_label = None
        self.status_label = None
        self.entities_label = None
        self.tick_label = None
        self.research_label = None
        self.game_view = None
        self.inventory_grid = None
        self.warnings_container = None
        self.warning_count_badge = None
        self.warnings_list = None
        self.auto_start = True

    def send_to_claude_code(self, message: str) -> bool:
        """Send message to Claude Code tmux session (similar to auto_continue.py logic)."""
        try:
            result = subprocess.run(['tmux', 'has-session', '-t', 'claude-code'], capture_output=True, text=True)
            if result.returncode != 0:
                logger.error('No claude-code tmux session found')
                return False
            logger.info('Found claude-code tmux session')
            subprocess.run(['tmux', 'send-keys', '-t', 'claude-code', message, 'C-m'], check=True)
            subprocess.run(['tmux', 'send-keys', '-t', 'claude-code', 'C-m'], check=True)
            logger.info(f"Sent '{message}' to claude-code session")
            return True
        except subprocess.CalledProcessError as e:
            logger.error(f'Failed to send to tmux: {e}')
            return False
        except Exception as e:
            logger.error(f'Unexpected error sending to tmux: {e}')
            return False

    def determine_warning_level(self, warning_text: str) -> str:
        """Determine the severity level of a warning based on its content."""
        return 'warning'

    def update_active_warnings(self, warnings_list: List[str]):
        """Update the set of currently active warnings from the latest poll."""
        new_active_warnings = {hash(warning) for warning in warnings_list}
        removed_warnings = self.current_active_warnings - new_active_warnings
        for warning_hash in removed_warnings:
            if warning_hash in self.warning_notification_times:
                del self.warning_notification_times[warning_hash]
                logger.debug(f'Warning {warning_hash} is no longer active, removed from tracking')
        self.current_active_warnings = new_active_warnings
        for warning_text in warnings_list:
            self.process_warning(warning_text, 'MCP')

    def process_warning(self, warning_text: str, source: str='MCP'):
        """Process a warning that is currently active."""
        warning_hash = hash(warning_text)
        current_time = time.time()
        timestamp = datetime.now()
        level = self.determine_warning_level(warning_text)
        warning_data = {'text': warning_text, 'source': source, 'timestamp': timestamp, 'level': level, 'hash': warning_hash}
        self.warning_buffer.append(warning_data)
        if not any((w['hash'] == warning_hash for w in self.displayed_warnings)):
            self.displayed_warnings.append(warning_data)
            logger.info(f'Added new warning to display: {warning_text[:50]}...')
        should_notify = False
        if warning_hash not in self.warning_notification_times:
            should_notify = True
            logger.info(f'New warning detected: {warning_text[:50]}...')
        else:
            time_since_last_notification = current_time - self.warning_notification_times[warning_hash]
            if time_since_last_notification >= self.warning_renotification_interval:
                should_notify = True
                logger.info(f'Re-notifying warning after {time_since_last_notification:.0f}s: {warning_text[:50]}...')
        if should_notify:
            self.submit_warning_to_claude(warning_data)
            self.warning_notification_times[warning_hash] = current_time
        self.update_warnings_display()

    def submit_warning_to_claude(self, warning_data: dict):
        """Submit a warning to Claude Code terminal."""
        warning_text = warning_data['text']
        source = warning_data['source']
        timestamp = warning_data['timestamp'].strftime('%H:%M:%S')
        formatted_message = f'[{timestamp}] {source} Warning: {warning_text}'
        logger.info(f'Submitting warning to Claude: {formatted_message}')
        success = self.send_to_claude_code(formatted_message)
        if success:
            logger.info('Successfully submitted warning to Claude')
        else:
            logger.warning('Failed to submit warning to Claude')

    def update_warnings_display(self):
        """Update the warnings display in the UI."""
        if not self.warnings_list:
            return
        self.warnings_list.clear()
        with self.warnings_list:
            sorted_warnings = sorted(self.displayed_warnings, key=lambda x: (-self.warning_levels[x['level']]['priority'], x['timestamp']), reverse=True)
            if not sorted_warnings:
                with ui.card().classes('w-full p-2 bg-gray-700 text-gray-400'):
                    ui.label('No warnings').classes('text-xs')
            else:
                for warning in sorted_warnings:
                    level_info = self.warning_levels[warning['level']]
                    warning_hash = warning['hash']
                    with ui.card().classes(f'w-full p-2 bg-gray-700 border-l-4 border-{level_info['color']}'):
                        with ui.row().classes('w-full items-start gap-2'):
                            ui.label(level_info['icon']).classes('text-sm')
                            with ui.column().classes('flex-1 gap-1'):
                                with ui.row().classes('w-full justify-between items-center'):
                                    ui.label(f'{warning['source']}').classes(f'text-xs font-bold text-{level_info['color']}')
                                    ui.label(warning['timestamp'].strftime('%H:%M:%S')).classes('text-xs text-gray-400')
                                ui.label(warning['text']).classes('text-xs text-white break-words')
                                status_parts = []
                                if warning_hash in self.current_active_warnings:
                                    status_parts.append('🟢 Active')
                                    if warning_hash in self.warning_notification_times:
                                        time_since_notification = time.time() - self.warning_notification_times[warning_hash]
                                        time_until_renotify = self.warning_renotification_interval - time_since_notification
                                        if time_until_renotify > 0:
                                            status_parts.append(f'Re-notify in {time_until_renotify:.0f}s')
                                        else:
                                            status_parts.append('Ready to re-notify')
                                else:
                                    status_parts.append('⚫ Resolved')
                                if status_parts:
                                    ui.label(' | '.join(status_parts)).classes('text-xs text-gray-500')
        if self.warning_count_badge:
            active_count = len(self.current_active_warnings)
            if active_count > 0:
                self.warning_count_badge.set_text(str(active_count))
                self.warning_count_badge.classes(remove='hidden')
            else:
                self.warning_count_badge.classes('hidden')

    def clear_warnings(self):
        """Clear all displayed warnings and their notification history."""
        self.displayed_warnings.clear()
        self.current_active_warnings.clear()
        self.warning_notification_times.clear()
        self.update_warnings_display()
        logger.info('Cleared all displayed warnings and notification history')

    def check_for_warnings(self):
        """Check for re-notification of active warnings."""
        current_time = time.time()
        if current_time - self.last_warning_check < 2.0:
            return
        self.last_warning_check = current_time
        for warning_hash in self.current_active_warnings:
            if warning_hash in self.warning_notification_times:
                time_since_notification = current_time - self.warning_notification_times[warning_hash]
                if time_since_notification >= self.warning_renotification_interval:
                    for warning in self.displayed_warnings:
                        if warning['hash'] == warning_hash:
                            logger.info(f'Re-notifying active warning: {warning['text'][:50]}...')
                            self.submit_warning_to_claude(warning)
                            self.warning_notification_times[warning_hash] = current_time
                            break
        self.update_warnings_display()

    def analyze_production_flows(self, metrics_data: dict):
        """Analyze production flow changes and generate notifications."""
        if not metrics_data:
            return
        current_time = time.time()
        timestamp = datetime.now()
        sample = {'timestamp': timestamp, 'time': current_time, 'input': metrics_data.get('input', {}), 'output': metrics_data.get('output', {})}
        self.production_samples.append(sample)
        if len(self.production_samples) < 2:
            return
        oldest_sample = self.production_samples[0]
        latest_sample = self.production_samples[-1]
        time_diff = latest_sample['time'] - oldest_sample['time']
        if time_diff < 1:
            return
        time_diff_minutes = time_diff / 60.0
        production_changes = []
        consumption_changes = []
        critical_changes = []
        for resource, latest_amount in latest_sample['output'].items():
            old_amount = oldest_sample['output'].get(resource, 0)
            if old_amount == 0:
                continue
            change = latest_amount - old_amount
            if change == 0:
                continue
            rate_per_minute = change / time_diff_minutes
            if old_amount > 0:
                percent_change = change / old_amount
            else:
                percent_change = 1.0 if change > 0 else 0
            if abs(percent_change) >= self.material_change_threshold:
                last_notified = self.last_production_notification.get(f'output_{resource}', 0)
                if current_time - last_notified >= self.production_notification_interval:
                    if change > 0:
                        production_changes.append({'resource': resource, 'change': change, 'percent': percent_change * 100, 'rate': rate_per_minute})
                    else:
                        critical_changes.append({'resource': resource, 'type': 'production_decrease', 'change': change, 'percent': percent_change * 100, 'rate': rate_per_minute})
                    self.last_production_notification[f'output_{resource}'] = current_time
        for resource, latest_amount in latest_sample['input'].items():
            old_amount = oldest_sample['input'].get(resource, 0)
            change = latest_amount - old_amount
            if change == 0:
                continue
            rate_per_minute = change / time_diff_minutes
            if old_amount > 0:
                percent_change = change / old_amount
            else:
                percent_change = 1.0 if change > 0 else 0
            if abs(percent_change) >= self.material_change_threshold:
                last_notified = self.last_production_notification.get(f'input_{resource}', 0)
                if current_time - last_notified >= self.production_notification_interval:
                    if change > 0:
                        consumption_changes.append({'resource': resource, 'change': change, 'percent': percent_change * 100, 'rate': rate_per_minute})
                    self.last_production_notification[f'input_{resource}'] = current_time
        for resource in set(latest_sample['input'].keys()) | set(latest_sample['output'].keys()):
            input_latest = latest_sample['input'].get(resource, 0)
            input_old = oldest_sample['input'].get(resource, 0)
            output_latest = latest_sample['output'].get(resource, 0)
            output_old = oldest_sample['output'].get(resource, 0)
            input_change = input_latest - input_old
            output_change = output_latest - output_old
            if input_change > 0 and output_change < 0:
                last_notified = self.last_production_notification.get(f'critical_{resource}', 0)
                if current_time - last_notified >= self.production_notification_interval:
                    critical_changes.append({'resource': resource, 'type': 'supply_deficit', 'consumption_increase': input_change, 'production_decrease': -output_change})
                    self.last_production_notification[f'critical_{resource}'] = current_time
        for change in production_changes:
            message = f'📈 {change['resource'].replace('-', ' ').title()} production {('increasing' if change['change'] > 0 else 'decreasing')} {abs(change['percent']):.1f}% ({change['rate']:.1f}/min)'
            self.process_warning(message, 'Production')
        for change in consumption_changes:
            message = f'⚡ {change['resource'].replace('-', ' ').title()} consumption {('increasing' if change['change'] > 0 else 'decreasing')} {abs(change['percent']):.1f}% ({change['rate']:.1f}/min)'
            self.process_warning(message, 'Consumption')
        for change in critical_changes:
            if change['type'] == 'production_decrease':
                message = f'⚠️ {change['resource'].replace('-', ' ').title()} production falling {abs(change['percent']):.1f}% ({change['rate']:.1f}/min)'
                self.process_warning(message, 'Production Alert')
            elif change['type'] == 'supply_deficit':
                message = f'🚨 CRITICAL: {change['resource'].replace('-', ' ').title()} - consumption up +{change['consumption_increase']}, production down -{change['production_decrease']}'
                self.process_warning(message, 'Supply Crisis')

    def process_updates(self):
        """Process updates from the MCP bridge."""
        while not self.update_queue.empty():
            update = self.update_queue.get()
            if 'warnings' in update and isinstance(update['warnings'], list):
                self.update_active_warnings(update['warnings'])
            if 'error' in update or 'message' in update:
                message = update.get('message', update.get('error', ''))
                if any((keyword in str(message).lower() for keyword in ['warning', 'error', 'failed', 'exception'])):
                    self.process_warning(str(message), 'System')
            if 'metrics' in update and update['metrics']:
                try:
                    if isinstance(update['metrics'], str):
                        metrics_data = json.loads(update['metrics'])
                    else:
                        metrics_data = update['metrics']
                    self.analyze_production_flows(metrics_data)
                except (json.JSONDecodeError, Exception) as e:
                    logger.error(f'Error analyzing metrics: {e}')
            if update['type'] == 'state_update':
                if 'inventory' in update and update['inventory']:
                    if self.inventory_items != update['inventory']:
                        self.inventory_items = update['inventory']
                        self.update_inventory_display()
                if 'inventory' in update and update['inventory']:
                    total_value = sum(update['inventory'].values())
                    score_text = f'{total_value:.0f}'
                    if self.score_label:
                        self.score_label.set_content(score_text)
                if 'entities_count' in update and self.entities_label:
                    self.entities_label.set_text(f'Entities: {update['entities_count']}')
                if 'position' in update and self.tick_label:
                    pos = update['position']
                    self.tick_label.set_text(f'Pos: ({pos.get('x', 0):.0f}, {pos.get('y', 0):.0f})')
                if 'image' in update and update['image'] and self.game_view:
                    self.game_view.set_source(update['image'])
                if 'status' in update and self.status_label:
                    if 'Connected to Factorio server' in str(update['status']):
                        self.status_label.set_text('🟢 Connected')
                    else:
                        self.status_label.set_text('🟡 ' + str(update['status'])[:30])
            elif update['type'] == 'init':
                if self.status_label:
                    self.status_label.set_text('🟢 Monitoring Active')
                coin_icon_data = self.icon_manager.get_icon_base64('coin')
                if coin_icon_data and self.coin_icon:
                    self.coin_icon.set_source(coin_icon_data)
                elif self.coin_icon:
                    self.coin_icon.classes('hidden')
            elif update['type'] == 'error':
                if self.status_label:
                    self.status_label.set_text(f'❌ {update.get('message', 'Error')[:30]}')
                self.process_warning(update.get('message', 'Unknown error'), 'System')

    def update_inventory_display(self):
        """Update the inventory grid display with sprite icons."""
        if not self.inventory_grid:
            return
        self.inventory_grid.clear()
        with self.inventory_grid:
            sorted_items = sorted(self.inventory_items.items(), key=lambda x: x[1], reverse=True)
            for item_name, count in sorted_items[:20]:
                with ui.card().classes('w-16 h-16 bg-gray-700 p-1 relative overflow-hidden'):
                    icon_data = self.icon_manager.get_icon_base64(item_name)
                    if icon_data:
                        ui.image(icon_data).classes('absolute inset-0 w-full h-full object-contain p-1')
                    else:
                        emoji = self.icon_manager.get_emoji_fallback(item_name)
                        ui.label(emoji).classes('text-2xl absolute top-1 left-1/2 transform -translate-x-1/2')
                    ui.label(str(count)).classes('text-sm text-white absolute bottom-0 right-1 bg-gray-900 px-1 rounded font-bold')
                    ui.tooltip(item_name)

    def create_ui(self):
        """Create the MCP monitoring interface with warning display."""
        if hasattr(self, '_ui_created'):
            return
        self._ui_created = True
        with ui.row().classes('w-full h-screen p-4 bg-gray-900 gap-4'):
            with ui.column().classes('w-96 flex-shrink-0 gap-2'):
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    ui.label('Factorio MCP Monitor').classes('text-xl font-bold text-center')
                    self.status_label = ui.label('⚪ Connecting to MCP...').classes('text-sm text-center mt-2')
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    ui.label('Statistics').classes('text-sm font-bold')
                    with ui.row().classes('items-center gap-1 mt-2'):
                        self.coin_icon = ui.image('').classes('w-4 h-4')
                        self.score_label = ui.html('0').classes('text-lg font-bold')
                    with ui.row().classes('w-full justify-between text-xs mt-2'):
                        self.entities_label = ui.label('Entities: 0')
                        self.tick_label = ui.label('Pos: (0, 0)')
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    with ui.row().classes('w-full justify-between items-center'):
                        with ui.row().classes('items-center gap-2'):
                            ui.label('⚠️ Warnings').classes('text-sm font-bold')
                            self.warning_count_badge = ui.label('0').classes('px-2 py-0.5 bg-red-500 text-white text-xs rounded-full hidden')
                        ui.button('Clear', on_click=self.clear_warnings).classes('text-xs px-2 py-1 bg-gray-700 hover:bg-gray-600')
                    with ui.scroll_area().classes('w-full h-48 mt-2'):
                        self.warnings_list = ui.column().classes('w-full gap-2')
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    ui.label('Inventory').classes('text-sm font-bold')
                    self.inventory_grid = ui.row().classes('w-full flex-wrap gap-2 mt-2')
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    with ui.row().classes('w-full gap-2'):
                        ui.button('Reconnect', on_click=self.reconnect_mcp).classes('flex-1')
                        ui.button('Stop', on_click=self.stop_monitoring).classes('flex-1')
                        ui.button('Test Warning', on_click=lambda: self.process_warning(f'Test warning at {datetime.now().strftime('%H:%M:%S')}', 'Test')).classes('flex-1')
                with ui.card().classes('w-full bg-gray-800 text-white'):
                    ui.label('⚙️ Warning Settings').classes('text-sm font-bold')
                    ui.label(f'Re-notification interval: {self.warning_renotification_interval}s').classes('text-xs text-gray-400 mt-1')
                    ui.label('Only active warnings are re-notified').classes('text-xs text-gray-400')
                    ui.label('Resolved warnings are automatically cleaned').classes('text-xs text-gray-400')
            with ui.column().classes('flex-1'):
                with ui.card().classes('w-full h-full bg-gray-800'):
                    ui.label('Game View').classes('text-sm font-bold text-white mb-2')
                    self.game_view = ui.image().classes('w-full h-full object-contain')
                    self.game_view.set_source('data:image/svg+xml;base64,')
            with ui.column().classes('w-80 flex-shrink-0 gap-2'):
                with ui.card().classes('w-full bg-gray-800 text-white h-full'):
                    ui.label('🚨 Live Warning Feed').classes('text-sm font-bold mb-2')
                    with ui.scroll_area().classes('w-full flex-1'):
                        self.live_warnings_feed = ui.column().classes('w-full gap-2')
                    with ui.row().classes('w-full mt-2 pt-2 border-t border-gray-700'):
                        ui.switch('Audio alerts').classes('text-xs')
                        ui.switch('Auto-clear old').classes('text-xs')
        ui.timer(0.5, self.process_updates)
        ui.timer(2.0, self.check_for_warnings)
        ui.timer(30.0, self.auto_clear_old_warnings)
        if self.auto_start:
            ui.timer(1.0, lambda: self.start_monitoring(), once=True)

    def auto_clear_old_warnings(self):
        """Automatically remove resolved warnings from display."""
        self.displayed_warnings = deque([w for w in self.displayed_warnings if w['hash'] in self.current_active_warnings], maxlen=10)
        self.update_warnings_display()
        logger.info(f'Auto-cleaned display, {len(self.current_active_warnings)} warnings remain active')

    def start_monitoring(self):
        """Start monitoring via MCP"""
        if self.is_monitoring:
            return
        logger.info('Starting MCP monitoring')
        self.is_monitoring = True
        if self.status_label:
            self.status_label.set_text('🟡 Connecting to MCP...')
        from mcp_dataloader import MCPDataBridge
        self.mcp_bridge = MCPDataBridge(update_queue=self.update_queue)
        try:
            self.mcp_bridge.start()
            logger.info('MCP bridge started successfully')
        except Exception as e:
            logger.error(f'Failed to start MCP bridge: {e}')
            if self.status_label:
                self.status_label.set_text(f'❌ Failed: {str(e)[:30]}')
            self.is_monitoring = False
            self.process_warning(f'Failed to start MCP bridge: {e}', 'System')

    def reconnect_mcp(self):
        """Reconnect to MCP server"""
        logger.info('Reconnecting to MCP')
        self.stop_monitoring()
        ui.timer(1.0, lambda: self.start_monitoring(), once=True)

    def stop_monitoring(self):
        """Stop monitoring"""
        if not self.is_monitoring:
            return
        logger.info('Stopping MCP monitoring')
        self.is_monitoring = False
        if self.mcp_bridge:
            try:
                self.mcp_bridge.stop()
            except Exception as e:
                logger.error(f'Error stopping MCP bridge: {e}')
            self.mcp_bridge = None
        if self.status_label:
            self.status_label.set_text('⏹️ Stopped')

# Cluster 21

@dataclass
class GameState:
    """Serializable Factorio game state"""
    entities: str
    inventories: List[Any]
    research: Optional[ResearchState] = field()
    timestamp: float = field(default_factory=time.time)
    namespaces: List[bytes] = field(default_factory=list)
    agent_messages: List[Any] = field(default_factory=list)

    @property
    def is_multiagent(self) -> bool:
        return len(self.inventories) > 1

    @property
    def num_agents(self) -> int:
        return len(self.inventories)

    def parse_agent_messages(data: dict) -> List[Any]:
        agent_messages = data.get('agent_messages', [])
        if not isinstance(agent_messages, list):
            raise ValueError('agent_messages must be a list')
        if agent_messages and (not all((isinstance(msg, (dict, list)) for msg in agent_messages))):
            for idx, message in enumerate(agent_messages):
                if isinstance(message, dict):
                    continue
                elif isinstance(message, list):
                    if len(message) > 0:
                        if not all((isinstance(msg, dict) for msg in message)):
                            raise ValueError(f'agent_messages[{idx}] contains non-dictionary elements')
                else:
                    raise ValueError(f'agent_messages[{idx}] must be a dictionary or a list of dictionaries, but got {type(message)}')
        return agent_messages

    @classmethod
    def from_instance(cls, instance) -> 'GameState':
        """Capture current game state from Factorio instances"""
        entities = instance.first_namespace._save_entity_state(compress=True, encode=True)
        research_state = instance.first_namespace._save_research_state()
        namespaces = []
        for namespace in instance.namespaces:
            if hasattr(namespace, 'persistent_vars'):
                serializable_vars = filter_serializable_vars(namespace.persistent_vars)
                namespaces.append(pickle.dumps(serializable_vars))
            else:
                namespaces.append(bytes())
        inventories = [namespace.inspect_inventory() for namespace in instance.namespaces]
        agent_messages = [namespace.get_messages() for namespace in instance.namespaces]
        return cls(entities=entities, inventories=inventories, namespaces=namespaces, research=research_state, agent_messages=agent_messages)

    def __repr__(self):
        readable_namespaces = [pickle.loads(namespace) for namespace in self.namespaces]
        return f'GameState(entities={self.entities}, inventories={self.inventories}, timestamp={self.timestamp}, namespace={{{readable_namespaces}}}, agent_messages={self.agent_messages})'

    @classmethod
    def parse_raw(cls, json_str: str) -> 'GameState':
        data = json.loads(json_str)
        namespaces = []
        if 'namespaces' in data:
            namespaces = [bytes.fromhex(ns) if ns else bytes() for ns in data['namespaces']]
        research = None
        if 'research' in data:
            research = ResearchState(technologies={name: TechnologyState(**tech) for name, tech in data['research']['technologies'].items()}, current_research=data['research']['current_research'], research_progress=data['research']['research_progress'], research_queue=data['research']['research_queue'], progress=data['research']['progress'] if 'progress' in data['research'] else {})
        return cls(entities=data['entities'], inventories=data['inventories'], timestamp=data['timestamp'] if 'timestamp' in data else time.time(), namespaces=namespaces, research=research, agent_messages=cls.parse_agent_messages(data))

    @classmethod
    def parse(cls, data) -> 'GameState':
        if 'namespace' in data:
            data['namespaces'] = [data['namespace']]
            data['inventories'] = [data['inventory']]
            data['agent_messages'] = []
        namespaces = []
        if 'namespaces' in data:
            namespaces = [bytes.fromhex(ns) if ns else bytes() for ns in data['namespaces']]
        research = None
        if 'research' in data:
            research = ResearchState(technologies={name: TechnologyState(**tech) for name, tech in data['research']['technologies'].items()}, current_research=data['research']['current_research'], research_progress=data['research']['research_progress'], research_queue=data['research']['research_queue'], progress=data['research']['progress'] if 'progress' in data['research'] else {})
        return cls(entities=data['entities'], inventories=data['inventories'], timestamp=data['timestamp'] if 'timestamp' in data else time.time(), namespaces=namespaces, research=research, agent_messages=cls.parse_agent_messages(data))

    def to_raw(self) -> str:
        """Convert state to JSON string"""
        data = {'entities': self.entities, 'inventories': [inventory.__dict__ if hasattr(inventory, '__dict__') else inventory for inventory in self.inventories], 'timestamp': self.timestamp, 'namespaces': [ns.hex() if ns else '' for ns in self.namespaces], 'agent_messages': self.agent_messages}
        if self.research:
            data['research'] = {'technologies': {name: asdict(tech) for name, tech in self.research.technologies.items()}, 'current_research': self.research.current_research, 'research_progress': self.research.research_progress, 'research_queue': self.research.research_queue, 'progress': self.research.progress}
        return json.dumps(data)

    def to_instance(self, instance):
        """Restore game state to a Factorio instance"""
        assert instance.num_agents == self.num_agents, f'GameState can only be restored to a multiagent instance with the same number of agents (num_agents={self.num_agents})'
        instance.first_namespace._load_entity_state(self.entities, decompress=True)
        if self.inventories:
            for namespace, inventory in zip(instance.namespaces, self.inventories):
                namespace._set_inventory(inventory)
        if self.research:
            instance.first_namespace._load_research_state(self.research)
        if self.agent_messages:
            for i in range(instance.num_agents):
                if i < len(self.agent_messages):
                    instance.namespaces[i].load_messages(self.agent_messages[i])
        if self.namespaces:
            for namespace in instance.namespaces:
                if namespace:
                    restored_vars = pickle.loads(namespace)
                if not hasattr(instance, 'persistent_vars') or instance.persistent_vars is None:
                    instance.persistent_vars = {}
                instance.persistent_vars.update(restored_vars)

class FactorioInstance:
    namespace_class = FactorioNamespace
    _cleanup_registered = False

    def __init__(self, address='localhost', fast=True, tcp_port=START_RCON_PORT, inventory: Dict={}, cache_scripts=True, all_technologies_researched=True, clear_entities=True, peaceful=True, num_agents=1, reset_speed=10, reset_paused=False, **kwargs):
        self.id = str(uuid.uuid4())[:8]
        self.num_agents = num_agents
        self.persistent_vars = {}
        self.tcp_port = tcp_port
        self.rcon_client, self.address = self.connect_to_server(address, tcp_port)
        self.fast = fast
        self._ticks_elapsed = 0
        self._is_initialised = False
        self.peaceful = peaceful
        self.namespaces = [self.namespace_class(self, i) for i in range(num_agents)]
        render_message_tool = None
        if hasattr(self.first_namespace, '_render_message'):
            render_message_tool = self.first_namespace._render_message
        self.game_control = GameControl(self.rcon_client, render_message_tool, reset_speed, reset_paused)
        self.game_control.reset_to_defaults()
        self.lua_script_manager = LuaScriptManager(self.rcon_client, cache_scripts)
        self.script_dict = {**self.lua_script_manager.lib_scripts, **self.lua_script_manager.tool_scripts}
        self.pre_tool_hooks = {}
        self.post_tool_hooks = {}
        self.lua_script_manager.load_init_into_game('initialise')
        self.lua_script_manager.setup_tools(self)
        if inventory is None:
            inventory = {}
        self.initial_inventory = inventory
        self.initialise(fast, all_technologies_researched, clear_entities)
        self.initial_score = 0
        try:
            self.first_namespace.score()
        except Exception:
            self.lua_script_manager = LuaScriptManager(self.rcon_client, False)
            self.script_dict = {**self.lua_script_manager.lib_scripts, **self.lua_script_manager.tool_scripts}
            self.lua_script_manager.setup_tools(self)
            self.initialise(fast, all_technologies_researched, clear_entities)
        self.initial_score, goal = self.first_namespace.score()
        if not FactorioInstance._cleanup_registered:
            atexit.register(self.cleanup)
            FactorioInstance._cleanup_registered = True
        self._executor = ThreadPoolExecutor(max_workers=2)

    @property
    def namespace(self):
        if len(self.namespaces) == 1:
            return self.namespaces[0]
        else:
            raise ValueError('Can only use .namespace for single-agent instances')

    @property
    def first_namespace(self) -> Optional[FactorioNamespace]:
        return self.namespaces[0] if self.namespaces else None

    @property
    def is_multiagent(self):
        return self.num_agents > 1

    def reset(self, game_state: Optional[GameState]=None, reset_position: bool=False, all_technologies_researched: bool=True, clear_entities: bool=True):
        assert not game_state or len(game_state.inventories) == self.num_agents, 'Game state must have the same number of inventories as num_agents'
        for namespace in self.namespaces:
            namespace.reset()
        if not game_state:
            inventories = [self.initial_inventory] * self.num_agents
            self.first_namespace._reset(inventories, reset_position, all_technologies_researched, clear_entities)
            if not all_technologies_researched:
                self.first_namespace._load_research_state(ResearchState(technologies={}, research_progress=0, current_research=None, research_queue=[], progress={}))
        else:
            self.first_namespace._reset(game_state.inventories, reset_position, all_technologies_researched, clear_entities)
            self.first_namespace._load_entity_state(game_state.entities, decompress=True)
            self.first_namespace._load_research_state(game_state.research)
            for i in range(min(self.num_agents, len(game_state.agent_messages))):
                self.namespaces[i].load_messages(game_state.agent_messages[i])
            for i in range(self.num_agents):
                self.namespaces[i].load(game_state.namespaces[i])
        self.game_control.reset_to_defaults()
        try:
            self.initial_score, _ = self.first_namespace.score()
        except Exception:
            self.initial_score = 0

    def set_speed(self, speed: float):
        """Set game speed (only affects speed when unpaused)"""
        self.game_control.set_speed(speed)

    def get_speed(self) -> float:
        """Get current speed setting (regardless of pause state)"""
        return self.game_control.get_speed()

    def get_elapsed_ticks(self):
        """Get the number of ticks elapsed since the game started"""
        return self.game_control.get_elapsed_ticks()

    def pause(self):
        """Pause the game (preserves speed setting)"""
        self.game_control.pause()

    def unpause(self):
        """Unpause the game (restores previous speed)"""
        self.game_control.unpause()

    def set_speed_and_unpause(self, speed: float):
        """Set speed and ensure game is unpaused - common use case"""
        self.game_control.set_speed_and_unpause(speed)

    def get_system_prompt(self, agent_idx: int=0) -> str:
        """
        Get the system prompt for the Factorio environment.
        This includes all the available actions, objects, and entities that the agent can interact with.
        We get the system prompt by loading the schema, definitions, and entity definitions from their source files.
        These are converted to their signatures - leaving out the implementations.
        :return:
        """
        execution_path = Path(os.path.dirname(os.path.realpath(__file__)))
        generator = SystemPromptGenerator(str(execution_path))
        return generator.generate_for_agent(agent_idx=agent_idx, num_agents=self.num_agents)

    @staticmethod
    def connect_to_server(address, tcp_port):
        try:
            rcon_client = RCONClient(address, tcp_port, RCON_PASSWORD)
            address = address
        except ConnectionError as e:
            print(e)
            rcon_client = RCONClient('localhost', tcp_port, RCON_PASSWORD)
            address = 'localhost'
        try:
            rcon_client.connect()
            player_count = rcon_client.send_command('/sc rcon.print(#game.players)')
            if int(player_count) == 0:
                print("WARNING: LuaPlayer hasn't been initialised into the game. Entity placement behavior _may_ be incorrect for boilers and pumps.")
        except Exception as e:
            raise ConnectionError(f'Could not connect to {address} at tcp/{tcp_port}: \n{e.args[0]}')
        print(f'Connected to {address} client at tcp/{tcp_port}.')
        return (rcon_client, address)

    def __eval_with_error(self, expr, agent_idx=0, timeout=60):
        """Evaluate an expression with a timeout, and return the result without error handling"""

        def handler(signum, frame):
            raise TimeoutError()
        signal.signal(signal.SIGALRM, handler)
        signal.alarm(timeout)
        try:
            return self.namespaces[agent_idx].eval_with_timeout(expr)
        finally:
            signal.alarm(0)

    def eval_with_error(self, expr, agent_idx=0, timeout=60):
        """Evaluate an expression with a timeout, and return the result without error handling"""
        future = self._executor.submit(self.namespaces[agent_idx].eval_with_timeout, expr)
        try:
            return future.result(timeout=timeout)
        except FutureTimeoutError:
            future.cancel()
            raise TimeoutError()
        except Exception:
            raise

    def eval(self, expr, agent_idx=0, timeout=60):
        """Evaluate several lines of input, returning the result of the last line with a timeout"""
        try:
            return self.eval_with_error(expr, agent_idx, timeout)
        except TimeoutError:
            return (-1, '', 'Error: Evaluation timed out')
        except Exception as e:
            message = e.args[0].replace('\\n', '')
            return (-1, '', f'{message}'.strip())

    def initialise(self, fast=True, all_technologies_researched=True, clear_entities=True):
        self.rcon_client.send_command(f'/sc global.fast = {str(fast).lower()}')
        self.first_namespace._create_agent_characters(self.num_agents)
        init_scripts = ['lualib_util', 'utils', 'alerts', 'connection_points', 'recipe_fluid_connection_mappings', 'serialize']
        for script_name in init_scripts:
            self.lua_script_manager.load_init_into_game(script_name)
        if self.peaceful:
            self.rcon_client.send_command('/sc global.remove_enemies()')
        inventories = [self.initial_inventory] * self.num_agents
        self.first_namespace._reset(inventories, reset_position=False, all_technologies_researched=all_technologies_researched, clear_entities=clear_entities)
        self.first_namespace._clear_collision_boxes()

    def get_warnings(self, seconds=10):
        """
        Get all alerts that have been raised before the last n seconds
        :param seconds: The number of seconds to look back
        :return:
        """
        start = timer()
        lua_response = self.rcon_client.send_command(f'/sc rcon.print(dump(global.get_alerts({seconds})))')
        alert_dict, duration = _lua2python('alerts', lua_response, start=start)
        if isinstance(alert_dict, dict):
            alerts = list(alert_dict.values())
            alert_strings = []
            for alert in alerts:
                issues = ', '.join([al.replace('_', ' ') for al in list(alert['issues'].values())])
                alert_strings.append(f'{alert['entity_name']} at {tuple(alert['position'].values())}: {issues}')
            return alert_strings
        else:
            return []

    def cleanup(self):
        if hasattr(self, 'rcon_client') and self.rcon_client:
            self.rcon_client.close()
        self.post_tool_hooks = {}
        self.pre_tool_hooks = {}
        for thread in threading.enumerate():
            if thread != threading.current_thread() and thread.is_alive() and (not thread.daemon):
                try:
                    thread.join(timeout=5)
                except Exception as e:
                    print(f'Error joining thread {thread.name}: {e}')
        if hasattr(self, '_executor'):
            self._executor.shutdown(wait=True, cancel_futures=True)

def eval_program_with_achievements(instance: Any, program: str) -> Tuple[List[str], str, bool, Dict[str, Dict[str, float]]]:
    """Evaluate a program and calculate achievements."""
    pre_flows = ProductionFlows.from_dict(instance.first_namespace._get_production_stats())
    try:
        score, goal, result = instance.eval_with_error(program, timeout=300)
        error = False
    except Exception as e:
        result = str(e)
        error = True
    post_flows = ProductionFlows.from_dict(instance.first_namespace._get_production_stats())
    achievements = calculate_achievements(pre_flows, post_flows)
    return (result.splitlines(), result, error, achievements)

def calculate_achievements(pre: ProductionFlows, post: ProductionFlows) -> Dict[str, Dict[str, float]]:
    """Calculate achievements between two production states."""
    achievements = {'static': {}, 'dynamic': {}}
    if not pre.is_valid() or not post.is_valid():
        print('Warning: Invalid production flows')
        return achievements
    post = deepcopy(post)
    new_flows = pre.get_new_flows(post)
    static_items = deepcopy(new_flows.harvested)
    for craft in new_flows.crafted:
        for item, value in craft['outputs'].items():
            static_items[item] = static_items.get(item, 0) + value
    for item in post.output:
        post_value = post.output[item]
        pre_value = pre.output.get(item, 0)
        if post_value > pre_value:
            created = post_value - pre_value
            static = static_items.get(item, 0)
            if static > 0:
                achievements['static'][item] = static
            if created > static:
                achievements['dynamic'][item] = created - static
    return achievements

class SaveResearchState(Tool):

    def __init__(self, connection, game_state):
        super().__init__(connection, game_state)

    def __call__(self) -> ResearchState:
        """
        Save the current research state of the force

        Returns:
            ResearchState: Complete research state including all technologies
        """
        state, _ = self.execute(self.player_index)
        if not isinstance(state, dict):
            raise Exception(f'Could not save research state: {state}')
        try:
            technologies = {}
            if 'technologies' in state:
                technologies = {name: TechnologyState(name=tech['name'], researched=tech['researched'], enabled=tech['enabled'], level=tech['level'], research_unit_count=tech['research_unit_count'], research_unit_energy=tech['research_unit_energy'], prerequisites=[x for x in tech['prerequisites'].values()], ingredients=[{x['name']: x['amount']} for x in tech['ingredients'].values()]) for name, tech in state['technologies'].items()}
            return ResearchState(technologies=technologies, current_research=state['current_research'] if 'current_research' in state else None, research_progress=state['research_progress'] if 'research_progress' in state else None, research_queue=[x for x in state['research_queue'].values()] if 'research_queue' in state else [], progress=state['progress'] if 'progress' in state else None)
        except Exception as e:
            print(f'Could not save technologies: {e}')
            raise e

@dataclass
class Observation:
    """Complete observation of the game state"""
    raw_text: str
    entities: List[str]
    inventory: Inventory
    research: ResearchState
    game_info: GameInfo
    score: float
    flows: ProductionFlows
    task_verification: Optional[TaskResponse]
    messages: List[AgentMessage]
    serialized_functions: List[Dict[str, Any]]
    task_info: Optional[TaskInfo]
    map_image: str

    @classmethod
    def from_dict(cls, obs_dict: Dict[str, Any]) -> 'Observation':
        """Create an Observation from a dictionary matching the gym observation space"""
        entities = obs_dict.get('entities', [])
        inventory = Inventory()
        for item in obs_dict.get('inventory', []):
            inventory[item['type']] = item['quantity']
        research = ResearchState(technologies={tech['name']: TechnologyState(name=tech['name'], researched=bool(tech['researched']), enabled=bool(tech['enabled']), level=tech['level'], research_unit_count=tech['research_unit_count'], research_unit_energy=tech['research_unit_energy'], prerequisites=tech['prerequisites'], ingredients={item['item']: item['amount'] for item in tech['ingredients']}) for tech in obs_dict.get('research', {}).get('technologies', [])}, current_research=obs_dict.get('research', {}).get('current_research'), research_progress=obs_dict.get('research', {}).get('research_progress', 0.0), research_queue=obs_dict.get('research', {}).get('research_queue', []), progress={item['name']: item['value'] for item in obs_dict.get('research', {}).get('progress', [])})
        game_info = GameInfo(tick=obs_dict.get('game_info', {}).get('tick', 0), time=obs_dict.get('game_info', {}).get('time', 0.0), speed=obs_dict.get('game_info', {}).get('speed', 0.0))
        flows_dict = obs_dict.get('flows', {})
        transformed_flows = {'input': {item['type']: item['rate'] for item in flows_dict.get('input', [])}, 'output': {item['type']: item['rate'] for item in flows_dict.get('output', [])}, 'crafted': flows_dict.get('crafted', []), 'harvested': {item['type']: item['amount'] for item in flows_dict.get('harvested', [])}, 'price_list': {item['type']: item['price'] for item in flows_dict.get('price_list', [])} if flows_dict.get('price_list') else None, 'static_items': {item['type']: item['value'] for item in flows_dict.get('static_items', [])} if flows_dict.get('static_items') else None}
        flows = ProductionFlows.from_dict(transformed_flows)
        task_verification = None
        if obs_dict.get('task_verification'):
            task_verification = TaskResponse(success=bool(obs_dict['task_verification']['success']), meta={item['key']: json.loads(item['value']) for item in obs_dict['task_verification'].get('meta', [])})
        messages = [AgentMessage(sender=msg['sender'], content=msg['content'], timestamp=msg['timestamp']) for msg in obs_dict.get('messages', [])]
        serialized_functions = obs_dict.get('serialized_functions', [])
        task_info = None
        task_dict = obs_dict.get('task_info', {})
        if task_dict.get('goal_description'):
            agent_instructions = task_dict.get('agent_instructions')
            if agent_instructions == '':
                agent_instructions = None
            task_info = TaskInfo(goal_description=task_dict.get('goal_description', ''), agent_instructions=agent_instructions, task_key=task_dict.get('task_key', ''), trajectory_length=task_dict.get('trajectory_length', 0))
        map_image = obs_dict.get('map_image', '')
        return cls(raw_text=obs_dict.get('raw_text', ''), entities=entities, inventory=inventory, research=research, game_info=game_info, score=obs_dict.get('score', 0.0), flows=flows, task_verification=task_verification, messages=messages, serialized_functions=serialized_functions, task_info=task_info, map_image=map_image)

    def to_dict(self) -> Dict[str, Any]:
        """Convert the Observation to a dictionary matching the gym observation space"""
        flows_dict = self.flows.to_dict()
        transformed_flows = {'input': [{'type': k, 'rate': v} for k, v in flows_dict['input'].items()], 'output': [{'type': k, 'rate': v} for k, v in flows_dict['output'].items()], 'crafted': flows_dict['crafted'], 'harvested': [{'type': k, 'amount': v} for k, v in flows_dict['harvested'].items()], 'price_list': [{'type': k, 'price': v} for k, v in (flows_dict['price_list'] or {}).items()], 'static_items': [{'type': k, 'value': v} for k, v in (flows_dict['static_items'] or {}).items()]}
        return {'raw_text': self.raw_text, 'map_image': self.map_image, 'entities': self.entities, 'inventory': [{'quantity': np.int32(v), 'type': k} for k, v in self.inventory.items() if v > 0], 'research': {'technologies': [{'name': tech.name, 'researched': int(tech.researched), 'enabled': int(tech.enabled), 'level': tech.level, 'research_unit_count': tech.research_unit_count, 'research_unit_energy': tech.research_unit_energy, 'prerequisites': tech.prerequisites, 'ingredients': []} for tech in self.research.technologies.values()], 'current_research': self.research.current_research if self.research.current_research is not None else 'None', 'research_progress': self.research.research_progress, 'research_queue': self.research.research_queue, 'progress': [{'name': name, 'value': value} for name, value in self.research.progress.items()]}, 'game_info': {'tick': self.game_info.tick, 'time': self.game_info.time, 'speed': self.game_info.speed}, 'score': self.score, 'flows': transformed_flows, 'task_verification': {'success': int(self.task_verification.success), 'meta': [{'key': k, 'value': json.dumps(v)} for k, v in self.task_verification.meta.items()]} if self.task_verification else {'success': 0, 'meta': []}, 'messages': [{'sender': msg.sender, 'content': msg.content, 'timestamp': msg.timestamp} for msg in self.messages], 'serialized_functions': self.serialized_functions, 'task_info': {'goal_description': self.task_info.goal_description if self.task_info else '', 'agent_instructions': self.task_info.agent_instructions or '' if self.task_info else '', 'task_key': self.task_info.task_key if self.task_info else '', 'trajectory_length': self.task_info.trajectory_length if self.task_info else 0}}

class FactorioGymEnv(gym.Env):
    """OpenAI Gym environment for Factorio"""

    def __init__(self, instance: FactorioInstance, task: Optional[TaskABC]=None, error_penalty: float=0.0, pause_after_action: bool=True, enable_vision: bool=False):
        super().__init__()
        self.instance = instance
        self.task = task
        self.error_penalty = error_penalty
        self.instance_speed = instance.get_speed()
        self.pause_after_action = pause_after_action
        self.enable_vision = enable_vision
        self.action_space = spaces.Dict({'agent_idx': spaces.Discrete(instance.num_agents), 'game_state': ObsSpaces.VERY_LONG_TEXT, 'code': ObsSpaces.LONG_TEXT})
        self.observation_space = spaces.Dict({'raw_text': ObsSpaces.LONG_TEXT, 'map_image': ObsSpaces.VERY_LONG_TEXT, 'entities': spaces.Sequence(ObsSpaces.LONG_TEXT), 'inventory': spaces.Sequence(ObsSpaces.ITEM_WITH_QUANTITY), 'research': ObsSpaces.RESEARCH, 'game_info': ObsSpaces.GAME_INFO, 'score': ObsSpaces.SCORE_FLOAT, 'flows': ObsSpaces.FLOWS, 'task_verification': ObsSpaces.TASK_VERIFICATION, 'messages': spaces.Sequence(ObsSpaces.MESSAGE), 'serialized_functions': spaces.Sequence(ObsSpaces.SERIALIZED_FUNCTION), 'task_info': ObsSpaces.TASK_INFO})
        self.current_state = None
        self.initial_score = 0
        self.last_observation = None
        self.last_message_timestamps = {i: 0.0 for i in range(instance.num_agents)}

    def get_observation(self, agent_idx: int=0, response: Optional[Response]=None) -> Observation:
        """Convert the current game state into a gym observation"""
        namespace = self.instance.namespaces[agent_idx]
        map_image = ''
        if self.enable_vision:
            map_image = namespace._render_simple().to_base64()
        entities = namespace.get_entities()
        entity_obs = [str(e) for e in entities]
        inventory_obs = namespace.inspect_inventory()
        research_obs = namespace._save_research_state()
        game_info = GameInfo(tick=self.instance.get_elapsed_ticks(), time=self.instance.get_elapsed_ticks() / 60, speed=self.instance.get_speed())
        if response:
            flows_obs = response.flows
        else:
            flows = namespace._get_production_stats()
            flows_obs = ProductionFlows.from_dict(flows)
        messages = namespace.get_messages()
        messages_obs = []
        latest_timestamp = self.last_message_timestamps[agent_idx]
        for msg in messages:
            if msg['timestamp'] > self.last_message_timestamps[agent_idx]:
                messages_obs.append(AgentMessage(sender=msg['sender'], content=msg['message'], timestamp=msg['timestamp']))
                latest_timestamp = max(latest_timestamp, msg['timestamp'])
        if messages_obs:
            self.last_message_timestamps[agent_idx] = latest_timestamp
        task_verification = None
        if response and hasattr(response, 'task'):
            task_verification = TaskResponse(success=response.task.success, meta=response.task.meta if hasattr(response.task, 'meta') else {})
        serialized_functions = []
        for func in namespace.get_functions():
            serialized_functions.append({'name': func.name, 'pickled_function': pickle.dumps(func).hex()})
        task_info = None
        if self.task:
            agent_instructions = None
            if self.task.agent_instructions:
                try:
                    agent_instructions = self.task.get_agent_instructions(agent_idx)
                except (IndexError, AttributeError):
                    agent_instructions = None
            task_info = TaskInfo(goal_description=self.task.goal_description, agent_instructions=agent_instructions, task_key=self.task.task_key, trajectory_length=self.task.trajectory_length)
        observation = Observation(raw_text=response.response if response else '', map_image=map_image, entities=entity_obs, inventory=inventory_obs, research=research_obs, game_info=game_info, score=response.score if response else 0.0, flows=flows_obs, task_verification=task_verification, messages=messages_obs, serialized_functions=serialized_functions, task_info=task_info)
        self.last_observation = observation
        return observation

    def step(self, action: Action) -> Tuple[Dict[str, Any], float, bool, bool, Dict[str, Any]]:
        """
        Execute one step in the environment

        Args:
            action: Action object

        Returns:
            observation: The new observation as a dictionary matching the observation space
            reward: The reward for this step
            terminated: Whether the episode is done
            truncated: Whether the episode is truncated
            info: Additional information
        """
        assert isinstance(action, Action)
        agent_idx = action.agent_idx
        self.instance.set_speed_and_unpause(self.instance_speed)
        if action.game_state:
            self.reset_instance(GameState.parse_raw(action.game_state.to_raw()))
        namespace = self.instance.namespaces[agent_idx]
        start_production_flows = ProductionFlows.from_dict(namespace._get_production_stats())
        initial_score, eval_time, result = self.instance.eval(action.code, agent_idx=agent_idx, timeout=60)
        error_occurred = 'error' in result.lower() or 'exception: ' in result.lower()
        task_response = task_success = None
        terminated = truncated = False
        if self.task:
            task_success = self.task.verify(initial_score, self.instance, step_statistics={})
            task_response = self.task.enhance_response_with_task_output(result, task_success)
            terminated = task_success.success
        production_score, _ = namespace.score()
        if task_success and REWARD_OVERRIDE_KEY in task_success.meta:
            reward = task_success.meta[REWARD_OVERRIDE_KEY]
        else:
            reward = production_score - initial_score
        reward = float(reward) - self.error_penalty
        output_game_state = GameState.from_instance(self.instance)
        current_flows = ProductionFlows.from_dict(namespace._get_production_stats())
        achievements = calculate_achievements(start_production_flows, current_flows)
        response = Response(code=f'```python\n{action.code}\n```', created_at=datetime.datetime.now(), score=reward, achievements=achievements, step=0, ticks=self.instance.get_elapsed_ticks(), flows=start_production_flows.get_new_flows(current_flows), response=task_response if task_response else result, task=task_success if task_success else TaskResponse(success=False, meta={}), error=error_occurred, program_id=None)
        observation = self.get_observation(action.agent_idx, response)
        info = {'error_occurred': error_occurred, 'result': result, 'ticks': self.instance.get_elapsed_ticks(), 'flows': response.flows, 'agent_idx': agent_idx, 'last_message_timestamp': self.last_message_timestamps[agent_idx], 'task_verification': task_response, 'output_game_state': output_game_state, 'achievements': achievements, 'production_score': production_score}
        if self.pause_after_action:
            self.instance.pause()
        return (observation.to_dict(), reward, terminated, truncated, info)

    def reset_instance(self, state: Optional[GameState]=None) -> None:
        """Reset the Factorio instance to a given state or initial state.

        Args:
            state: Optional[GameState] to reset to. If None, resets to initial state.
        """
        self.instance.reset(state)

    def reset(self, options: Optional[Dict[str, Any]]=None, seed: Optional[int]=None) -> Dict[str, Any]:
        """Reset the environment to initial state

        Args:
            options: dict containing 'game_state' key with Optional[GameState] value to reset to
            seed: Not used
        """
        if options is None:
            options = {}
        game_state = options.get('game_state')
        self.reset_instance(game_state)
        self.initial_score, _ = self.instance.namespaces[0].score()
        self.last_observation = None
        self.last_message_timestamps = {i: 0.0 for i in range(self.instance.num_agents)}
        observation = self.get_observation(0).to_dict()
        return observation

    def close(self):
        """Clean up resources"""
        self.instance.cleanup()

class FactorioMCPRepository:
    """
    Version control system for Factorio game states and project files using Dulwich.

    Uses .claude-code as the working directory:
    - If current directory is named .claude-code, uses it directly
    - If .claude-code exists as subdirectory, uses that
    - Otherwise creates .claude-code as a new subdirectory
    """

    def __init__(self, instance: FactorioInstance):
        current_dir = os.getcwd()
        current_dirname = os.path.basename(current_dir)
        if current_dirname == '.claude-code':
            self.repo_dir = current_dir
        else:
            claude_code_path = os.path.join(current_dir, '.claude-code')
            if os.path.exists(claude_code_path) and os.path.isdir(claude_code_path):
                self.repo_dir = os.path.abspath(claude_code_path)
            else:
                self.repo_dir = os.path.abspath(claude_code_path)
                os.makedirs(self.repo_dir, exist_ok=True)
        instance_id = instance.tcp_port
        self.instance_repo_dir = os.path.join(self.repo_dir, f'instance_{instance_id}')
        os.makedirs(self.instance_repo_dir, exist_ok=True)
        if os.path.exists(os.path.join(self.instance_repo_dir, '.git')):
            self.repo = Repo(self.instance_repo_dir)
        else:
            self.repo = Repo.init(self.instance_repo_dir)
        self.branch = b'refs/heads/main'
        self.current_branch = 'main'
        self.instance = instance
        self.branches = {'main': None}
        self.tags = {}
        self.undo_stack = []
        if not self._has_commits():
            self._init_repo()
        else:
            self._load_existing_state()

    def _has_commits(self):
        """Check if the repository has any commits"""
        try:
            refs_dict = self.repo.refs.as_dict()
            return self.branch in refs_dict
        except Exception as e:
            print(f'Error checking for commits: {str(e)}')
            return False

    def _load_existing_state(self):
        """Load existing state from disk repository"""
        try:
            refs_dict = self.repo.refs.as_dict()
            for ref_name, ref_value in refs_dict.items():
                if ref_name.startswith(b'refs/heads/'):
                    branch_name = ref_name.decode('utf-8').replace('refs/heads/', '')
                    self.branches[branch_name] = ref_value.decode('utf-8')
                elif ref_name.startswith(b'refs/tags/'):
                    tag_name = ref_name.decode('utf-8').replace('refs/tags/', '')
                    self.tags[tag_name] = ref_value.decode('utf-8')
            if self.branch in refs_dict:
                history = self.get_history(max_count=100)
                self.undo_stack = [commit['id'] for commit in history]
        except Exception as e:
            print(f'Error loading existing repository state: {str(e)}')
            if not self.branches:
                self.branches = {'main': None}

    def _init_repo(self):
        """Initialize the repository with an empty commit"""
        initial_state = GameState.from_instance(self.instance)
        self.commit(initial_state, 'Initial state', None)

    def _make_blob(self, data: str) -> Tuple[bytes, Blob]:
        """Create a blob object from string data"""
        blob = Blob.from_string(data.encode('utf-8'))
        self.repo.object_store.add_object(blob)
        return (blob.id, blob)

    def _make_blob_from_bytes(self, data: bytes) -> Tuple[bytes, Blob]:
        """Create a blob object from bytes data"""
        blob = Blob.from_string(data)
        self.repo.object_store.add_object(blob)
        return (blob.id, blob)

    def _make_tree(self, entries: Dict[str, Tuple[int, bytes]]) -> Tuple[bytes, Tree]:
        """Create a tree object from a dictionary of entries"""
        tree = Tree()
        for name, (mode, blob_id) in entries.items():
            tree.add(name.encode('utf-8'), mode, blob_id)
        self.repo.object_store.add_object(tree)
        return (tree.id, tree)

    def _scan_working_directory(self) -> Dict[str, bytes]:
        """
        Scan the instance repo directory for files to include in commits.
        Returns a dict of relative_path -> file_content_bytes
        """
        files_to_track = {}
        ignore_patterns = ['.git', '__pycache__', '*.pyc', '.DS_Store', '*.swp', '*.swo', '.factorio_mcp_repo']
        for root, dirs, files in os.walk(self.instance_repo_dir):
            dirs[:] = [d for d in dirs if d not in ignore_patterns]
            for file_name in files:
                if any((file_name.endswith(pattern.replace('*', '')) for pattern in ignore_patterns if '*' in pattern)):
                    continue
                if file_name in ignore_patterns:
                    continue
                file_path = os.path.join(root, file_name)
                rel_path = os.path.relpath(file_path, self.instance_repo_dir)
                if '.git' in rel_path:
                    continue
                try:
                    with open(file_path, 'rb') as f:
                        files_to_track[rel_path] = f.read()
                except Exception as e:
                    print(f'Warning: Could not read file {rel_path}: {str(e)}')
        return files_to_track

    def commit(self, state: GameState, message: str, policy: Optional[str]=None, include_files: bool=True) -> str:
        """
        Create a commit with the given state, message, and optionally tracked files

        Args:
            state: Game state to commit
            message: Commit message
            policy: Optional Python code that was executed
            include_files: Whether to include working directory files in the commit
        """
        state_id, state_blob = self._make_blob(state.to_raw())
        entries = {'gamestate.json': (33188, state_id)}
        if policy:
            policy_id, policy_blob = self._make_blob(policy)
            entries['policy.py'] = (33188, policy_id)
        if include_files:
            tracked_files = self._scan_working_directory()
            for file_path, file_content in tracked_files.items():
                if file_path in ['gamestate.json', 'policy.py']:
                    continue
                file_id, file_blob = self._make_blob_from_bytes(file_content)
                git_path = file_path.replace('\\', '/')
                entries[git_path] = (33188, file_id)
        tree_id, tree = self._make_tree(entries)
        commit = Commit()
        commit.tree = tree_id
        commit.author = commit.committer = b'FLE-Agent <agent@fle.local>'
        commit.commit_time = commit.author_time = int(time.time())
        commit.commit_timezone = commit.author_timezone = 0
        commit.message = message.encode('utf-8')
        try:
            refs_dict = self.repo.refs.as_dict()
            if self.branch in refs_dict:
                commit.parents = [refs_dict[self.branch]]
        except Exception as e:
            print(f'No parent commit found (this may be normal for first commit): {str(e)}')
            pass
        self.repo.object_store.add_object(commit)
        commit_id = commit.id.decode('utf-8')
        old_ref = None
        try:
            if self.branch in self.repo.refs:
                old_ref = self.repo.refs[self.branch]
        except Exception:
            pass
        self.repo.refs.set_if_equals(self.branch, old_ref, commit.id)
        self.branches[self.current_branch] = commit_id
        self.undo_stack.append(commit_id)
        try:
            self.repo.refs.pack_refs()
        except Exception as e:
            print(f'Warning: Could not pack refs: {str(e)}')
        return commit_id

    def restore_files_from_commit(self, commit_id: str) -> Dict[str, str]:
        """
        Restore files from a specific commit to the working directory.
        Returns a dict of files that were restored.
        """
        commit_id = commit_id.encode('utf-8') if isinstance(commit_id, str) else commit_id
        restored_files = {}
        try:
            try:
                commit = self.repo.object_store[commit_id]
            except KeyError:
                self.repo.object_store.add_objects_from_pack(commit_id)
                commit = self.repo.object_store[commit_id]
            tree = self.repo.object_store[commit.tree]
            for name, entry in tree.items():
                name = name.decode('utf-8')
                if name == 'gamestate.json':
                    continue
                mode, blob_id = entry
                blob = self.repo.object_store[blob_id]
                file_path = os.path.join(self.instance_repo_dir, name)
                os.makedirs(os.path.dirname(file_path), exist_ok=True)
                with open(file_path, 'wb') as f:
                    f.write(blob.data)
                restored_files[name] = f'Restored ({len(blob.data)} bytes)'
        except Exception as e:
            print(f'Error restoring files from commit {commit_id}: {str(e)}')
        return restored_files

    def tag_commit(self, name: str, commit_id: Optional[str]=None) -> str:
        """Create a named tag for a commit (default: current HEAD)"""
        if commit_id is None:
            try:
                refs_dict = self.repo.refs.as_dict()
                if self.branch in refs_dict:
                    commit_id = refs_dict[self.branch].decode('utf-8')
                else:
                    raise ValueError('No current HEAD to tag')
            except Exception as e:
                raise ValueError(f'Error getting current HEAD: {str(e)}')
        self.tags[name] = commit_id
        tag_ref = f'refs/tags/{name}'.encode('utf-8')
        commit_id_bytes = commit_id.encode('utf-8')
        self.repo.refs.add_if_new(tag_ref, commit_id_bytes)
        try:
            self.repo.refs.pack_refs()
        except Exception as e:
            print(f'Warning: Could not pack refs for tag: {str(e)}')
        return commit_id

    def get_tag(self, name: str) -> Optional[str]:
        """Get commit ID for a named tag"""
        return self.tags.get(name)

    def list_tags(self) -> Dict[str, str]:
        """List all tags and their commit IDs"""
        return self.tags

    def checkout(self, ref: str) -> str:
        """
        Checkout a specific commit, branch, or tag.
        This changes internal state AND restores files to working directory.
        """
        refs_dict = self.repo.refs.as_dict()
        if ref in self.tags:
            ref = self.tags[ref]
            tag_ref = f'refs/tags/{ref}'.encode('utf-8')
            if tag_ref in refs_dict:
                commit_id = refs_dict[tag_ref]
            else:
                commit_id = ref.encode('utf-8') if isinstance(ref, str) else ref
        elif ref in self.branches:
            self.current_branch = ref
            self.branch = f'refs/heads/{ref}'.encode('utf-8')
            if self.branch in refs_dict:
                commit_id = refs_dict[self.branch]
            else:
                print(f'Warning: Branch {ref} not found in refs')
                return None
        else:
            commit_id = ref.encode('utf-8') if isinstance(ref, str) else ref
            self.current_branch = None
        try:
            if self.current_branch:
                self.repo.refs.set_symbolic_ref(b'HEAD', self.branch)
            else:
                self.repo.refs[b'HEAD'] = commit_id
            self.repo.refs.pack_refs()
            restored = self.restore_files_from_commit(commit_id)
            if restored:
                print(f'Restored {len(restored)} files from commit')
        except Exception as e:
            print(f'Warning: Error updating HEAD reference: {str(e)}')
        return commit_id.decode('utf-8') if isinstance(commit_id, bytes) else commit_id

    def apply_to_instance(self, commit_id: Optional[str]=None) -> bool:
        """Apply a specific commit to the game instance and restore files"""
        if commit_id is None:
            try:
                refs_dict = self.repo.refs.as_dict()
                head_value = refs_dict.get(b'HEAD')
                if head_value and head_value.startswith(b'ref: '):
                    ref_name = head_value[5:]
                    if ref_name in refs_dict:
                        commit_id = refs_dict[ref_name]
                    else:
                        raise ValueError(f'Symbolic ref {ref_name.decode('utf-8')} not found')
                else:
                    commit_id = head_value
                if not commit_id:
                    raise ValueError('No current commit to apply')
            except Exception as e:
                raise ValueError(f'Error getting current HEAD: {str(e)}')
        else:
            commit_id = commit_id.encode('utf-8') if isinstance(commit_id, str) else commit_id
        try:
            try:
                commit = self.repo.object_store[commit_id]
            except KeyError:
                self.repo.object_store.add_objects_from_pack(commit_id)
                commit = self.repo.object_store[commit_id]
            tree = self.repo.object_store[commit.tree]
            if b'gamestate.json' in tree:
                state_id = tree[b'gamestate.json'][1]
                state_blob = self.repo.object_store[state_id]
                state_json = state_blob.data.decode('utf-8')
                state = GameState.parse_raw(state_json)
                self.instance.reset(game_state=state)
                self.restore_files_from_commit(commit_id)
                print('Instance reset and files restored')
                return True
        except Exception as e:
            print(f'Error applying commit {commit_id}: {str(e)}')
        return False

    def undo(self) -> Optional[str]:
        """
        Undo to the previous commit.
        Returns the commit ID that was restored, or None if no more history.
        """
        if len(self.undo_stack) <= 1:
            return None
        self.undo_stack.pop()
        if not self.undo_stack:
            return None
        prev_commit_id = self.undo_stack[-1]
        commit_id_bytes = prev_commit_id.encode('utf-8')
        try:
            old_ref = None
            if self.branch in self.repo.refs:
                old_ref = self.repo.refs[self.branch]
            self.repo.refs.set_if_equals(self.branch, old_ref, commit_id_bytes)
            if self.current_branch:
                self.branches[self.current_branch] = prev_commit_id
            if self.current_branch:
                self.repo.refs.set_symbolic_ref(b'HEAD', self.branch)
            else:
                self.repo.refs[b'HEAD'] = commit_id_bytes
            self.repo.refs.pack_refs()
        except Exception as e:
            print(f'Warning: Error updating references during undo: {str(e)}')
        return prev_commit_id

    def get_policy(self, commit_id: str) -> Optional[str]:
        """Get the policy associated with a commit"""
        commit_id = commit_id.encode('utf-8') if isinstance(commit_id, str) else commit_id
        try:
            try:
                commit = self.repo.object_store[commit_id]
            except KeyError:
                self.repo.do_pack()
                commit = self.repo.object_store[commit_id]
            try:
                tree = self.repo.object_store[commit.tree]
            except KeyError:
                self.repo.do_pack()
                tree = self.repo.object_store[commit.tree]
            if b'policy.py' in tree:
                policy_id = tree[b'policy.py'][1]
                try:
                    policy_blob = self.repo.object_store[policy_id]
                except KeyError:
                    self.repo.do_pack()
                    policy_blob = self.repo.object_store[policy_id]
                return policy_blob.data.decode('utf-8')
        except KeyError:
            pass
        except Exception as e:
            print(f'Error getting policy: {str(e)}')
        return None

    def get_file_from_commit(self, commit_id: str, file_path: str) -> Optional[str]:
        """Get a specific file from a commit"""
        commit_id = commit_id.encode('utf-8') if isinstance(commit_id, str) else commit_id
        file_path = file_path.replace('\\', '/')
        try:
            commit = self.repo.object_store[commit_id]
            tree = self.repo.object_store[commit.tree]
            file_path_bytes = file_path.encode('utf-8')
            if file_path_bytes in tree:
                mode, blob_id = tree[file_path_bytes]
                blob = self.repo.object_store[blob_id]
                return blob.data.decode('utf-8')
        except Exception as e:
            print(f'Error getting file {file_path} from commit: {str(e)}')
        return None

    def list_files_in_commit(self, commit_id: str) -> List[str]:
        """List all files tracked in a specific commit"""
        commit_id = commit_id.encode('utf-8') if isinstance(commit_id, str) else commit_id
        files = []
        try:
            commit = self.repo.object_store[commit_id]
            tree = self.repo.object_store[commit.tree]
            for name, entry in tree.items():
                files.append(name.decode('utf-8'))
        except Exception as e:
            print(f'Error listing files in commit: {str(e)}')
        return files

    def get_history(self, max_count=10) -> List[Dict[str, Any]]:
        """Get commit history"""
        history = []
        try:
            if self.branch not in self.repo.refs:
                return history
            commit_id = self.repo.refs[self.branch]
            while commit_id and len(history) < max_count:
                try:
                    try:
                        commit = self.repo.object_store[commit_id]
                    except KeyError:
                        self.repo.do_pack()
                        commit = self.repo.object_store[commit_id]
                    tree = self.repo.object_store[commit.tree]
                    file_count = len(list(tree.items()))
                    history.append({'id': commit_id.decode('utf-8') if isinstance(commit_id, bytes) else commit_id, 'message': commit.message.decode('utf-8'), 'timestamp': commit.commit_time, 'has_policy': self._has_policy(commit.tree), 'file_count': file_count})
                    if commit.parents:
                        commit_id = commit.parents[0]
                    else:
                        break
                except KeyError:
                    break
                except Exception as e:
                    print(f'Error processing commit {commit_id}: {str(e)}')
                    break
        except Exception as e:
            print(f'Error getting history: {str(e)}')
        return history

    def _has_policy(self, tree_id):
        """Check if a tree contains a policy file"""
        try:
            try:
                tree = self.repo.object_store[tree_id]
            except KeyError:
                self.repo.do_pack()
                tree = self.repo.object_store[tree_id]
            return b'policy.py' in tree
        except Exception:
            return False

    def diff_policies(self, commit_id1: str, commit_id2: str) -> Dict[str, Any]:
        """
        Compare policies between two commits.
        Returns information about the differences.
        """
        try:
            policy1 = self.get_policy(commit_id1)
            policy2 = self.get_policy(commit_id2)
            if policy1 is None and policy2 is None:
                return {'status': 'no_policies', 'message': 'Neither commit has a policy'}
            if policy1 is None:
                return {'status': 'added', 'message': 'Policy added in second commit', 'policy': policy2}
            if policy2 is None:
                return {'status': 'removed', 'message': 'Policy removed in second commit', 'policy': policy1}
            import difflib
            diff = list(difflib.unified_diff(policy1.splitlines(keepends=True), policy2.splitlines(keepends=True), fromfile=f'policy-{commit_id1[:8]}.py', tofile=f'policy-{commit_id2[:8]}.py'))
            return {'status': 'modified', 'message': 'Policy modified between commits', 'diff': ''.join(diff), 'policy1': policy1, 'policy2': policy2}
        except Exception as e:
            return {'status': 'error', 'message': f'Error comparing policies: {str(e)}'}

class UnboundedThroughputTask(TaskABC):

    def __init__(self, trajectory_length, goal_description: str, task_key: str, throughput_entity: Entity, holdout_wait_period: int, pre_holdout_wait_period: int=0, show_number_of_steps_left_in_prompt=False, use_populated_inventory=True, unlock_all_research=True, agent_instructions: Optional[List[str]]=None) -> None:
        goal_description += f'\n{INSTRUCTIONS}'
        if show_number_of_steps_left_in_prompt:
            goal_description += f'\n\nIn total you have {trajectory_length} steps to build your factory'
        starting_inventory = LAB_PLAY_POPULATED_STARTING_INVENTORY if use_populated_inventory else {}
        super().__init__(trajectory_length, starting_inventory=starting_inventory, goal_description=goal_description, task_key=task_key, all_technology_reserached=unlock_all_research, agent_instructions=agent_instructions)
        self.throughput_entity = throughput_entity
        self.holdout_wait_period = holdout_wait_period
        self.starting_game_state = None
        self.pre_holdout_wait_period = pre_holdout_wait_period
        self.show_number_of_steps_left_in_prompt = show_number_of_steps_left_in_prompt

    def verify(self, score: float, instance: FactorioInstance, step_statistics: Dict) -> TaskResponse:
        max_achieved_throughput = 0
        max_achievements = None
        while True:
            result_list, result, error, achievements = eval_program_with_achievements(program=f'sleep({self.holdout_wait_period})', instance=instance)
            if max_achievements is None:
                max_achievements = achievements
            dynamic_achievements = achievements['dynamic']
            target_throughput = dynamic_achievements.get(self.throughput_entity, 0)
            if target_throughput > max_achieved_throughput:
                max_achieved_throughput = target_throughput
                max_achievements = achievements
            else:
                break
        return TaskResponse(success=False, meta={'achievements': max_achievements})

    def _to_dict(self) -> Dict[str, Any]:
        return {'task': self.goal_description, 'throughput_entity': self.throughput_entity, 'trajectory_length': self.trajectory_length, 'starting_inventory': self.starting_inventory, 'initial_state': self.starting_game_state.to_raw() if self.starting_game_state else None, 'show_number_of_steps_left_in_prompt': self.show_number_of_steps_left_in_prompt}

    def setup_instance(self, instance):
        """Code to provision the task environment"""
        pass

    def enhance_response_with_task_output(self, response: str, task_response: TaskResponse) -> str:
        task_throughputs = task_response.meta.get('achievements', None)
        number_of_steps_left = task_response.meta.get('nr_of_steps_left', None)
        if task_throughputs:
            response += f'\n\nHere is the current throughput of your factory: {task_throughputs['dynamic']} created per 60 seconds'
        if self.show_number_of_steps_left_in_prompt and number_of_steps_left:
            response += f'\n\nYou have: {number_of_steps_left} steps left to build or expand your factory'
        return response

class ThroughputTask(TaskABC):

    def __init__(self, trajectory_length, goal_description: str, task_key: str, throughput_entity: Entity, quota: int, holdout_wait_period: int, pre_holdout_wait_period: int=0, agent_instructions: Optional[List[str]]=None):
        goal_description += f'\n{INSTRUCTIONS}'
        super().__init__(trajectory_length, starting_inventory=LAB_PLAY_POPULATED_STARTING_INVENTORY, goal_description=goal_description, task_key=task_key, all_technology_reserached=True, agent_instructions=agent_instructions)
        self.throughput_entity = throughput_entity
        self.quota = quota
        self.holdout_wait_period = holdout_wait_period
        self.starting_game_state = None
        self.pre_holdout_wait_period = pre_holdout_wait_period
        self.throughput_key = f'{throughput_entity} achieved throughput per {holdout_wait_period} seconds'

    def verify(self, score: float, instance: FactorioInstance, step_statistics: Dict) -> TaskResponse:
        max_achieved_throughput = 0
        max_achievements = None
        while True:
            result_list, result, error, achievements = eval_program_with_achievements(program=f'sleep({self.holdout_wait_period})', instance=instance)
            if max_achievements is None:
                max_achievements = achievements
            dynamic_achievements = achievements['dynamic']
            target_throughput = dynamic_achievements.get(self.throughput_entity, 0)
            if target_throughput > max_achieved_throughput:
                max_achieved_throughput = target_throughput
                max_achievements = achievements
            else:
                break
        return TaskResponse(success=max_achieved_throughput >= self.quota, meta={self.throughput_key: max_achieved_throughput, REWARD_OVERRIDE_KEY: max_achieved_throughput})

    def _to_dict(self) -> Dict[str, Any]:
        return {'task': self.goal_description, 'throughput_entity': self.throughput_entity, 'quota': self.quota, 'trajectory_length': self.trajectory_length, 'starting_inventory': self.starting_inventory, 'initial_state': self.starting_game_state.to_raw() if self.starting_game_state else None}

    def setup_instance(self, instance):
        """Code to provision the task environment"""
        pass

    def enhance_response_with_task_output(self, response: str, task_response: TaskResponse) -> str:
        task_throughput = task_response.meta.get(self.throughput_key, None)
        if task_throughput:
            response += f'\n\nThe current throughput of your factory is {task_throughput} of {self.throughput_entity} created per 60 seconds'
        return response

