class Vigil:
    vectordb: Optional[VectorDB] = None
    embedder: Optional[Callable] = None

    def __init__(self, config_path: str):
        self._config = Config(config_path)
        self._initialize_vectordb()
        self._initialize_embedder()
        self._input_scanners: List[BaseScanner] = self._setup_scanners(self._config.get_scanner_names('input_scanners'))
        self._output_scanners: List[BaseScanner] = self._setup_scanners(self._config.get_scanner_names('output_scanners'))
        self.canary_tokens = CanaryTokens()
        self.input_scanner = self._create_manager(name='input', scanners=self._input_scanners)
        self.output_scanner = self._create_manager(name='output', scanners=self._output_scanners)

    def _initialize_embedder(self):
        full_config = self._config.get_general_config()
        params = full_config.get('embedding', {})
        self.embedder = Embedder(**params)

    def _initialize_vectordb(self):
        full_config = self._config.get_general_config()
        params = full_config.get('vectordb', {})
        params.update(full_config.get('embedding', {}))
        self.vectordb = VectorDB(**params)

    def _setup_scanners(self, scanner_names: List[str]) -> List[BaseScanner]:
        scanners = []
        for name in scanner_names:
            try:
                metadata = ScannerRegistry.get_scanner_metadata(name)
            except ValueError as err:
                logger.error(err)
                raise err
            scanner_config = None
            vectordb = None
            embedder = None
            if metadata.get('requires_config', False):
                scanner_config = self._config.get_scanner_config(name)
            if metadata.get('requires_vectordb', False):
                vectordb = self.vectordb
            if metadata.get('requires_embedding', False):
                embedder = self.embedder
            scanner = ScannerRegistry.create_scanner(name=name, config=scanner_config, vectordb=vectordb, embedder=embedder)
            scanners.append(scanner)
        return scanners

    def _create_manager(self, name: str, scanners: List[BaseScanner]) -> Manager:
        manager_config = self._config.get_general_config()
        auto_update = manager_config.get('auto_update', {}).get('enabled', False)
        update_threshold = int(manager_config.get('auto_update', {}).get('threshold', 3))
        return Manager(name=name, scanners=scanners, auto_update=auto_update, update_threshold=update_threshold, db_client=self.vectordb if auto_update else None)

    @staticmethod
    def from_config(config_path: str) -> 'Vigil':
        return Vigil(config_path=config_path)

# Cluster 7

class VectorDB:

    def __init__(self, model: str, collection: str, db_dir: str, n_results: int, openai_key: Optional[str]=None):
        """ Initialize Chroma vector db client """
        self.name = 'database:vector'
        if model == 'openai':
            logger.info('Using OpenAI embedding function')
            self.embed_fn = embedding_functions.OpenAIEmbeddingFunction(api_key=openai_key, model_name='text-embedding-ada-002')
        else:
            logger.info(f'Using SentenceTransformer embedding function: {config_dict['embed_fn']}')
            self.embed_fn = embedding_functions.SentenceTransformerEmbeddingFunction(model_name=model)
        self.collection = collection
        self.db_dir = db_dir
        self.n_results = int(n_results)
        if not hasattr(self.embed_fn, '__call__'):
            logger.error('Embedding function is not callable')
            raise ValueError('Embedding function is not a function')
        self.client = chromadb.PersistentClient(path=self.db_dir, settings=Settings(anonymized_telemetry=False, allow_reset=True))
        self.collection = self.get_or_create_collection(self.collection)
        logger.success('Loaded database')

    def get_or_create_collection(self, name: str):
        logger.info(f'Using collection: {name}')
        self.collection = self.client.get_or_create_collection(name=name, embedding_function=self.embed_fn, metadata={'hnsw:space': 'cosine'})
        return self.collection

    def add_texts(self, texts: List[str], metadatas: List[dict]):
        success = False
        logger.info(f'Adding {len(texts)} texts')
        ids = [uuid4_str() for _ in range(len(texts))]
        try:
            self.collection.add(documents=texts, metadatas=metadatas, ids=ids)
            success = True
        except Exception as err:
            logger.error(f'Failed to add texts to collection: {err}')
        return (success, ids)

    def add_embeddings(self, texts: List[str], embeddings: List[List], metadatas: List[dict]):
        success = False
        logger.info(f'Adding {len(texts)} embeddings')
        ids = [uuid4_str() for _ in range(len(texts))]
        try:
            self.collection.add(documents=texts, embeddings=embeddings, metadatas=metadatas, ids=ids)
            success = True
        except Exception as err:
            logger.error(f'Failed to add texts to collection: {err}')
        return (success, ids)

    def query(self, text: str):
        logger.info(f'Querying database for: {text}')
        try:
            return self.collection.query(query_texts=[text], n_results=self.n_results)
        except Exception as err:
            logger.error(f'Failed to query database: {err}')

def uuid4_str():
    return str(uuid4())

